window.PAGE_MODULES = {"admin-guide":"    <article class=\"ebook-page admin-guide-page\" id=\"admin-guide\">\n      <div class=\"part-lead-header\">\n        <span class=\"part-tag\">PHẦN V · CHUYÊN ĐỀ THỰC HÀNH ỨNG DỤNG</span>\n        <h2>Số Hóa Quy Trình: Từ Hồ Sơ Giấy Đến Quy Trình Số Có Thể Kiểm Tra</h2>\n        <p>Guideline dùng AI coding agent để thiết kế prototype hành chính an toàn: hiểu quy trình trước, khóa quyền và dữ liệu, kiểm thử bằng tình huống thật, rồi thí điểm có người chịu trách nhiệm.</p>\n      </div>\n\n      <!-- HERO SECTION -->\n      <section class=\"hero\" id=\"admin-hero\" style=\"border-radius: 20px; margin-bottom: 24px;\">\n        <div>\n          <p class=\"eyebrow\">CHUYÊN ĐỀ THỰC HÀNH · CẬP NHẬT 2026</p>\n          <h1>Từ hồ sơ giấy đến quy trình số <em>có thể kiểm tra.</em></h1>\n          <p class=\"lead\">Guideline dùng AI coding agent để thiết kế prototype hành chính an toàn: hiểu quy trình trước, khóa quyền và dữ liệu, kiểm thử bằng tình huống thật, rồi thí điểm có người chịu trách nhiệm.</p>\n          <div class=\"actions\">\n            <a class=\"btn primary\" href=\"#gate-1\">Xem lộ trình 8 cổng →</a>\n            <a class=\"btn ghost\" href=\"#templates\">Tải bộ mẫu</a>\n          </div>\n          <div class=\"stats\">\n            <span><b>8</b><small>cổng kiểm soát</small></span>\n            <span><b>5</b><small>mẫu tải về</small></span>\n            <span><b>1</b><small>ca xuyên suốt</small></span>\n          </div>\n        </div>\n        <div class=\"case-window\">\n          <div class=\"window-head\">\n            <i></i><i></i><i></i><span>hoso-noibo.local</span>\n          </div>\n          <div class=\"window-body\">\n            <p>HỒ SƠ #XN-2026-0142</p>\n            <h2>Đề nghị cấp giấy xác nhận</h2>\n            <div class=\"status-line\"><b>Đang thẩm định</b><span>Còn 14 giờ SLA</span></div>\n            <ol>\n              <li class=\"done\"><b>1</b><span>Tiếp nhận<small>08:31 · Minh Anh</small></span></li>\n              <li class=\"done\"><b>2</b><span>Kiểm tra hồ sơ<small>09:04 · Có log</small></span></li>\n              <li class=\"active\"><b>3</b><span>Thẩm định<small>Đang xử lý</small></span></li>\n              <li><b>4</b><span>Phê duyệt<small>Chưa bắt đầu</small></span></li>\n            </ol>\n            <div class=\"audit-note\"><b>Nhật ký bất biến</b><span>Ai · làm gì · khi nào · lý do</span></div>\n          </div>\n        </div>\n      </section>\n\n      <!-- GUARDRAILS -->\n      <section class=\"guardrail\" style=\"border-radius: 14px; overflow: hidden; margin-bottom: 30px; border: 1px solid var(--line);\">\n        <div><b>Prototype ≠ hệ thống chính thức</b><span>Không đưa hồ sơ thật vào app thử nghiệm.</span></div>\n        <div><b>AI đề xuất ≠ quyết định</b><span>Phê duyệt thuộc người có thẩm quyền.</span></div>\n        <div><b>Chạy được ≠ sẵn sàng</b><span>Phải có UAT, log, sao lưu và chủ sở hữu.</span></div>\n      </section>\n\n      <!-- ROADMAP -->\n      <section class=\"section intro\" id=\"roadmap\" style=\"padding: 20px 0;\">\n        <header class=\"section-head\">\n          <p class=\"eyebrow dark\">BẢN ĐỒ TRIỂN KHAI</p>\n          <h2>8 cổng kiểm soát — qua cổng bằng bằng chứng</h2>\n          <p>Mỗi giai đoạn tạo một artifact có thể đọc, duyệt và kiểm tra. “AI đã làm xong” không phải bằng chứng hoàn thành.</p>\n        </header>\n        <div class=\"roadmap\">\n          <a href=\"#gate-1\"><b>01</b><span>Chọn quy trình<small>Phiếu khởi động</small></span></a>\n          <a href=\"#gate-2\"><b>02</b><span>Vẽ AS-IS<small>Bản đồ hiện trạng</small></span></a>\n          <a href=\"#gate-3\"><b>03</b><span>Thiết kế TO-BE<small>Trạng thái &amp; SLA</small></span></a>\n          <a href=\"#gate-4\"><b>04</b><span>Khóa dữ liệu<small>Quyền &amp; rủi ro</small></span></a>\n          <a href=\"#gate-5\"><b>05</b><span>Đặc tả<small>Spec &amp; acceptance</small></span></a>\n          <a href=\"#gate-6\"><b>06</b><span>Làm prototype<small>Plan → code</small></span></a>\n          <a href=\"#gate-7\"><b>07</b><span>UAT &amp; an toàn<small>Bằng chứng test</small></span></a>\n          <a href=\"#gate-8\"><b>08</b><span>Thí điểm<small>Go-live &amp; handoff</small></span></a>\n        </div>\n        <div class=\"progress\">\n          <div><span>Tiến độ guideline</span><strong id=\"progress-label\">0/8 cổng</strong></div>\n          <i><b id=\"progress-bar\"></b></i>\n          <p id=\"progress-message\">Bắt đầu bằng một quy trình nhỏ, ổn định và có chủ sở hữu.</p>\n        </div>\n      </section>\n\n      <!-- CASE STUDY -->\n      <section class=\"section case-study\" id=\"case\" style=\"padding: 20px 0;\">\n        <header class=\"section-head\">\n          <p class=\"eyebrow dark\">CA XUYÊN SUỐT</p>\n          <h2>“Đề nghị cấp giấy xác nhận nội bộ”</h2>\n          <p>Đủ phức tạp để học phân quyền và phê duyệt, nhưng đủ nhỏ để hoàn thành prototype trong workshop.</p>\n        </header>\n        <div class=\"case-grid\">\n          <article>\n            <span>TRƯỚC</span>\n            <h3>Email + file rời</h3>\n            <ul>\n              <li>Không biết hồ sơ đang ở ai.</li>\n              <li>Thiếu thành phần phát hiện muộn.</li>\n              <li>Khó đo thời gian xử lý.</li>\n              <li>Không lưu lý do trả lại.</li>\n            </ul>\n          </article>\n          <article class=\"target\">\n            <span>SAU</span>\n            <h3>Một luồng có kiểm soát</h3>\n            <ul>\n              <li>Mỗi hồ sơ có mã và trạng thái.</li>\n              <li>Validation ngay khi tiếp nhận.</li>\n              <li>SLA theo từng bước.</li>\n              <li>Mọi thay đổi có người và thời điểm.</li>\n            </ul>\n          </article>\n          <article>\n            <span>KHÔNG LÀM V1</span>\n            <h3>Khóa phạm vi</h3>\n            <ul>\n              <li>Không ký số thật.</li>\n              <li>Không kết nối CSDL thật.</li>\n              <li>Không gửi SMS/email thật.</li>\n              <li>Không để AI tự phê duyệt.</li>\n            </ul>\n          </article>\n        </div>\n        <div class=\"flow\">\n          <span>Nộp nháp</span><i>→</i><span>Đã tiếp nhận</span><i>→</i><span>Đang thẩm định</span><i>→</i><span>Chờ phê duyệt</span><i>→</i><span>Hoàn tất</span><b>↘ Yêu cầu bổ sung ↗</b>\n        </div>\n      </section>\n\n      <!-- 8 GATES CHI TIẾT -->\n      <section class=\"section gates\" aria-label=\"Tám cổng kiểm soát\" style=\"padding: 20px 0;\">\n        <!-- GATE 1 -->\n        <article class=\"gate\" id=\"gate-1\">\n          <header>\n            <b>01</b>\n            <div>\n              <p>DISCOVER · 60–90 PHÚT</p>\n              <h2>Chọn đúng quy trình để thí điểm</h2>\n              <span>Ưu tiên việc lặp lại, quy tắc ổn định, dữ liệu giả lập được và có chủ sở hữu nghiệp vụ.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>Thu thập tối thiểu</h3>\n              <ul>\n                <li>Mục đích và căn cứ nội bộ/pháp lý.</li>\n                <li>Điểm bắt đầu, kết thúc, tần suất.</li>\n                <li>Người nộp, tiếp nhận, xử lý, phê duyệt.</li>\n                <li>Đầu vào, đầu ra và thời hạn.</li>\n                <li>5 ca: thường, thiếu, trễ, từ chối, hủy.</li>\n              </ul>\n            </section>\n            <section>\n              <h3>Chấm điểm 0–2</h3>\n              <div class=\"chips\">\n                <span>Lặp lại nhiều</span><span>Quy tắc rõ</span><span>Chủ quy trình rõ</span><span>Dữ liệu giả được</span><span>Ít tích hợp</span><span>Rủi ro thấp–vừa</span>\n              </div>\n              <p class=\"note\" style=\"margin-top: 10px;\">Chọn khi tổng ≥ 8/12 và “chủ quy trình” không bằng 0.</p>\n            </section>\n            <section class=\"wide\">\n              <h3>Điều kiện qua cổng</h3>\n              <div class=\"checks\">\n                <label><input type=\"checkbox\"> Có chủ quy trình</label>\n                <label><input type=\"checkbox\"> Có 5 hồ sơ giả/ẩn danh</label>\n                <label><input type=\"checkbox\"> Có mục tiêu đo được</label>\n                <label><input type=\"checkbox\"> Có “không làm v1”</label>\n              </div>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> PHIEU_KHOI_DONG.md</span>\n            <button class=\"figure-btn\" data-complete=\"1\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 2 -->\n        <article class=\"gate\" id=\"gate-2\">\n          <header>\n            <b>02</b>\n            <div>\n              <p>MAP AS-IS · 90 PHÚT</p>\n              <h2>Vẽ đúng hiện trạng, kể cả đường vòng</h2>\n              <span>Ghi cả bước chờ, trả lại, bổ sung, ngoại lệ và thao tác ngoài hệ thống.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>6 câu hỏi</h3>\n              <ol>\n                <li>Ai kích hoạt quy trình?</li>\n                <li>Thông tin nào bắt buộc?</li>\n                <li>Ai được sửa ở từng bước?</li>\n                <li>Khi thiếu/sai thì quay về đâu?</li>\n                <li>Quá hạn cảnh báo ai?</li>\n                <li>Bằng chứng nào chứng minh đã xử lý?</li>\n              </ol>\n            </section>\n            <section>\n              <h3>Mẫu một bước</h3>\n              <div class=\"mini-table\">\n                <b>Trường</b><b>Ví dụ</b>\n                <span>Tác nhân</span><span>Văn thư</span>\n                <span>Đầu vào</span><span>Phiếu + tệp</span>\n                <span>Quy tắc</span><span>Đủ 4 thành phần</span>\n                <span>Đầu ra</span><span>Mã tiếp nhận</span>\n                <span>Ngoại lệ</span><span>Yêu cầu bổ sung</span>\n              </div>\n            </section>\n            <section class=\"wide\">\n              <p class=\"callout\">Đo riêng <b>thời gian xử lý</b> và <b>thời gian chờ</b>. Nút thắt thường nằm ở hồ sơ chờ giữa hai vai trò.</p>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> AS_IS.md + 5 tình huống</span>\n            <button class=\"figure-btn\" data-complete=\"2\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 3 -->\n        <article class=\"gate\" id=\"gate-3\">\n          <header>\n            <b>03</b>\n            <div>\n              <p>DESIGN TO-BE · 120 PHÚT</p>\n              <h2>Thiết kế trạng thái và SLA trước màn hình</h2>\n              <span>Mô hình trạng thái quyết định hồ sơ đi đâu, ai chịu trách nhiệm và điều gì được phép.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>Mỗi trạng thái trả lời</h3>\n              <ul>\n                <li>Ai đang chịu trách nhiệm?</li>\n                <li>Hành động tiếp theo hợp lệ?</li>\n                <li>Điều kiện chuyển trạng thái?</li>\n                <li>SLA bắt đầu/dừng khi nào?</li>\n                <li>Được quay lui, hủy, mở lại không?</li>\n              </ul>\n            </section>\n            <section>\n              <h3>Đúng và sai</h3>\n              <div class=\"do-dont\">\n                <div><b>NÊN</b><span>Đang thẩm định → Chờ phê duyệt khi checklist đủ và có kết luận.</span></div>\n                <div><b>TRÁNH</b><span>Nút “Cập nhật” cho phép chọn bất kỳ trạng thái nào.</span></div>\n              </div>\n            </section>\n            <section class=\"wide\">\n              <div class=\"checks\">\n                <label><input type=\"checkbox\"> Tên trạng thái rõ</label>\n                <label><input type=\"checkbox\"> Có bổ sung/từ chối/hủy</label>\n                <label><input type=\"checkbox\"> SLA có điểm bắt đầu/dừng</label>\n                <label><input type=\"checkbox\"> Mỗi bước có một chủ trách nhiệm</label>\n              </div>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> TO_BE.md + STATE_MACHINE.md</span>\n            <button class=\"figure-btn\" data-complete=\"3\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 4 -->\n        <article class=\"gate\" id=\"gate-4\">\n          <header>\n            <b>04</b>\n            <div>\n              <p>DATA &amp; ACCESS · 90 PHÚT</p>\n              <h2>Khóa dữ liệu và quyền trước khi code</h2>\n              <span>Thu thập tối thiểu, phân quyền theo vai trò và log mọi thao tác có hậu quả.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>4 mức dữ liệu thực hành</h3>\n              <div class=\"risks\">\n                <span class=\"r1\"><b>Công khai</b>Đã được phép công bố.</span>\n                <span class=\"r2\"><b>Nội bộ</b>Quy trình, phân công.</span>\n                <span class=\"r3\"><b>Nhạy cảm</b>Định danh, liên hệ.</span>\n                <span class=\"r4\"><b>Hạn chế</b>Y tế, tài chính, kỷ luật, secret.</span>\n              </div>\n            </section>\n            <section>\n              <h3>Ma trận quyền tối thiểu</h3>\n              <div class=\"permission\">\n                <div><b>Vai trò</b><b>Xem</b><b>Sửa</b><b>Duyệt</b></div>\n                <div><span>Người nộp</span><span>Hồ sơ mình</span><span>Nháp/bổ sung</span><span>—</span></div>\n                <div><span>Chuyên viên</span><span>Được giao</span><span>Kết luận</span><span>—</span></div>\n                <div><span>Lãnh đạo</span><span>Chờ duyệt</span><span>Ý kiến</span><span>Có</span></div>\n              </div>\n            </section>\n            <section class=\"wide\">\n              <p class=\"warning\"><b>Không dán vào agent:</b> hồ sơ thật, CCCD, thông tin sức khỏe/tài chính, mật khẩu, API key, cookie, dữ liệu chưa được phép xử lý. Hệ thống chính thức phải qua pháp chế, an toàn thông tin và kiến trúc của đơn vị.</p>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> DATA_DICTIONARY.md + MA_TRAN_QUYEN.csv</span>\n            <button class=\"figure-btn\" data-complete=\"4\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 5 -->\n        <article class=\"gate\" id=\"gate-5\">\n          <header>\n            <b>05</b>\n            <div>\n              <p>SPECIFY · 120 PHÚT</p>\n              <h2>Viết đặc tả để AI không được phép đoán</h2>\n              <span>Đặc tả nói cái gì/vì sao; kế hoạch kỹ thuật nói làm thế nào. Chủ nghiệp vụ duyệt đặc tả.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>Spec 10 phần</h3>\n              <ol>\n                <li>Bối cảnh, mục tiêu</li>\n                <li>Vai trò</li>\n                <li>Phạm vi/không làm</li>\n                <li>Luồng chính</li>\n                <li>Ngoại lệ</li>\n                <li>Trạng thái/SLA</li>\n                <li>Dữ liệu/validation</li>\n                <li>Quyền/audit</li>\n                <li>Acceptance criteria</li>\n                <li>Rủi ro/câu hỏi mở</li>\n              </ol>\n            </section>\n            <section>\n              <h3>Given–When–Then</h3>\n              <div class=\"code\">\n                <b>AC-07 · Yêu cầu bổ sung</b>\n                <pre>Given hồ sơ “Đang thẩm định”\nAnd vai trò Chuyên viên\nWhen nhập lý do và gửi\nThen trạng thái “Chờ bổ sung”\nAnd người nộp thấy lý do\nAnd log ghi người, lúc, cũ/mới</pre>\n              </div>\n            </section>\n            <section class=\"wide\">\n              <div class=\"prompt\" id=\"prompt-spec\">Bạn là business analyst hỗ trợ, không tự quyết định nghiệp vụ. Đọc AS_IS.md, TO_BE.md, DATA_DICTIONARY.md và MA_TRAN_QUYEN.csv. Liệt kê mâu thuẫn/câu hỏi mở trước. Soạn SPEC.md theo 10 phần; mỗi yêu cầu có mã; acceptance dùng Given–When–Then; mọi chuyển trạng thái nêu vai trò, điều kiện, log và lỗi. Chưa viết code.</div>\n              <button class=\"copy\" data-copy=\"prompt-spec\">Sao chép prompt</button>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> SPEC.md được chủ nghiệp vụ duyệt</span>\n            <button class=\"figure-btn\" data-complete=\"5\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 6 -->\n        <article class=\"gate\" id=\"gate-6\">\n          <header>\n            <b>06</b>\n            <div>\n              <p>PROTOTYPE · 1–3 NGÀY</p>\n              <h2>Plan → code theo lát cắt</h2>\n              <span>Mỗi lát cắt chạy xuyên từ UI đến dữ liệu giả và có test; luồng chính trước ngoại lệ.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>4 lát cắt</h3>\n              <ol>\n                <li><b>Tiếp nhận:</b> tạo, validate, mã hồ sơ.</li>\n                <li><b>Xử lý:</b> phân công, thẩm định, bổ sung.</li>\n                <li><b>Phê duyệt:</b> duyệt/từ chối, lý do, log.</li>\n                <li><b>Quản trị:</b> SLA, lọc, báo cáo giả.</li>\n              </ol>\n            </section>\n            <section>\n              <h3>Kỷ luật phiên</h3>\n              <ul>\n                <li>Đọc SPEC + AGENTS.</li>\n                <li>Lập plan, nêu file; chưa code.</li>\n                <li>Duyệt một lát cắt; giới hạn workspace.</li>\n                <li>Xem diff, chạy test, lưu bằng chứng.</li>\n                <li>Checkpoint trước lát cắt mới.</li>\n              </ul>\n            </section>\n            <section class=\"wide\">\n              <div class=\"prompt\" id=\"prompt-build\">Đọc SPEC.md và AGENTS.md. Chỉ triển khai lát cắt “Tiếp nhận hồ sơ” gồm AC-01 đến AC-05 bằng dữ liệu giả. Lập plan tối đa 6 bước, nêu file, migration, test tự động và test thao tác. Không làm phân công/phê duyệt/báo cáo. Chờ tôi duyệt. Sau triển khai, báo từng AC đạt/chưa đạt và bằng chứng.</div>\n              <button class=\"copy\" data-copy=\"prompt-build\">Sao chép prompt</button>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> Prototype + diff + test log</span>\n            <button class=\"figure-btn\" data-complete=\"6\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 7 -->\n        <article class=\"gate\" id=\"gate-7\">\n          <header>\n            <b>07</b>\n            <div>\n              <p>VERIFY &amp; UAT · 1–2 NGÀY</p>\n              <h2>Kiểm thử quyền, ngoại lệ và truy vết</h2>\n              <span>Happy path chỉ là điểm bắt đầu; lỗi nguy hiểm nhất là sai quyền và thiếu bằng chứng.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>6 nhóm test</h3>\n              <div class=\"chips\">\n                <span>Luồng chính</span><span>Dữ liệu sai/thiếu</span><span>Chuyển trạng thái</span><span>Phân quyền</span><span>Audit &amp; SLA</span><span>Restore</span>\n              </div>\n            </section>\n            <section>\n              <h3>Test quyền âm</h3>\n              <ul>\n                <li>Không xem hồ sơ người khác.</li>\n                <li>Không tự xử lý và tự duyệt.</li>\n                <li>URL/API trực tiếp vẫn bị từ chối.</li>\n                <li>Hồ sơ hoàn tất không sửa im lặng.</li>\n                <li>Log nghiệp vụ không thể xóa/sửa.</li>\n              </ul>\n            </section>\n            <section class=\"wide\">\n              <div class=\"checks\">\n                <label><input type=\"checkbox\"> Mỗi test có mã/người chạy</label>\n                <label><input type=\"checkbox\"> Có ảnh/log bằng chứng</label>\n                <label><input type=\"checkbox\"> Lỗi có mức độ/owner</label>\n                <label><input type=\"checkbox\"> Chủ nghiệp vụ ký UAT</label>\n              </div>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> UAT_HANH_CHINH.md + báo lỗi</span>\n            <button class=\"figure-btn\" data-complete=\"7\">Đánh dấu qua cổng</button>\n          </footer>\n        </article>\n\n        <!-- GATE 8 -->\n        <article class=\"gate\" id=\"gate-8\">\n          <header>\n            <b>08</b>\n            <div>\n              <p>PILOT &amp; HANDOFF · 1–4 TUẦN</p>\n              <h2>Thí điểm hẹp, có rollback và người vận hành</h2>\n              <span>Go-live là quyết định có chủ sở hữu, phạm vi, giám sát, hỗ trợ và phương án quay lại.</span>\n            </div>\n          </header>\n          <div class=\"gate-body\">\n            <section>\n              <h3>Pre-flight</h3>\n              <ul>\n                <li>Chủ hệ thống, dữ liệu, hỗ trợ.</li>\n                <li>HTTPS, môi trường, secret server-side.</li>\n                <li>Backup đã restore thử.</li>\n                <li>Log, cảnh báo, SLA hỗ trợ.</li>\n                <li>Hướng dẫn người dùng/quản trị.</li>\n                <li>Phạm vi và tiêu chí dừng.</li>\n              </ul>\n            </section>\n            <section>\n              <h3>Đo sau thí điểm</h3>\n              <div class=\"metrics\">\n                <span><b>Tỷ lệ đúng hạn</b>Đúng hạn / tổng</span>\n                <span><b>First-time-right</b>Không bổ sung / tổng</span>\n                <span><b>Lead time</b>Tiếp nhận → hoàn tất</span>\n                <span><b>Lỗi quyền</b>Phải bằng 0</span>\n              </div>\n            </section>\n            <section class=\"wide\">\n              <div class=\"decision\">\n                <article><b>MỞ RỘNG</b><p>Chỉ số đạt, không lỗi nghiêm trọng, đủ vận hành.</p></article>\n                <article><b>GIỮ PHẠM VI</b><p>Có giá trị nhưng cần ổn định thêm.</p></article>\n                <article><b>DỪNG / ROLLBACK</b><p>Sai quyền, mất dữ liệu hoặc không truy vết.</p></article>\n              </div>\n            </section>\n          </div>\n          <footer>\n            <span><b>Artifact</b> GO_LIVE.md + HANDOFF.md</span>\n            <button class=\"figure-btn\" data-complete=\"8\">Hoàn thành guideline</button>\n          </footer>\n        </article>\n      </section>\n\n      <!-- THƯ VIỆN PROMPT ĐẦY ĐỦ 8 MẪU -->\n      <section class=\"section prompt-library\" id=\"prompts\" style=\"padding: 20px 0;\">\n        <header class=\"section-head\">\n          <p class=\"eyebrow dark\">THƯ VIỆN PROMPT</p>\n          <h2>Giao đúng vai cho AI</h2>\n          <p>Prompt không thay artifact. Đính kèm đúng file, yêu cầu câu hỏi mở và giới hạn “chưa sửa” hoặc “chỉ sửa lát cắt”.</p>\n        </header>\n        <div class=\"prompt-grid\">\n          <details open>\n            <summary><span>01</span>Bóc tách AS-IS</summary>\n            <div>\n              <p id=\"p1\">Từ biên bản phỏng vấn, lập bảng: bước, tác nhân, đầu vào, quy tắc, đầu ra, thời gian xử lý/chờ, công cụ, ngoại lệ và bằng chứng. Không tự điền thiếu; tạo danh sách câu hỏi xác minh.</p>\n              <button class=\"copy\" data-copy=\"p1\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>02</span>Phản biện TO-BE</summary>\n            <div>\n              <p id=\"p2\">Phản biện TO_BE.md: tìm trạng thái mồ côi, chuyển trạng thái thiếu quyền/điều kiện, SLA thiếu điểm bắt đầu-dừng, vòng lặp không thoát, ngoại lệ thiếu và một người vừa xử lý vừa duyệt. Chưa sửa thiết kế.</p>\n              <button class=\"copy\" data-copy=\"p2\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>03</span>Sinh dữ liệu giả</summary>\n            <div>\n              <p id=\"p3\">Tạo 30 hồ sơ GIẢ LẬP theo DATA_DICTIONARY.md gồm ca thường, thiếu, trùng, quá hạn, bổ sung, từ chối và hủy. Không dùng tên, liên hệ, mã định danh có thật. Kèm README ghi rõ dữ liệu giả.</p>\n              <button class=\"copy\" data-copy=\"p3\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>04</span>Test quyền</summary>\n            <div>\n              <p id=\"p4\">Từ MA_TRAN_QUYEN.csv và STATE_MACHINE.md, tạo test matrix vai trò × tài nguyên × hành động × trạng thái. Có test cho phép và từ chối; kiểm tra trực tiếp API/URL, không chỉ ẩn nút UI.</p>\n              <button class=\"copy\" data-copy=\"p4\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>05</span>Chẩn đoán lỗi</summary>\n            <div>\n              <p id=\"p5\">Chẩn đoán, chưa sửa: ca test [...], vai trò [...], trạng thái [...], bước [...], mong đợi [...], thực tế [...], log [...]. Tìm nguyên nhân gốc, ảnh hưởng, bản sửa nhỏ nhất và test hồi quy.</p>\n              <button class=\"copy\" data-copy=\"p5\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>06</span>Tạo handoff</summary>\n            <div>\n              <p id=\"p6\">Tạo HANDOFF.md: phạm vi, kiến trúc, vai trò/trạng thái/dữ liệu, môi trường, file/migration, test+bằng chứng, rủi ro, deploy/rollback/restore, sở hữu và 5 việc tiếp theo. Không chép secret.</p>\n              <button class=\"copy\" data-copy=\"p6\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>07</span>Audit Trail &amp; Chống chối bỏ</summary>\n            <div>\n              <p id=\"p7\">Thiết kế bảng nhật ký bất biến (Audit Log) cho quy trình: mọi thao tác phê duyệt, từ chối, yêu cầu bổ sung phải lưu người thực hiện, thời điểm ISO-8601, địa chỉ IP giả lập, trạng thái trước/sau và lý do nghiệp vụ. Log chỉ được thêm mới (Append-only), không được phép sửa hoặc xóa.</p>\n              <button class=\"copy\" data-copy=\"p7\">Sao chép</button>\n            </div>\n          </details>\n          <details open>\n            <summary><span>08</span>Kiểm soát State Machine &amp; SLA</summary>\n            <div>\n              <p id=\"p8\">Tạo module kiểm soát chuyển trạng thái hồ sơ (State Machine): chỉ cho phép chuyển trạng thái theo đúng luồng định nghĩa trong TO_BE.md. Tự động tính hạn xử lý (SLA), cảnh báo màu vàng khi còn 20% thời gian và chuyển màu đỏ kèm thông báo khi quá hạn.</p>\n              <button class=\"copy\" data-copy=\"p8\">Sao chép</button>\n            </div>\n          </details>\n        </div>\n      </section>\n\n      <!-- BỘ MẪU THỰC HÀNH -->\n      <section class=\"section templates\" id=\"templates\" style=\"padding: 20px 0;\">\n        <header class=\"section-head\">\n          <p class=\"eyebrow dark\">BỘ MẪU THỰC HÀNH</p>\n          <h2>Tải vào workspace</h2>\n          <p>Tất cả dùng dữ liệu giả và phải được chủ nghiệp vụ điều chỉnh theo quy định đơn vị.</p>\n        </header>\n        <div class=\"downloads\">\n          <a href=\"starter/YEU_CAU.md\" download>\n            <b>MD</b>\n            <span>QUY_TRINH_HANH_CHINH.md<small>AS-IS, TO-BE, SLA, acceptance</small></span>\n            <i>↓</i>\n          </a>\n          <a href=\"starter/MA_TRAN_QUYEN.csv\" download>\n            <b>CSV</b>\n            <span>MA_TRAN_QUYEN.csv<small>Vai trò × tài nguyên × hành động</small></span>\n            <i>↓</i>\n          </a>\n          <a href=\"starter/CHECKLIST.md\" download>\n            <b>MD</b>\n            <span>UAT_HANH_CHINH.md<small>Luồng, quyền, audit, restore</small></span>\n            <i>↓</i>\n          </a>\n          <a href=\"starter/HANDOFF_HANH_CHINH.md\" download>\n            <b>MD</b>\n            <span>HANDOFF_HANH_CHINH.md<small>Vận hành, rollback, sở hữu</small></span>\n            <i>↓</i>\n          </a>\n          <a href=\"starter/DU_LIEU_MAU.json\" download>\n            <b>JSON</b>\n            <span>DU_LIEU_GIA_LAP_HANH_CHINH.json<small>8 hồ sơ giả cho test</small></span>\n            <i>↓</i>\n          </a>\n        </div>\n      </section>\n\n      <!-- NGUỒN CHÍNH THỨC & CƠ SỞ PHÁP LÝ -->\n      <section class=\"section sources\" id=\"sources\" style=\"padding: 20px 0;\">\n        <header class=\"section-head\">\n          <p class=\"eyebrow dark\">NGUỒN CHÍNH THỨC</p>\n          <h2>Cơ sở xây dựng guideline</h2>\n          <p>Đối chiếu chuẩn 2026: Tuân thủ nghiêm ngặt ranh giới bảo mật PII, thủ tục hành chính điện tử và chuẩn an toàn SSDF.</p>\n        </header>\n        <div class=\"source-list\">\n          <a href=\"https://vanban.chinhphu.vn/?pageid=27160&amp;docid=199753\" target=\"_blank\" rel=\"noopener\">\n            <b>01</b><span>Nghị định 45/2020/NĐ-CP<small>Thủ tục hành chính trên môi trường điện tử.</small></span><i>↗</i>\n          </a>\n          <a href=\"https://vanban.chinhphu.vn/?pageid=27160&amp;docid=219101\" target=\"_blank\" rel=\"noopener\">\n            <b>MỚI</b><span>Nghị định 310/2026/NĐ-CP<small>Sửa đổi Nghị định 45/2020; hiệu lực 05/08/2026.</small></span><i>↗</i>\n          </a>\n          <a href=\"https://vanban.chinhphu.vn\" target=\"_blank\" rel=\"noopener\">\n            <b>02</b><span>Luật Bảo vệ dữ liệu cá nhân 2025<small>Hiệu lực 01/01/2026: Phân loại dữ liệu cá nhân cơ bản và nhạy cảm.</small></span><i>↗</i>\n          </a>\n          <a href=\"https://github.com/github/spec-kit\" target=\"_blank\" rel=\"noopener\">\n            <b>03</b><span>GitHub Spec Kit<small>Define what to build before building.</small></span><i>↗</i>\n          </a>\n          <a href=\"https://www.nist.gov/publications/secure-software-development-framework-ssdf-version-11-recommendations-mitigating-risk\" target=\"_blank\" rel=\"noopener\">\n            <b>04</b><span>NIST SSDF 1.1<small>Phát triển phần mềm an toàn theo vòng đời.</small></span><i>↗</i>\n          </a>\n        </div>\n      </section>\n\n      <footer class=\"chapter-footer-seamless\">\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#medical-course\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chuyên đề: Vibe Coding Y khoa</span>\n          </a>\n          <a href=\"#home\" class=\"nav-link-next\">\n            <small>HOÀN THÀNH TOÀN BỘ →</small>\n            <span>Về Trang bìa &amp; Mục lục</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","appendix-a":"    <article class=\"ebook-page\" id=\"appendix-a\">\n      <div class=\"part-lead-header\">\n        <span class=\"part-tag\">PHẦN IV · PHỤ LỤC &amp; TÀI NGUYÊN</span>\n        <h2>Phụ Lục Tra Cứu, Starter Kit &amp; Thư Viện Prompt Thực Chiến</h2>\n        <p>Kho tài nguyên thực chiến: Chuỗi prompt mẫu từ A-Z cho bài toán Y khoa thực tế, từ điển thuật ngữ chuyên ngành, bộ starter kit tải về và sổ tay cứu hộ.</p>\n      </div>\n\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\" style=\"background: linear-gradient(135deg, #0284c7, #0ea5e9);\">A</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">PHỤ LỤC A <span>· THƯ VIỆN PROMPT THỰC CHIẾN</span></p>\n          <h2>Chuỗi Prompt Từ A Đến Z: Xây Dựng Ứng Dụng Y Khoa</h2>\n          <p class=\"chapter-subtitle\">Bộ prompt hoàn chỉnh theo luồng thực tế: Từ đặc tả bài toán, thiết kế Google Stitch, Frontend, Backend, Phân quyền đa vai trò, CSDL đến Bảo mật dữ liệu y tế.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Bài toán thực tế xuyên suốt:</b>\n        <span>Xây dựng <strong>\"Cổng Tiếp Nhận &amp; Quản Lý Hồ Sơ Khám Bệnh (MedCare Portal)\"</strong> phục vụ 4 vai trò: Bệnh nhân (đăng ký khám, xem kết quả), Điều dưỡng (tiếp đón, đo sinh hiệu), Bác sĩ (khám, chẩn đoán, kê toa) và Quản trị viên (báo cáo thống kê).</span>\n      </div>\n\n      <div class=\"body\">\n        <!-- GIAI ĐOẠN 1: ĐẶC TẢ BÀI TOÁN -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>📋</span> Giai đoạn 1: Prompt Đặc Tả Bài Toán Y Khoa &amp; Phạm Vi Dự Án (PRD &amp; SPEC)\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 1: KHỞI TẠO ĐẶC TẢ SPEC.MD 10 PHẦN CHO HỆ THỐNG KHÁM BỆNH</b>\n            <p>Dùng để ép AI thiết lập khung tài liệu kỹ thuật chuẩn xác, không tự ý suy diễn tính năng rác.</p>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy đóng vai trò Kỹ sư Trưởng kiêm Chuyên gia Hệ thống Y tế. Tôi muốn xây dựng ứng dụng Web App \"Cổng Tiếp Nhận &amp; Quản Lý Khám Bệnh Khoa Khám (MedCare Portal)\".\nHãy tạo tài liệu `SPEC.md` hoàn chỉnh gồm 10 phần tiêu chuẩn:\n1. Bối cảnh &amp; Mục tiêu: Giảm thời gian chờ đợi xếp hàng của bệnh nhân, chuẩn hóa quy trình nhập sinh hiệu và toa thuốc.\n2. Ranh giới tính năng (Scope):\n   - In-scope v1: Đăng ký lịch khám, tiếp nhận đo sinh hiệu (Huyết áp, Mạch, SpO2, Chiều cao, Cân nặng), ghi chép chẩn đoán của bác sĩ, in phiếu khám và lưu trữ cục bộ an toàn.\n   - Out-of-scope v1: Chưa tích hợp cổng thanh toán trực tuyến, chưa kết nối máy xét nghiệm tự động.\n3. Công nghệ: HTML5 ngữ nghĩa, Vanilla CSS (CSS Variables), JavaScript thuần, dữ liệu lưu LocalStorage an toàn (không dùng framework phức tạp).\n4. Mô hình 4 vai trò: Bệnh nhân, Điều dưỡng, Bác sĩ, Quản trị.\n5. Danh mục 5 tiêu chí nghiệm thu Given-When-Then.\n\nTuyệt đối chưa viết mã nguồn, hãy xuất bản tài liệu SPEC.md trước để tôi duyệt.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-spec-med\">Sao chép prompt</button>\n            <div id=\"p-spec-med\" style=\"display:none;\">Hãy đóng vai trò Kỹ sư Trưởng kiêm Chuyên gia Hệ thống Y tế. Tôi muốn xây dựng ứng dụng Web App \"Cổng Tiếp Nhận &amp; Quản Lý Khám Bệnh Khoa Khám (MedCare Portal)\".\nHãy tạo tài liệu `SPEC.md` hoàn chỉnh gồm 10 phần tiêu chuẩn:\n1. Bối cảnh &amp; Mục tiêu: Giảm thời gian chờ đợi xếp hàng của bệnh nhân, chuẩn hóa quy trình nhập sinh hiệu và toa thuốc.\n2. Ranh giới tính năng (Scope):\n   - In-scope v1: Đăng ký lịch khám, tiếp nhận đo sinh hiệu (Huyết áp, Mạch, SpO2, Chiều cao, Cân nặng), ghi chép chẩn đoán của bác sĩ, in phiếu khám và lưu trữ cục bộ an toàn.\n   - Out-of-scope v1: Chưa tích hợp cổng thanh toán trực tuyến, chưa kết nối máy xét nghiệm tự động.\n3. Công nghệ: HTML5 ngữ nghĩa, Vanilla CSS (CSS Variables), JavaScript thuần, dữ liệu lưu LocalStorage an toàn (không dùng framework phức tạp).\n4. Mô hình 4 vai trò: Bệnh nhân, Điều dưỡng, Bác sĩ, Quản trị.\n5. Danh mục 5 tiêu chí nghiệm thu Given-When-Then.\n\nTuyệt đối chưa viết mã nguồn, hãy xuất bản tài liệu SPEC.md trước để tôi duyệt.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 2: GOOGLE STITCH UI -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>🎨</span> Giai đoạn 2: Prompt Thiết Kế Giao Diện Google Stitch (Desktop &amp; Mobile)\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 2.1: THIẾT KẾ DASHBOARD BÁC SĨ / ĐIỀU DƯỠNG TRÊN MÁY TÍNH (DESKTOP)</b>\n            <p>Prompt nạp vào Google Stitch để sinh giao diện bảng điều khiển quản trị khoa khám bệnh.</p>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy thiết kế giao diện Dashboard Quản lý Khám bệnh trên Desktop chuẩn Google Stitch bằng HTML5 và Vanilla CSS.\nYÊU CẦU THIẾT KẾ:\n- Bố cục: 1 Header trên cùng (Logo Bệnh viện, Tên phòng khám, Nút đổi vai trò Bác sĩ/Điều dưỡng); 1 Sidebar bên trái thu gọn được; khu vực trung tâm chia 2 cột:\n  + Cột trái (40%): Danh sách hàng đợi bệnh nhân chờ khám (hiển thị Mã hồ sơ, Tên, Giờ hẹn, Huy hiệu trạng thái: Chờ khám [Vàng], Đang khám [Xanh], Đã khám [Xanh lá]).\n  + Cột phải (60%): Chi tiết phiếu khám của bệnh nhân đang chọn (Khối đo Sinh hiệu: Huyết áp, Mạch, Nhiệt độ, BMI; Khối Chẩn đoán ICD-10; Khối Kê toa thuốc có nút Thêm thuốc).\n- Phong cách: Tone màu Xanh Y khoa (#0284c7), nền thẻ trắng xám nhạt (#f8fafc), bo góc 10px, font chữ Be Vietnam Pro sạch sẽ, chuyên nghiệp.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-stitch-desk\">Sao chép prompt</button>\n            <div id=\"p-stitch-desk\" style=\"display:none;\">Hãy thiết kế giao diện Dashboard Quản lý Khám bệnh trên Desktop chuẩn Google Stitch bằng HTML5 và Vanilla CSS.\nYÊU CẦU THIẾT KẾ:\n- Bố cục: 1 Header trên cùng (Logo Bệnh viện, Tên phòng khám, Nút đổi vai trò Bác sĩ/Điều dưỡng); 1 Sidebar bên trái thu gọn được; khu vực trung tâm chia 2 cột:\n  + Cột trái (40%): Danh sách hàng đợi bệnh nhân chờ khám (hiển thị Mã hồ sơ, Tên, Giờ hẹn, Huy hiệu trạng thái: Chờ khám [Vàng], Đang khám [Xanh], Đã khám [Xanh lá]).\n  + Cột phải (60%): Chi tiết phiếu khám của bệnh nhân đang chọn (Khối đo Sinh hiệu: Huyết áp, Mạch, Nhiệt độ, BMI; Khối Chẩn đoán ICD-10; Khối Kê toa thuốc có nút Thêm thuốc).\n- Phong cách: Tone màu Xanh Y khoa (#0284c7), nền thẻ trắng xám nhạt (#f8fafc), bo góc 10px, font chữ Be Vietnam Pro sạch sẽ, chuyên nghiệp.</div>\n          </div>\n\n          <div class=\"prompt\">\n            <b>PROMPT 2.2: THIẾT KẾ BIỂU MẪU ĐẶT LỊCH KHÁM TRÊN ĐIỆN THOẠI DI ĐỘNG (MOBILE)</b>\n            <p>Prompt nạp vào Google Stitch để sinh giao diện đặt khám tối ưu cho bệnh nhân dùng điện thoại.</p>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy thiết kế giao diện Biểu mẫu Đăng ký Lịch khám dành cho bệnh nhân tối ưu trên điện thoại di động bằng HTML5/CSS:\n- Bố cục 1 cột dọc: Các trường Họ tên bệnh nhân, Năm sinh, Triệu chứng ban đầu, Chọn Chuyên khoa (Nội tổng quát, Tim mạch, Tiêu hóa), Chọn Giờ khám.\n- Trải nghiệm di động: Mọi nút bấm và ô chọn có chiều cao rộng rãi (dễ chạm ngón tay không bị trượt), nhãn đặt ngay phía trên ô nhập.\n- Phản hồi trực quan: Có thanh tiến trình 3 bước (1. Điền thông tin -> 2. Xác nhận -> 3. Nhận phiếu hẹn có mã QR/Mã số). Khi nhấn gửi, nút chuyển hiệu ứng xoay loading và hiện Toast thông báo thành công.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-stitch-mob\">Sao chép prompt</button>\n            <div id=\"p-stitch-mob\" style=\"display:none;\">Hãy thiết kế giao diện Biểu mẫu Đăng ký Lịch khám dành cho bệnh nhân tối ưu trên điện thoại di động bằng HTML5/CSS:\n- Bố cục 1 cột dọc: Các trường Họ tên bệnh nhân, Năm sinh, Triệu chứng ban đầu, Chọn Chuyên khoa (Nội tổng quát, Tim mạch, Tiêu hóa), Chọn Giờ khám.\n- Trải nghiệm di động: Mọi nút bấm và ô chọn có chiều cao rộng rãi (dễ chạm ngón tay không bị trượt), nhãn đặt ngay phía trên ô nhập.\n- Phản hồi trực quan: Có thanh tiến trình 3 bước (1. Điền thông tin -> 2. Xác nhận -> 3. Nhận phiếu hẹn có mã QR/Mã số). Khi nhấn gửi, nút chuyển hiệu ứng xoay loading và hiện Toast thông báo thành công.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 3: FRONTEND & 5 TRẠNG THÁI -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>💻</span> Giai đoạn 3: Prompt Xây Dựng Frontend &amp; 5 Trạng Thái Giao Diện\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 3: LẬP TRÌNH KHUNG FRONTEND ĐỦ 5 TRẠNG THÁI MÀN HÌNH</b>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy ghép mã HTML5 và Vanilla CSS cho toàn bộ ứng dụng MedCare Portal theo cấu trúc Design Tokens:\n1. Thiết lập biến :root trong CSS: `--primary: #0284c7; --success: #10b981; --warning: #f59e0b; --danger: #ef4444; --bg-page: #f8fafc;`.\n2. Xử lý đủ 5 trạng thái cho bảng danh sách bệnh nhân:\n   - Ideal State: Danh sách bệnh nhân kèm chỉ số sinh hiệu đầy đủ.\n   - Empty State: Hình minh họa hồ sơ rỗng + Thông báo \"Hiện tại chưa có bệnh nhân nào trong hàng đợi\" + Nút \"+ Tiếp nhận bệnh nhân mới\".\n   - Loading State: Hiệu ứng Shimmer Skeleton lướt nhẹ khi đang đọc dữ liệu.\n   - Error State: Khung viền đỏ báo lỗi \"Không thể đọc dữ liệu hồ sơ\" kèm nút \"Thử tải lại\".\n   - Partial State: Cắt gọn tên chẩn đoán quá dài bằng dấu ba chấm (...) và tooltip hiển thị đầy đủ.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-fe-5state\">Sao chép prompt</button>\n            <div id=\"p-fe-5state\" style=\"display:none;\">Hãy ghép mã HTML5 và Vanilla CSS cho toàn bộ ứng dụng MedCare Portal theo cấu trúc Design Tokens:\n1. Thiết lập biến :root trong CSS: `--primary: #0284c7; --success: #10b981; --warning: #f59e0b; --danger: #ef4444; --bg-page: #f8fafc;`.\n2. Xử lý đủ 5 trạng thái cho bảng danh sách bệnh nhân:\n   - Ideal State: Danh sách bệnh nhân kèm chỉ số sinh hiệu đầy đủ.\n   - Empty State: Hình minh họa hồ sơ rỗng + Thông báo \"Hiện tại chưa có bệnh nhân nào trong hàng đợi\" + Nút \"+ Tiếp nhận bệnh nhân mới\".\n   - Loading State: Hiệu ứng Shimmer Skeleton lướt nhẹ khi đang đọc dữ liệu.\n   - Error State: Khung viền đỏ báo lỗi \"Không thể đọc dữ liệu hồ sơ\" kèm nút \"Thử tải lại\".\n   - Partial State: Cắt gọn tên chẩn đoán quá dài bằng dấu ba chấm (...) và tooltip hiển thị đầy đủ.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 4: DATABASE & DATA SCHEMA -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>🗄️</span> Giai đoạn 4: Prompt Thiết Kế Cơ Sở Dữ Liệu &amp; Schema Y Tế\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 4: TẠO CẤU TRÚC DỮ LIỆU SCHEMA JSON / LOCALSTORAGE CHUẨN Y KHOA</b>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy định nghĩa cấu trúc dữ liệu JSON Schema chuẩn để lưu trữ trong `localStorage` cho hệ thống MedCare Portal:\nBao gồm 3 thực thể liên kết với nhau:\n1. `patients` (Bệnh nhân): `id`, `patient_code` (dạng BN-2026-XXXX), `full_name`, `birth_year`, `gender`, `phone_masked`, `created_at`.\n2. `examinations` (Phiếu khám bệnh): `id`, `patient_id`, `doctor_name`, `department`, `symptoms`, `vitals` { `blood_pressure`, `heart_rate`, `temperature`, `spo2`, `height`, `weight`, `bmi` }, `diagnosis_icd10`, `status` ('cho_kham', 'dang_kham', 'da_kham', 'huy'), `created_at`, `updated_at`.\n3. `prescriptions` (Đơn thuốc): `id`, `exam_id`, `medications` [ { `drug_name`, `dosage`, `unit`, `usage_instruction` } ], `doctor_notes`.\n\nTạo sẵn file `DU_LIEU_MAU.json` chứa 5 bản ghi mẫu hoàn chỉnh với các chỉ số sinh hiệu hợp lý để kiểm thử ngay.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-db-schema\">Sao chép prompt</button>\n            <div id=\"p-db-schema\" style=\"display:none;\">Hãy định nghĩa cấu trúc dữ liệu JSON Schema chuẩn để lưu trữ trong `localStorage` cho hệ thống MedCare Portal:\nBao gồm 3 thực thể liên kết với nhau:\n1. `patients` (Bệnh nhân): `id`, `patient_code` (dạng BN-2026-XXXX), `full_name`, `birth_year`, `gender`, `phone_masked`, `created_at`.\n2. `examinations` (Phiếu khám bệnh): `id`, `patient_id`, `doctor_name`, `department`, `symptoms`, `vitals` { `blood_pressure`, `heart_rate`, `temperature`, `spo2`, `height`, `weight`, `bmi` }, `diagnosis_icd10`, `status` ('cho_kham', 'dang_kham', 'da_kham', 'huy'), `created_at`, `updated_at`.\n3. `prescriptions` (Đơn thuốc): `id`, `exam_id`, `medications` [ { `drug_name`, `dosage`, `unit`, `usage_instruction` } ], `doctor_notes`.\n\nTạo sẵn file `DU_LIEU_MAU.json` chứa 5 bản ghi mẫu hoàn chỉnh với các chỉ số sinh hiệu hợp lý để kiểm thử ngay.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 5: BACKEND LOGIC & TÍNH TOÁN Y KHOA -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>⚙️</span> Giai đoạn 5: Prompt Lập Trình Logic Backend &amp; Tự Động Hóa Nghiệp Vụ\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 5: VIẾT HÀM XỬ LÝ LOGIC NGHIỆP VỤ &amp; TÍNH TOÁN CHỈ SỐ Y TẾ</b>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy viết toàn bộ logic xử lý JavaScript cho hệ thống khám bệnh:\n1. Hàm tự động sinh mã hồ sơ: Sinh mã duy nhất dạng `#KB-2026-0001` tăng tự động.\n2. Hàm tự động tính chỉ số BMI: Khi điều dưỡng nhập Chiều cao (cm) và Cân nặng (kg), tự động tính BMI = Cân nặng / ((Chiều cao/100)^2), làm tròn 1 chữ số thập phân và phân loại tự động (Thiếu cân / Bình thường / Thừa cân / Béo phì).\n3. Hàm cảnh báo sinh hiệu bất thường: Nếu Huyết áp tâm thu >= 140 hoặc Nhiệt độ >= 38.5°C, tự động hiển thị chữ đỏ nhấp nháy cảnh báo điều dưỡng.\n4. Quản lý trạng thái: Chuyển trạng thái mượt mà từ \"Chờ khám\" -> \"Đang khám\" -> \"Đã khám hoàn tất\". Hồ sơ đã hoàn tất không cho phép chỉnh sửa sinh hiệu ban đầu.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-logic-med\">Sao chép prompt</button>\n            <div id=\"p-logic-med\" style=\"display:none;\">Hãy viết toàn bộ logic xử lý JavaScript cho hệ thống khám bệnh:\n1. Hàm tự động sinh mã hồ sơ: Sinh mã duy nhất dạng `#KB-2026-0001` tăng tự động.\n2. Hàm tự động tính chỉ số BMI: Khi điều dưỡng nhập Chiều cao (cm) và Cân nặng (kg), tự động tính BMI = Cân nặng / ((Chiều cao/100)^2), làm tròn 1 chữ số thập phân và phân loại tự động (Thiếu cân / Bình thường / Thừa cân / Béo phì).\n3. Hàm cảnh báo sinh hiệu bất thường: Nếu Huyết áp tâm thu >= 140 hoặc Nhiệt độ >= 38.5°C, tự động hiển thị chữ đỏ nhấp nháy cảnh báo điều dưỡng.\n4. Quản lý trạng thái: Chuyển trạng thái mượt mà từ \"Chờ khám\" -> \"Đang khám\" -> \"Đã khám hoàn tất\". Hồ sơ đã hoàn tất không cho phép chỉnh sửa sinh hiệu ban đầu.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 6: PHÂN QUYỀN ĐA VAI TRÒ & CẤP BẬC -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>👥</span> Giai đoạn 6: Prompt Phân Quyền Đa Vai Trò &amp; Cấp Bậc (Roles &amp; Levels)\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 6: THIẾT LẬP PHÂN QUYỀN 4 VAI TRÒ &amp; KHÓA THAO TÁC CẤM</b>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy thiết lập ma trận phân quyền 4 vai trò rõ ràng trong ứng dụng:\n1. Vai trò \"Bệnh nhân\" (Level 1): Chỉ có quyền xem form đăng ký khám và tra cứu đúng mã phiếu khám của chính mình; không thấy danh sách bệnh nhân khác và không có nút chỉnh sửa.\n2. Vai trò \"Điều dưỡng tiếp đón\" (Level 2): Xem danh sách hàng đợi, nhập/sửa chỉ số sinh hiệu (Huyết áp, Mạch, Cân nặng); KHÔNG có quyền kê đơn thuốc hay kết luận chẩn đoán.\n3. Vai trò \"Bác sĩ điều trị\" (Level 3): Xem đầy đủ sinh hiệu, nhập chẩn đoán bệnh, kê đơn thuốc và bấm nút \"Hoàn thành ca khám\".\n4. Vai trò \"Quản trị viên / Lãnh đạo\" (Level 4): Xem toàn bộ bảng thống kê số ca khám trong ngày, xuất báo cáo file CSV, cấu hình danh mục thuốc và phòng khám.\n\nYêu cầu: Viết hàm kiểm tra quyền thực thi (Role-check) ở tầng xử lý logic để người dùng không thể mở F12 gọi lén hàm của vai trò cao hơn.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-roles-med\">Sao chép prompt</button>\n            <div id=\"p-roles-med\" style=\"display:none;\">Hãy thiết lập ma trận phân quyền 4 vai trò rõ ràng trong ứng dụng:\n1. Vai trò \"Bệnh nhân\" (Level 1): Chỉ có quyền xem form đăng ký khám và tra cứu đúng mã phiếu khám của chính mình; không thấy danh sách bệnh nhân khác và không có nút chỉnh sửa.\n2. Vai trò \"Điều dưỡng tiếp đón\" (Level 2): Xem danh sách hàng đợi, nhập/sửa chỉ số sinh hiệu (Huyết áp, Mạch, Cân nặng); KHÔNG có quyền kê đơn thuốc hay kết luận chẩn đoán.\n3. Vai trò \"Bác sĩ điều trị\" (Level 3): Xem đầy đủ sinh hiệu, nhập chẩn đoán bệnh, kê đơn thuốc và bấm nút \"Hoàn thành ca khám\".\n4. Vai trò \"Quản trị viên / Lãnh đạo\" (Level 4): Xem toàn bộ bảng thống kê số ca khám trong ngày, xuất báo cáo file CSV, cấu hình danh mục thuốc và phòng khám.\n\nYêu cầu: Viết hàm kiểm tra quyền thực thi (Role-check) ở tầng xử lý logic để người dùng không thể mở F12 gọi lén hàm của vai trò cao hơn.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 7: BẢO MẬT DỮ LIỆU Y TẾ & CHỐNG MẤT DỮ LIỆU -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>🛡️</span> Giai đoạn 7: Prompt Bảo Mật Dữ Liệu Y Tế &amp; Chống Mất Dữ Liệu (F5)\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 7: RÀO CHẮN BẢO VỆ DỮ LIỆU Y TẾ, KHỬ ĐỘC XSS &amp; LƯU AN TOÀN</b>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy bổ sung toàn diện các tiêu chuẩn an toàn dữ liệu y tế cho ứng dụng:\n1. Bảo vệ dữ liệu cá nhân (PII): Tuyệt đối không lưu số CCCD hoặc mật khẩu trong mã nguồn; số điện thoại bệnh nhân phải được che dạng `090****123` khi hiển thị ở màn hình công cộng.\n2. Khử độc ô nhập liệu: Sử dụng `textContent` khi in thông tin bệnh nhân và toa thuốc, chống tuyệt đối việc chèn mã HTML độc hại hoặc thẻ &lt;script&gt;.\n3. Chống mất dữ liệu khi F5: Bọc toàn bộ quá trình đọc/ghi LocalStorage trong khối `try ... catch`. Nếu dữ liệu bộ nhớ trình duyệt bị lỗi định dạng, tự động phục hồi về bộ dữ liệu mẫu an toàn mà không làm đơ ứng dụng.\n4. Chặn xóa nhầm: Khi bấm xóa một dòng thuốc hoặc hủy ca khám, luôn hiển thị hộp thoại xác nhận bắt buộc.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-sec-med\">Sao chép prompt</button>\n            <div id=\"p-sec-med\" style=\"display:none;\">Hãy bổ sung toàn diện các tiêu chuẩn an toàn dữ liệu y tế cho ứng dụng:\n1. Bảo vệ dữ liệu cá nhân (PII): Tuyệt đối không lưu số CCCD hoặc mật khẩu trong mã nguồn; số điện thoại bệnh nhân phải được che dạng `090****123` khi hiển thị ở màn hình công cộng.\n2. Khử độc ô nhập liệu: Sử dụng `textContent` khi in thông tin bệnh nhân và toa thuốc, chống tuyệt đối việc chèn mã HTML độc hại hoặc thẻ &lt;script&gt;.\n3. Chống mất dữ liệu khi F5: Bọc toàn bộ quá trình đọc/ghi LocalStorage trong khối `try ... catch`. Nếu dữ liệu bộ nhớ trình duyệt bị lỗi định dạng, tự động phục hồi về bộ dữ liệu mẫu an toàn mà không làm đơ ứng dụng.\n4. Chặn xóa nhầm: Khi bấm xóa một dòng thuốc hoặc hủy ca khám, luôn hiển thị hộp thoại xác nhận bắt buộc.</div>\n          </div>\n        </section>\n\n        <!-- GIAI ĐOẠN 8: KIỂM THỬ & GO-LIVE -->\n        <section class=\"wide\">\n          <h3 style=\"color: #0284c7; display: flex; align-items: center; gap: 8px;\">\n            <span>🚀</span> Giai đoạn 8: Prompt Kiểm Thử Nghiệm Thu &amp; Xuất Bản Go-Live\n          </h3>\n          <div class=\"prompt\">\n            <b>PROMPT 8: BẮT AI CHẠY MA TRẬN 8 CA TEST NGHIỆM THU &amp; ĐÓNG GÓI XUẤT BẢN</b>\n            <pre style=\"background: #020617; padding: 14px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 8px 0; border: 1px solid #1e293b;\">Hãy thực hiện kiểm thử tự động toàn diện và chuẩn bị xuất bản ứng dụng:\n1. Lập bảng kết quả 8 ca kiểm thử nghiệm thu:\n   - TC1: Đăng ký ca khám mới thành công.\n   - TC2: Để trống trường bắt buộc báo lỗi đỏ.\n   - TC3: Tự động tính đúng chỉ số BMI.\n   - TC4: Chuyển đổi vai trò Bác sĩ/Điều dưỡng hoạt động đúng quyền.\n   - TC5: Nhấn F5 dữ liệu vẫn giữ nguyên 100%.\n   - TC6: Kiểm tra không bị tràn cuộn ngang trên điện thoại di động.\n   - TC7: Mở Console F12 kiểm tra không còn bất kỳ lỗi đỏ nào.\n   - TC8: Xuất thành công danh sách ca khám ra file CSV.\n2. Hướng dẫn tôi 2 cách xuất bản ứng dụng lên mạng: 1) Kéo thả thư mục lên Netlify Drop trong 30 giây; 2) Đẩy lên GitHub để Vercel tự động deploy.</pre>\n            <button class=\"figure-btn\" data-copy=\"p-test-deploy\">Sao chép prompt</button>\n            <div id=\"p-test-deploy\" style=\"display:none;\">Hãy thực hiện kiểm thử tự động toàn diện và chuẩn bị xuất bản ứng dụng:\n1. Lập bảng kết quả 8 ca kiểm thử nghiệm thu:\n   - TC1: Đăng ký ca khám mới thành công.\n   - TC2: Để trống trường bắt buộc báo lỗi đỏ.\n   - TC3: Tự động tính đúng chỉ số BMI.\n   - TC4: Chuyển đổi vai trò Bác sĩ/Điều dưỡng hoạt động đúng quyền.\n   - TC5: Nhấn F5 dữ liệu vẫn giữ nguyên 100%.\n   - TC6: Kiểm tra không bị tràn cuộn ngang trên điện thoại di động.\n   - TC7: Mở Console F12 kiểm tra không còn bất kỳ lỗi đỏ nào.\n   - TC8: Xuất thành công danh sách ca khám ra file CSV.\n2. Hướng dẫn tôi 2 cách xuất bản ứng dụng lên mạng: 1) Kéo thả thư mục lên Netlify Drop trong 30 giây; 2) Đẩy lên GitHub để Vercel tự động deploy.</div>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-12\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 12: Go-Live &amp; Xuất bản</span>\n          </a>\n          <a href=\"#appendix-c\" class=\"nav-link-next\">\n            <small>TIẾP THEO →</small>\n            <span>Phụ lục C: Bộ Starter Kit</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","appendix-c":"    <article class=\"ebook-page\" id=\"appendix-c\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\" style=\"background: linear-gradient(135deg, #d97706, #f59e0b);\">C</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">PHỤ LỤC C <span>· STARTER KITS</span></p>\n          <h2>Bộ Starter Kit &amp; Mẫu Dự Án Sẵn Dùng</h2>\n          <p class=\"chapter-subtitle\">Tải về bộ khung mẫu cấu hình sẵn để bắt đầu dự án mới trong 1 phút.</p>\n        </div>\n      </header>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"downloads\">\n            <a href=\"starter/DU_LIEU_MAU.json\" download>\n              <b>JSON</b>\n              <div>\n                <span>DU_LIEU_MAU.json</span>\n                <small>Tệp dữ liệu mẫu 30 bản ghi giả lập đầy đủ các tình huống nghiệp vụ</small>\n              </div>\n              <i>↓ Tải về</i>\n            </a>\n            <a href=\"starter/YEU_CAU.md\" download>\n              <b>MD</b>\n              <div>\n                <span>YEU_CAU.md / SPEC.md</span>\n                <small>Khung mẫu đặc tả yêu cầu nghiệp vụ chuẩn 10 phần</small>\n              </div>\n              <i>↓ Tải về</i>\n            </a>\n            <a href=\"starter/AGENTS.md\" download>\n              <b>MD</b>\n              <div>\n                <span>AGENTS.md &amp; GEMINI.md</span>\n                <small>Tệp hướng dẫn quy tắc hành vi bền vững cho Antigravity, Codex &amp; Claude</small>\n              </div>\n              <i>↓ Tải về</i>\n            </a>\n            <a href=\"starter/CHECKLIST.md\" download>\n              <b>MD</b>\n              <div>\n                <span>CHECKLIST.md</span>\n                <small>Bảng kiểm tra 20 tiêu chí nghiệm thu phần mềm trước khi Go-Live</small>\n              </div>\n              <i>↓ Tải về</i>\n            </a>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#appendix-a\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Phụ lục A: Thư viện Prompt</span>\n          </a>\n          <a href=\"#medical-course\" class=\"nav-link-next\">\n            <small>TIẾP THEO →</small>\n            <span>Chuyên đề: Vibe Coding Y khoa</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-1":"    <article class=\"ebook-page\" id=\"chapter-1\" data-chapter=\"1\">\n      <div class=\"part-lead-header\">\n        <span class=\"part-tag\">PHẦN I · NỀN TẢNG &amp; TƯ DUY</span>\n        <h2>Nền Tảng &amp; Tư Duy Vibe Coding Hiện Đại</h2>\n        <p>Nắm vững bản chất kỹ thuật của việc chỉ huy AI, hiểu cấu trúc của một ứng dụng phần mềm và thiết lập kho mã nguồn an toàn trước khi viết dòng lệnh đầu tiên.</p>\n      </div>\n\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">01</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 01 · PHẦN I <span>· 20 PHÚT ĐỌC</span></p>\n          <h2>Bản Chất Vibe Coding &amp; Tư Duy Làm Chủ AI Coding Agent</h2>\n          <p class=\"chapter-subtitle\">Tốc độ nằm ở vòng phản hồi ngắn và kỷ luật giao việc, không nằm ở việc bấm nút vô thức hay phó mặc cho AI đoán mò.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Làm rõ sự chuyển dịch từ gợi ý mã nguồn (Autocomplete) sang AI Agent tự chủ; nắm vững vòng lặp 4 bước Vibe Coding chuẩn mực; hiểu rõ 5 khái niệm cốt lõi (Workspace, Session, Model, Context Window, Quota) và loại bỏ tư duy code mò.</span>\n      </div>\n\n      <div class=\"body\">\n        <section>\n          <h3>1. Sự tiến hóa từ AI gợi ý code đến AI Agent tự chủ</h3>\n          <p>Lịch sử ứng dụng trí tuệ nhân tạo vào lập trình đã trải qua 3 thế hệ phát triển then chốt:</p>\n          <ul>\n            <li><strong>Thế hệ 1 - Auto-complete (Gợi ý dòng lệnh):</strong> Đại diện là GitHub Copilot đời đầu (2021-2023). AI chỉ đóng vai trò là \"Tab Completion\", đoán dòng lệnh tiếp theo dựa trên vài dòng code trước đó. Lập trình viên vẫn phải tự tạo file, tự sửa lỗi và tự kiểm thử.</li>\n            <li><strong>Thế hệ 2 - Chat Sidebar (Hỏi đáp bên lề):</strong> Xuất hiện qua ChatGPT, Claude web và plugin sidebar (2023-2024). Lập trình viên copy-paste code qua lại giữa trình duyệt và IDE. Quá trình này tiêu tốn nhiều thời gian và thường xuyên làm mất ngữ cảnh.</li>\n            <li><strong>Thế hệ 3 - Autonomous AI Coding Agent (Trợ lý tự chủ):</strong> Đại diện bởi <em>Google Antigravity</em>, <em>OpenAI Codex</em>, <em>Claude Desktop / Claude Code</em> (2025-2026). AI có khả năng đọc toàn bộ cây thư mục dự án, tự đề xuất kế hoạch sửa đổi nhiều file đồng thời, tự thực thi lệnh trong terminal, mở trình duyệt để kiểm thử và báo cáo kết quả qua diff trực quan.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>2. Bản chất thực sự của Vibe Coding</h3>\n          <p>Thuật ngữ <em>Vibe Coding</em> được khởi xướng bởi Andrej Karpathy (cựu Giám đốc AI Tesla, đồng sáng lập OpenAI). Nó mô tả trạng thái lập trình viên diễn đạt mong muốn bằng ngôn ngữ tự nhiên, để AI đảm nhiệm việc hiện thực hóa mã nguồn.</p>\n          <p>Tuy nhiên, <strong>Vibe Coding không phải là code mò vô định</strong>. Nếu không có đặc tả, AI sẽ tự bịa logic (hallucination), tạo ra mã nguồn rác, vi phạm bảo mật và làm tràn bộ nhớ ngữ cảnh (Context Window). Vibe Coding chuyên nghiệp là kỹ năng của một <em>Tổng chỉ huy kỹ thuật</em>: đưa ra yêu cầu chính xác, xét duyệt kế hoạch trước khi chạy và nghiệm thu sản phẩm qua từng bài test.</p>\n        </section>\n\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">📊 Hình 1.1: 5 Khái niệm nền tảng cần biết trước khi dùng AI Agent</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/diagrams/beginner_five_concepts.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/diagrams/beginner_five_concepts.webp\" alt=\"5 Khái niệm nền tảng AI Coding Agent: Project, Session, Model, History, Quota\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 1.1:</em> Năm trụ cột vận hành của bất kỳ AI Coding Agent nào: <strong>Project</strong> (Không gian làm việc), <strong>Session</strong> (Phiên hội thoại), <strong>Model</strong> (Bộ não suy luận), <strong>History</strong> (Lịch sử phiên) và <strong>Quota</strong> (Hạn ngạch token/lượt gọi).\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: VIBE CODING & TƯ DUY DEV -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Kênh Tôi Đi Code Dạo</span>\n                📺 Video Thực Chiến: AI Viết Code Ngày Càng Xịn — Bản Chất Vibe Coding &amp; Tương Lai Ngành Lập Trình\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=z4aoLLaV4-4\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"AI viết code ngày càng xịn, tương lai ngành Lập Trình sẽ ra sao?\"</div>\n              <div class=\"video-channel-tag\"><span>Kênh: Tôi Đi Code Dạo (Phạm Huy Hoàng)</span> • 400.000+ Lượt xem</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=z4aoLLaV4-4\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Góc nhìn thực tế từ chuyên gia:</strong> Lập trình viên không lo bị AI thay thế nếu biết cách chuyển đổi vai trò từ \"thợ gõ code\" sang \"chỉ huy kỹ thuật\" — nắm rõ bài toán nghiệp vụ, duyệt giải pháp và kiểm thử nghiệm thu nghiêm ngặt.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 01:20 — Auto-complete vs AI Agent</span>\n                <span class=\"video-stamp-pill\">⏱️ 05:40 — Vì sao lười suy nghĩ sẽ bị đào thải</span>\n                <span class=\"video-stamp-pill\">⏱️ 11:15 — 3 Kỹ năng cốt lõi thời đại AI</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Năm khái niệm cốt lõi của mọi AI Coding Agent</h3>\n          <p>Dù sử dụng Antigravity, Codex hay Claude Desktop, bạn bắt buộc phải hiểu 5 thực thể sau:</p>\n          <ol>\n            <li><strong>Project / Workspace:</strong> Thư mục gốc chứa toàn bộ mã nguồn, tài liệu và cấu hình của dự án. Agent chỉ có thể thao tác an toàn bên trong phạm vi thư mục này.</li>\n            <li><strong>Session (Phiên làm việc):</strong> Cuộc hội thoại độc lập giữa bạn và AI. Khi đổi nhiệm vụ lớn, nên tạo session mới để làm sạch Context Window.</li>\n            <li><strong>Model (Mô hình suy luận):</strong> Bộ não xử lý (ví dụ: Claude 3.7 Sonnet, GPT-4o, Gemini 2.5 Pro). Mỗi mô hình có thế mạnh riêng về logic, tốc độ hoặc phân tích hình ảnh.</li>\n            <li><strong>Context Window &amp; Token Budget:</strong> Dung lượng bộ nhớ của phiên làm việc. Càng nhiều tin nhắn cũ, bộ nhớ càng đầy, AI càng dễ bị \"lú lẫn\" và phản hồi chậm hơn.</li>\n            <li><strong>Quota &amp; Rate Limit:</strong> Hạn mức sử dụng của tài khoản (tính theo số lượt gọi mỗi phút/giờ hoặc số token tiêu thụ trong ngày).</li>\n          </ol>\n        </section>\n\n        <section>\n          <h3>4. Vòng lặp 4 bước Vibe Coding chuẩn mực</h3>\n          <p>Để đạt hiệu quả cao nhất và tránh lỗi phá hỏng mã nguồn cũ, hãy luôn tuân thủ vòng lặp 4 bước khép kín:</p>\n          <ul>\n            <li><strong>Bước 1 - Explore (Khám phá):</strong> Yêu cầu AI đọc repo, quét các file liên quan để hiểu hiện trạng mà không sửa mã.</li>\n            <li><strong>Bước 2 - Plan (Lập kế hoạch):</strong> AI tạo tài liệu kế hoạch liệt kê danh sách file cần sửa, kiến trúc và rủi ro kỹ thuật; bạn duyệt trước khi chạy.</li>\n            <li><strong>Bước 3 - Code (Viết mã từng phần):</strong> AI chỉ sửa đúng phạm vi đã duyệt, ưu tiên các lát cắt nhỏ độc lập (incremental slice).</li>\n            <li><strong>Bước 4 - Verify (Kiểm chứng &amp; Commit):</strong> Chạy unit test, mở trình duyệt kiểm tra giao diện, đối chiếu tiêu chí hoàn thành rồi commit git.</li>\n          </ul>\n        </section>\n\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">🔄 Hình 1.2: Vòng lặp Vibe Coding có kiểm soát</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/diagrams/01_vibe_loop.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/diagrams/01_vibe_loop.webp\" alt=\"Vòng lặp Vibe Coding\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 1.2:</em> Quy trình lặp liên tục: Đưa đặc tả → Xem Plan → Duyệt Diff → Kiểm thử → Commit.\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>5. Năm cạm bẫy \"Code mò\" (Vibe Blindness) thường gặp</h3>\n          <div class=\"warn\">\n            <strong>NHỮNG SAI LẦM PHỔ BIẾN CẦN TRÁNH:</strong>\n            <ol style=\"margin-top: 8px; padding-left: 20px;\">\n              <li><strong>Prompt quá chung chung:</strong> <em>\"Làm cho tôi một web bán hàng giống Shopee.\"</em> → AI sẽ tự bịa hàng trăm dòng code thừa thãi không chạy được.</li>\n              <li><strong>Không đọc Diff trước khi Apply:</strong> Chấp nhận toàn bộ thay đổi mà không kiểm tra xem AI có xóa nhầm code cũ hay không.</li>\n              <li><strong>Dồn toàn bộ tính năng vào một Prompt:</strong> Yêu cầu vừa làm giao diện, vừa làm backend, vừa làm thanh toán trong một lần bấm nút.</li>\n              <li><strong>Giữ một Session quá dài:</strong> Chat hàng trăm tin nhắn trong một session khiến context bị loãng, chi phí token tăng vọt.</li>\n              <li><strong>Bỏ qua bước Test trên trình duyệt:</strong> Tin rằng \"AI báo xong nghĩa là code chạy được\" mà không tự mình bấm thử các nút trên màn hình.</li>\n            </ol>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 1 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"1\">✓ Đánh dấu đã đọc chương 1</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#home\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Trang bìa &amp; Mục lục</span>\n          </a>\n          <a href=\"#chapter-2\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 02: Mô hình hoạt động Web App</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-10":"    <article class=\"ebook-page\" id=\"chapter-10\" data-chapter=\"10\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">10</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 10 · PHẦN III <span>· 30 PHÚT ĐỌC</span></p>\n          <h2>Đặc Tả Kỹ Thuật Không Đoán Mò: Phương Pháp Spec-Driven</h2>\n          <p class=\"chapter-subtitle\">Nguyên tắc số 1 để AI không tự ý bịa tính năng: Viết SPEC.md theo cú pháp Given-When-Then và phân chia phạm vi v1/v2 rõ ràng.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Hiểu rõ tại sao 80% dự án AI thất bại do thiếu đặc tả; làm chủ cấu trúc tài liệu SPEC.md 10 phần tiêu chuẩn; viết kịch bản kiểm thử theo cú pháp Given-When-Then và thiết lập ranh giới tính năng In-scope vs Out-of-scope dứt khoát.</span>\n      </div>\n\n      <div class=\"body\">\n        <section>\n          <h3>1. Tại sao 80% dự án thất bại vì thiếu đặc tả?</h3>\n          <p>Khi bạn ra lệnh mơ hồ như: <em>\"Làm cho tôi một ứng dụng quản lý công việc\"</em>, mô hình AI buộc phải tự suy diễn hàng trăm quyết định kiến trúc: Dữ liệu lưu ở đâu? Có cần phân quyền không? Khi xóa công việc thì xóa vĩnh viễn hay chuyển vào thùng rác? Trạng thái công việc có mấy bước?</p>\n          <p>Mỗi lần AI tự đoán mò là một lần tăng nguy cơ sinh mã nguồn rác và xung đột logic. <strong>Phương pháp Spec-Driven Development (SDD)</strong> yêu cầu con người viết rõ ràng các quyết định này vào file <code>SPEC.md</code> trước khi AI viết dòng mã đầu tiên. Đây không phải là thủ tục rườm rà, mà là hàng rào kỹ thuật ngăn AI phá hủy cấu trúc dự án.</p>\n        </section>\n\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">📋 Hình 10.1: Quy trình Spec-Driven Development — Từ Ý Tưởng Đến Acceptance Test</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/diagrams/07_spec_driven.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/diagrams/07_spec_driven.webp\" alt=\"Quy trình Spec-Driven Development: PRD, Given-When-Then, Implementation Plan, Automated Verification\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 10.1:</em> Chu trình 4 bước của Spec-Driven Development: <strong>Đặc tả 10 phần</strong> → <strong>Tiêu chí Given-When-Then</strong> → <strong>Kế hoạch kỹ thuật (Plan)</strong> → <strong>Kiểm thử nghiệm thu tự động</strong>.\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: AI-DRIVEN SPEC -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Series AI-Driven Development</span>\n                📺 Video Hướng Dẫn: Quy Trình Đặc Tả &amp; Phát Triển Phần Mềm Cùng AI\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=4t0zD9gveo0&amp;list=PLDHSigHSDJWW2TkRAeBXplLy5dF1rkHYi&amp;index=6\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"Quy Trình Đặc Tả Yêu Cầu &amp; Phát Triển Ứng Dụng Chuẩn AI-Driven (SPEC.md → Plan → Code)\"</div>\n              <div class=\"video-channel-tag\"><span>Series: AI-Driven Software Engineering</span> • Video Thực Hành</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=4t0zD9gveo0&amp;list=PLDHSigHSDJWW2TkRAeBXplLy5dF1rkHYi&amp;index=6\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Quy trình công nghiệp:</strong> Hướng dẫn cách xây dựng tài liệu đặc tả kỹ thuật (SPEC.md), bóc tách kiến trúc, định dạng tiêu chí nghiệm thu Given-When-Then và chỉ đạo AI triển khai chính xác theo kế hoạch.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 01:30 — Bóc tách tài liệu yêu cầu (PRD &amp; SPEC)</span>\n                <span class=\"video-stamp-pill\">⏱️ 06:45 — Thiết kế luồng dữ liệu &amp; Schema CSDL</span>\n                <span class=\"video-stamp-pill\">⏱️ 13:20 — Tiêu chí kiểm thử Given-When-Then</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Cấu trúc tài liệu SPEC.md 10 phần tiêu chuẩn</h3>\n          <p>Tài liệu đặc tả hoàn chỉnh gồm đúng 10 mục cốt lõi:</p>\n          <div class=\"code\">\n            <div><span>KHUNG TÀI LIỆU SPEC.MD TIÊU CHUẨN</span></div>\n            <pre># SPEC.md - ĐẶC TẢ KỸ THUẬT DỰ ÁN\n\n## 1. Mục tiêu và Bối cảnh (Problem &amp; Goal)\n- Giải quyết vấn đề gì? Cho đối tượng nào?\n- Thước đo thành công: Số lượng thao tác giảm, thời gian xử lý nhanh hơn.\n\n## 2. Ranh giới tính năng (Scope)\n- In-scope (Phải làm trong v1): Danh sách tính năng cốt lõi.\n- Out-of-scope (Tuyệt đối không làm trong v1): Các tính năng phức tạp để dành v2.\n\n## 3. Kiến trúc tổng thể &amp; Công nghệ (Tech Stack)\n- Frontend: HTML5, CSS Variables, Vanilla JS (không dùng framework phức tạp).\n- Backend / Lưu trữ: LocalStorage / Supabase / PostgreSQL.\n- API Endpoints: Danh sách các đường dẫn dữ liệu.\n\n## 4. Mô hình dữ liệu (Data Models &amp; Schema)\n- Bảng 1: Các trường, kiểu dữ liệu, khóa chính, ràng buộc.\n- Bảng 2: Quan hệ giữa các bảng (1-1, 1-N).\n\n## 5. Luồng người dùng &amp; Kịch bản (User Flows)\n- Bước 1 -> Bước 2 -> Bước 3 -> Kết quả mong đợi.\n\n## 6. Tiêu chí nghiệm thu (Given-When-Then Acceptance Criteria)\n- Scenario 1: Given [Trạng thái ban đầu], When [Thực hiện hành động], Then [Kết quả xảy ra].\n- Scenario 2: Xử lý khi dữ liệu nhập vào bị sai hoặc bỏ trống.\n\n## 7. Ràng buộc bảo mật &amp; Phân quyền (Security &amp; Auth)\n- Ai được xem dữ liệu nào? Ai được quyền sửa/xóa?\n- Cơ chế bảo vệ API Key và chống XSS/SQL Injection.\n\n## 8. Trải nghiệm người dùng &amp; 5 trạng thái UI\n- Ideal State, Empty State, Loading State, Error State, Partial State.\n\n## 9. Kế hoạch kiểm thử (Test Plan)\n- Happy path, Edge cases, Negative testing, Persistence test.\n\n## 10. Checklist bàn giao (Definition of Done)\n- Code sạch, không lỗi Console F12, chạy mượt trên thiết bị di động (Mobile), đầy đủ tài liệu README.</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Kỹ thuật viết Given-When-Then để AI tự kiểm tra mã</h3>\n          <p>Khi mô tả hành vi ứng dụng cho AI, hãy dùng cú pháp Given-When-Then chuẩn công nghiệp để AI có thể tự động viết test case và tự kiểm tra mã của chính nó:</p>\n          <div class=\"prompt\">\n            <b>MẪU PROMPT GIVEN-WHEN-THEN CHUẨN:</b>\n            <p><strong>Scenario:</strong> Sinh viên đăng ký cấp giấy xác nhận học tập.<br>\n            <strong>Given:</strong> Sinh viên đã đăng nhập thành công và đang ở trang biểu mẫu đăng ký.<br>\n            <strong>When:</strong> Sinh viên chọn lý do \"Vay vốn ngân hàng\" và nhấn nút \"Gửi yêu cầu\".<br>\n            <strong>Then:</strong> Hệ thống tạo bản ghi mới với trạng thái \"Chờ duyệt\", hiển thị mã hồ sơ dạng <code>XN-2026-XXXX</code> và gửi thông báo Toast màu xanh: <em>\"Đã gửi yêu cầu thành công!\"</em>.<br>\n            <strong>Edge Case:</strong> Nếu sinh viên bỏ trống ô lý do, viền ô chuyển sang màu đỏ và hiển thị dòng chữ: <em>\"Vui lòng nhập lý do xin cấp giấy\"</em>, nút Gửi bị vô hiệu hóa.</p>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 10 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"10\">✓ Đánh dấu đã đọc chương 10</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-9\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 09: Dữ liệu &amp; Bảo mật</span>\n          </a>\n          <a href=\"#chapter-11\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 11: Kiểm thử &amp; Sửa lỗi</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-11":"    <article class=\"ebook-page\" id=\"chapter-11\" data-chapter=\"11\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">11</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 11 · PHẦN III <span>· 25 PHÚT ĐỌC</span></p>\n          <h2>Kiểm Thử Chất Lượng (QA/UAT) &amp; Khắc Phục Sự Cố</h2>\n          <p class=\"chapter-subtitle\">\"Mã nguồn chạy không báo lỗi\" chỉ là bước đầu — nghiệm thu bằng 6 nhóm kịch bản kiểm thử và thu thập bằng chứng.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Xây dựng bảng kiểm thử UAT 6 nhóm kịch bản; thực hiện kiểm tra quyền âm (Negative Testing); thành thạo quy trình 3 bước khắc phục sự cố khi AI làm sai và giải mã 5 lỗi phổ biến trong mã nguồn AI sinh.</span>\n      </div>\n\n      <div class=\"body\">\n        <section>\n          <h3>1. Sáu nhóm kịch bản kiểm thử UAT bắt buộc</h3>\n          <p>Trước khi nghiệm thu bất kỳ tính năng nào do AI viết, hãy lần lượt kiểm tra qua 6 kịch bản:</p>\n          <ol>\n            <li><strong>Nhóm 1 - Happy Path (Luồng chuẩn):</strong> Nhập dữ liệu hợp lệ và hoàn tất quy trình từ đầu đến cuối.</li>\n            <li><strong>Nhóm 2 - Validation &amp; Boundary (Dữ liệu sai/biên):</strong> Bỏ trống ô bắt buộc, nhập chữ vào ô số, nhập số âm, nhập văn bản cực dài (1.000 từ).</li>\n            <li><strong>Nhóm 3 - State Transition (Chuyển trạng thái):</strong> Kiểm tra xem đơn hàng đã hủy có thể bấm duyệt lại được không (phải bị chặn).</li>\n            <li><strong>Nhóm 4 - Negative Permission (Quyền âm):</strong> Dùng tài khoản nhân viên truy cập thẳng vào URL trang admin xem hệ thống có đẩy ra không.</li>\n            <li><strong>Nhóm 5 - Refresh &amp; Persistence (Tải lại trang):</strong> Nhấn F5 xem dữ liệu có còn nguyên không hay bị reset về trắng.</li>\n            <li><strong>Nhóm 6 - Multi-device Responsive:</strong> Kiểm tra hiển thị trên máy tính, máy tính bảng và điện thoại di động.</li>\n          </ol>\n        </section>\n\n        <!-- THƯ VIỆN PROMPT KIỂM THỬ TỰ ĐỘNG & BẮT MỌI LỖI -->\n        <section class=\"wide\" style=\"margin: 20px 0;\">\n          <div style=\"background: linear-gradient(135deg, #0f172a, #1e293b); border: 1px solid #334155; border-radius: 14px; padding: 24px; color: #f8fafc;\">\n            <div style=\"display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; margin-bottom: 18px;\">\n              <h4 style=\"margin: 0; font-size: 16px; color: #38bdf8; display: flex; align-items: center; gap: 8px;\">\n                <span>🧪</span> Thư Viện Prompt Kiểm Thử Tự Động &amp; Rà Soát Sạch Mọi Lỗi (Bug Audit Prompts)\n              </h4>\n              <span style=\"background: #ef4444; color: #ffffff; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 700;\">Sao Chép Dùng Liền</span>\n            </div>\n\n            <!-- PROMPT 1 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">🔍 Mẫu 1: Rà Soát Toàn Diện Lỗi Console, Runtime &amp; Bất Đồng Bộ</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Quét sạch lỗi ngầm</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy đóng vai Kỹ sư Kiểm thử Phần mềm (Senior QA Engineer). Hãy đọc toàn bộ mã nguồn hiện tại trong dự án và thực hiện kiểm tra toàn diện:\n1. Rà soát tất cả các hàm xử lý dữ liệu và sự kiện (Event Listeners), tìm kiếm các vị trí có nguy cơ gây lỗi Null/Undefined hoặc bất đồng bộ (Missing async/await).\n2. Kiểm tra xem có trường hợp nào gắn trùng sự kiện (Duplicate Event Listener) khiến ứng dụng bị chạy lặp lại nhiều lần không.\n3. Liệt kê bảng báo cáo lỗi gồm 3 cột: [Tên File/Dòng mã] - [Mô tả nguy cơ lỗi] - [Cách khắc phục]. Chưa sửa mã nguồn khi tôi chưa xác nhận.</pre>\n            </div>\n\n            <!-- PROMPT 2 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">💥 Mẫu 2: Kiểm Thử Dữ Liệu Biên &amp; Trường Hợp Cực Đoan (Stress Test)</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Thử thách độ bền của ứng dụng</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy thiết lập các kịch bản kiểm thử dữ liệu biên (Boundary &amp; Edge Cases) cho tất cả các biểu mẫu (Form) nhập liệu trong hệ thống:\n- Thử nghiệm 1: Bỏ trống tất cả các trường và bấm Gửi.\n- Thử nghiệm 2: Nhập số âm, ký tự chữ vào ô chỉ nhận số (Số điện thoại, Năm sinh).\n- Thử nghiệm 3: Nhập chuỗi văn bản cực dài (500 ký tự) hoặc ký tự đặc biệt &lt;script&gt;alert(1)&lt;/script&gt;.\n- Thử nghiệm 4: Chọn ngày tương lai cho ngày sinh, hoặc ngày bắt đầu lớn hơn ngày kết thúc.\nHãy kiểm tra xem mã nguồn đã có đủ điều kiện chặn (Validation) chưa và đề xuất bổ sung các câu thông báo lỗi tiếng Việt thân thiện.</pre>\n            </div>\n\n            <!-- PROMPT 3 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">🔄 Mẫu 3: Kiểm Thử F5 Tải Lại Trang &amp; Lưu Trữ Bền Vững (Persistence)</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Chống mất dữ liệu</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy rà soát toàn bộ cơ chế lưu trữ trạng thái (State Persistence) của ứng dụng:\n1. Đảm bảo mọi thao tác: Thêm mới, Sửa, Xóa hoặc Đánh dấu trạng thái đều được đồng bộ ngay lập tức vào localStorage/Database.\n2. Kiểm tra hàm khởi tạo (Init) khi người dùng mở lại trang hoặc nhấn F5: dữ liệu phải được nạp lại đầy đủ và hiển thị chính xác lên giao diện.\n3. Xử lý trường hợp dữ liệu lưu trữ bị lỗi hoặc trống (Corrupted/Empty JSON): ứng dụng phải tự động khôi phục về trạng thái mặc định an toàn, không bị treo trắng màn hình.</pre>\n            </div>\n\n            <!-- PROMPT 4 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">🎯 Mẫu 4: Sửa Lỗi Tối Thiểu (Minimal Fix — Không Phá Hỏng Code Đang Chạy)</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Sửa đúng trọng tâm</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Tôi phát hiện lỗi sau khi chạy ứng dụng:\n- Hiện tượng: [Mô tả chi tiết, ví dụ: Nhấn nút Lưu hồ sơ nhưng bảng không hiện bản ghi mới]\n- Lỗi Console F12: [Dán nguyên văn dòng lỗi đỏ kèm số dòng file]\n\nYêu cầu thực hiện:\n1. Giải thích nguyên nhân gốc rễ (Root cause) ngắn gọn trong 2 câu.\n2. Áp dụng quy tắc Sửa lỗi tối thiểu (Minimal Fix): Chỉ chỉnh sửa đúng hàm gây lỗi. Tuyệt đối không thay đổi cấu trúc HTML, không xóa class CSS hay viết lại toàn bộ file.\n3. Cung cấp đoạn mã thay thế và hướng dẫn tôi cách kiểm tra lại để chắc chắn lỗi đã hết.</pre>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Quy trình 3 bước khắc phục sự cố khi AI đi chệch hướng</h3>\n          <p>Khi gặp lỗi (trang bị đơ, lỗi Console đỏ, chức năng không hoạt động), tuyệt đối không hoảng loạn xóa code viết lại. Hãy làm đúng 3 bước:</p>\n          <div class=\"hint\">\n            <strong>QUY TRÌNH 3 BƯỚC SỬA LỖI TINH GỌN:</strong><br>\n            <strong>Bước 1 - Thu thập bằng chứng chính xác:</strong> Mở Console trình duyệt (nhấn F12), chụp ảnh màn hình hoặc sao chép chính xác dòng thông báo lỗi màu đỏ đầu tiên kèm mã dòng (Line Number).<br>\n            <strong>Bước 2 - Đặt câu hỏi phân tích nguyên nhân gốc (Root Cause):</strong> Gửi cho AI: <em>\"Khi tôi bấm nút [Tên nút] thì Console báo lỗi [Dòng lỗi]. Hãy phân tích nguyên nhân gốc trước, liệt kê các file liên quan, CHƯA vội viết lại toàn bộ code.\"</em><br>\n            <strong>Bước 3 - Yêu cầu bản sửa lỗi tối thiểu (Minimal Fix):</strong> Yêu cầu AI chỉ sửa đúng hàm bị lỗi, không đụng vào các hàm khác đang chạy ổn định.\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Giải mã 5 lỗi kinh điển trong mã nguồn do AI sinh</h3>\n          <ul>\n            <li><strong>Lỗi 1 - State Desynchronization (Lệch trạng thái):</strong> Dữ liệu đã lưu vào CSDL nhưng giao diện không tự cập nhật lại danh sách mới (cần gọi lại hàm render sau khi API trả về 200).</li>\n            <li><strong>Lỗi 2 - Asynchronous Race Condition (Bất đồng bộ):</strong> Gọi hàm trước khi dữ liệu từ máy chủ kịp tải về (cần thêm <code>await</code> hoặc kiểm tra <code>if (!data) return;</code>).</li>\n            <li><strong>Lỗi 3 - CORS Policy Blocked:</strong> Trình duyệt chặn kết nối API do máy chủ backend chưa cấu hình <code>Access-Control-Allow-Origin</code>.</li>\n            <li><strong>Lỗi 4 - Null Pointer Exception:</strong> Cố gắng truy cập thuộc tính của một biến chưa tồn tại (ví dụ: <code>user.profile.avatar</code> khi <code>profile</code> đang là <code>undefined</code>).</li>\n            <li><strong>Lỗi 5 - Memory Leak / Event Listener Duplicate:</strong> Gắn sự kiện <code>addEventListener</code> lặp lại nhiều lần trong vòng lặp khiến ứng dụng chạy càng lúc càng chậm.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>4. Definition of Done: chỉ nhận “xong” khi có bằng chứng</h3>\n          <p>Một Agent nói “đã hoàn thành” chưa phải là nghiệm thu. Trước khi gộp mã hoặc phát hành, hãy đối chiếu 6 bằng chứng sau với SPEC.md:</p>\n          <ol>\n            <li>Đúng luồng chính và các tiêu chí Given–When–Then đã cam kết.</li>\n            <li>Kiểm tra dữ liệu sai, giá trị biên và trạng thái rỗng.</li>\n            <li>Kiểm tra quyền âm: người không có quyền không thể xem hoặc sửa bằng URL/API trực tiếp.</li>\n            <li>Kiểm tra tải lại trang, lưu bền dữ liệu và đường khôi phục khi dữ liệu lỗi.</li>\n            <li>Chạy các lệnh test/build được dự án khai báo; Console không còn lỗi mới.</li>\n            <li>Xem Git diff, cập nhật README/HANDOFF và ghi rõ phần chưa làm vào backlog.</li>\n          </ol>\n          <div class=\"hint\"><strong>Quy tắc bàn giao:</strong> báo cáo cần ghi “đã chạy gì, kết quả gì, còn rủi ro gì” thay vì chỉ ghi “đã test xong”.</div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 11 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"11\">✓ Đánh dấu đã đọc chương 11</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-10\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 10: Đặc tả Spec-Driven</span>\n          </a>\n          <a href=\"#chapter-12\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 12: Go-Live &amp; Xuất bản</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-12":"    <article class=\"ebook-page\" id=\"chapter-12\" data-chapter=\"12\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">12</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 12 · PHẦN III <span>· 30 PHÚT ĐỌC</span></p>\n          <h2>Đưa Ứng Dụng Lên Mạng (Vercel, Netlify &amp; Go-Live)</h2>\n          <p class=\"chapter-subtitle\">Từ máy cá nhân ra thế giới: Hướng dẫn chi tiết cách xuất bản web bằng Netlify Drop, Vercel, trỏ tên miền riêng và nghiệm thu bàn giao.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Làm chủ 3 cách xuất bản ứng dụng lên mạng miễn phí (Netlify Drop kéo-thả trong 30 giây, Vercel tự động hóa CI/CD qua GitHub, và GitHub Pages); biết cách đổi tên miền phụ, gắn tên miền riêng và thực hiện bảng kiểm tra 10 điểm trước khi bàn giao.</span>\n      </div>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">🚀 Hình 12.1: Quy trình tự động triển khai (CI/CD) từ Git lên Vercel &amp; Netlify</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/official_ui/deploy_workflow.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/official_ui/deploy_workflow.webp\" alt=\"Sơ đồ luồng đẩy mã nguồn GitHub lên Cloudflare và Vercel\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 12.1:</em> Khi bạn sửa code hoặc push commit lên GitHub, máy chủ Vercel / Netlify tự động nhận diện và xuất bản phiên bản mới trong 30 giây kèm chứng chỉ bảo mật HTTPS miễn phí.\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: GO-LIVE & DEPLOY VERCEL -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Hướng Dẫn Vercel</span>\n                📺 Video Thực Hành: Triển Khai &amp; Xuất Bản Web Lên Vercel Cực Nhanh\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=U00nmT_jWYs\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"Hướng Dẫn Triển Khai Website Lên Vercel Miễn Phí, Tự Động Hóa CI/CD &amp; Cấu Hình Tên Miền\"</div>\n              <div class=\"video-channel-tag\"><span>Chuyên đề: Vercel Cloud Deployment</span> • Video Thực Hành</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=U00nmT_jWYs\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Thực hành triển khai:</strong> Xem trực tiếp quy trình kết nối kho mã nguồn GitHub với Vercel, tự động build &amp; deploy và kiểm tra trang web trực tuyến với chứng chỉ HTTPS.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 01:20 — Chuẩn bị mã nguồn &amp; Đăng nhập Vercel</span>\n                <span class=\"video-stamp-pill\">⏱️ 04:45 — Import GitHub Repo &amp; Bấm Deploy</span>\n                <span class=\"video-stamp-pill\">⏱️ 08:30 — Kiểm tra link online &amp; Tên miền</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <!-- HƯỚNG DẪN CHI TIẾT BẰNG CHỮ CÁC CÁCH XUẤT BẢN -->\n        <section>\n          <h3>1. Cách 1: Xuất bản siêu tốc bằng Netlify Drop (Kéo - Thả trong 30 giây)</h3>\n          <p>Đây là cách đơn giản nhất dành cho người làm Vibe Coding: <strong>không cần cài đặt phần mềm, không cần dùng dòng lệnh Git</strong> mà vẫn có ngay trang web chạy online với đường dẫn HTTPS an toàn.</p>\n          <div class=\"code\">\n            <div><span>4 BƯỚC THỰC HIỆN VỚI NETLIFY DROP</span></div>\n            <pre>Bước 1: Mở trình duyệt và truy cập vào địa chỉ: https://app.netlify.com/drop\nBước 2: Mở thư mục dự án trên máy tính của bạn (thư mục chứa file index.html cùng các file css, js).\nBước 3: Dùng chuột KÉO TOÀN BỘ THƯ MỤC ĐÓ VÀ THẢ vào ô chấm nét đứt trên màn hình Netlify.\nBước 4: Chờ khoảng 10-15 giây để hệ thống tải lên. Netlify sẽ cấp ngay một đường link trực tiếp (ví dụ: https://happy-curie-123456.netlify.app).</pre>\n          </div>\n          <div class=\"hint\">\n            <strong>Mẹo đổi tên miền phụ đẹp mắt trên Netlify:</strong><br>\n            Sau khi tải lên thành công, bấm vào mục <em>Site configuration</em> → Chọn <em>Change site name</em> → Gõ tên bạn muốn (ví dụ: <code>so-tay-sinh-vien</code>) → Bấm <em>Save</em>. Đường link của bạn sẽ đổi thành <code>https://so-tay-sinh-vien.netlify.app</code> hoàn toàn miễn phí!\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Cách 2: Triển khai tự động chuẩn doanh nghiệp với Vercel</h3>\n          <p>Vercel là nền tảng điện toán đám mây hàng đầu thế giới dành cho ứng dụng web. Khi kết nối với GitHub, mỗi lần bạn sửa mã nguồn và lưu lại, Vercel sẽ <strong>tự động cập nhật trang web sau 30 giây</strong>.</p>\n          <div class=\"code\">\n            <div><span>4 BƯỚC TRIỂN KHAI VỚI VERCEL</span></div>\n            <pre>Bước 1: Đẩy toàn bộ mã nguồn của bạn lên một kho lưu trữ (Repository) trên GitHub.\nBước 2: Mở trang https://vercel.com → Đăng nhập bằng tài khoản GitHub (Continue with GitHub).\nBước 3: Tại bảng điều khiển Vercel, nhấp vào nút \"Add New...\" ở góc trên bên phải → Chọn \"Project\" → Nhấn \"Import\" cạnh kho GitHub vừa tạo.\nBước 4: Tại màn hình cấu hình:\n  - Project Name: Đặt tên cho ứng dụng của bạn.\n  - Framework Preset: Nếu là HTML/CSS/JS thuần, chọn \"Other\".\n  - Environment Variables: Thêm các khóa bí mật nếu dự án có dùng API ngoài.\n  - Nhấn nút \"Deploy\" màu xanh.</pre>\n          </div>\n          <p>Sau khoảng 20-30 giây, màn hình bắn pháo hoa xuất hiện và bạn nhận được đường dẫn dạng <code>https://ten-du-an.vercel.app</code> có tốc độ tải siêu nhanh trên toàn cầu.</p>\n        </section>\n\n        <section>\n          <h3>3. Cách 3: Xuất bản miễn phí trọn đời bằng GitHub Pages</h3>\n          <p>Nếu bạn đã lưu trữ mã nguồn trên GitHub, bạn có thể bật tính năng GitHub Pages tích hợp sẵn:</p>\n          <ol>\n            <li>Mở trang GitHub repository của bạn trên trình duyệt → Chọn thẻ <strong>Settings</strong> (Cài đặt) ở thanh menu trên cùng.</li>\n            <li>Tại menu bên trái, chọn mục <strong>Pages</strong>.</li>\n            <li>Ở phần <em>Build and deployment</em> → Mục <em>Branch</em>, chọn nhánh <code>main</code> (hoặc <code>master</code>) và chọn thư mục <code>/(root)</code> → Nhấn <strong>Save</strong>.</li>\n            <li>Chờ 1-2 phút rồi làm mới trang, GitHub sẽ cung cấp link công khai dạng: <code>https://&lt;ten-tai-khoan&gt;.github.io/&lt;ten-repo&gt;/</code>.</li>\n          </ol>\n        </section>\n\n        <section>\n          <h3>4. Cấu hình tên miền riêng (Custom Domain)</h3>\n          <p>Để gắn tên miền của cơ quan hay thương hiệu của bạn (ví dụ: <code>ungdung.bvchoray.vn</code> hoặc <code>app.cuaban.com</code>), vào trang quản lý DNS của nhà cung cấp tên miền và thêm các bản ghi sau:</p>\n          <div class=\"code\">\n            <div><span>BẢN GHI DNS MẪU TRỎ VỀ VERCEL / NETLIFY</span></div>\n            <pre>Loại bản ghi    Tên máy chủ (Host)      Giá trị đích (Value / Points to)       TTL\nCNAME           app                     cname.vercel-dns.com.                 Tự động\nCNAME           web                     ten-site-cua-ban.netlify.app.         Tự động\nA               @                       76.76.21.21 (Vercel IP)               Tự động</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>5. Bảng kiểm tra 10 điểm Go-Live bắt buộc trước khi bàn giao</h3>\n          <div class=\"prompt\">\n            <b>CHECKLIST GO-LIVE CUỐI CÙNG:</b>\n            <ol style=\"margin-top: 8px; padding-left: 20px;\">\n              <li>[ ] <strong>Console sạch:</strong> Mở F12 không còn dòng lỗi đỏ nào (`Uncaught Error`).</li>\n              <li>[ ] <strong>Bảo vệ bí mật:</strong> Không có bất kỳ mật khẩu hay API Key thật nào bị lộ trong file mã nguồn.</li>\n              <li>[ ] <strong>Thử nghiệm F5:</strong> Tải lại trang trên link online xem dữ liệu nhập vào có còn nguyên không.</li>\n              <li>[ ] <strong>Kiểm tra trên điện thoại di động:</strong> Dùng điện thoại thật mở đường link web xem có bị tràn viền hay nút bấm khó bấm không.</li>\n              <li>[ ] <strong>Kiểm tra liên kết:</strong> Bấm thử tất cả các nút và menu xem có trang nào bị lỗi 404 không.</li>\n              <li>[ ] <strong>Chứng chỉ HTTPS:</strong> Đảm bảo thanh địa chỉ trình duyệt hiện biểu tượng ổ khóa an toàn.</li>\n              <li>[ ] <strong>Thông báo người dùng:</strong> Khi gửi form thành công hoặc có lỗi, luôn hiện thông báo Toast rõ ràng.</li>\n              <li>[ ] <strong>Tiêu đề &amp; Biểu tượng:</strong> Đã đặt thẻ <code>&lt;title&gt;</code> tiếng Việt rõ nghĩa và gắn icon (Favicon).</li>\n              <li>[ ] <strong>Dữ liệu mẫu:</strong> Đã dọn dẹp các dữ liệu nháp thử nghiệm không cần thiết.</li>\n              <li>[ ] <strong>Tài liệu hướng dẫn:</strong> Đã viết file <code>README.md</code> hoặc hướng dẫn ngắn gọn cho người tiếp nhận sử dụng.</li>\n            </ol>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 12 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"12\">✓ Hoàn tất toàn bộ 12 chương sách</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-11\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 11: Kiểm thử &amp; Sửa lỗi</span>\n          </a>\n          <a href=\"#appendix-a\" class=\"nav-link-next\">\n            <small>PHỤ LỤC TIẾP THEO →</small>\n            <span>Phụ lục A: Thư viện Prompt mẫu</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-2":"    <article class=\"ebook-page\" id=\"chapter-2\" data-chapter=\"2\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">02</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 02 · PHẦN I <span>· 25 PHÚT ĐỌC</span></p>\n          <h2>Mô Hình Hoạt Động Của Web App &amp; Luồng Dữ Liệu</h2>\n          <p class=\"chapter-subtitle\">Hiểu rõ 4 tầng cấu tạo của ứng dụng web và 5 đường đi của dữ liệu để không bao giờ hỏi AI những câu mơ hồ.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Nắm vững phân tầng Frontend - Backend - Database - Hosting; phân tích 5 cấp độ lưu trữ dữ liệu từ LocalStorage đến Cloud PostgreSQL; hiểu cách dữ liệu di chuyển an toàn qua HTTP/JSON và xác định kiến trúc phù hợp cho dự án của bạn.</span>\n      </div>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">🏗️ Hình 2.1: Kiến trúc tổng quan 4 tầng của một ứng dụng Web</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/official_ui/ai_app_architecture.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/official_ui/ai_app_architecture.webp\" alt=\"Kiến trúc ứng dụng Web: UI, API, Database, Hosting\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 2.1:</em> Mô hình tách biệt rõ ràng giữa <strong>Giao diện người dùng (Frontend)</strong>, <strong>Xử lý nghiệp vụ &amp; Bảo mật (Backend/API)</strong>, <strong>Lưu trữ có cấu trúc (Database)</strong> và <strong>Đám mây triển khai (Hosting/Cloud)</strong>.\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: MÔ HÌNH WEB APP & DATABASE -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Kênh Tôi Đi Code Dạo</span>\n                📺 Video Hướng Dẫn: Tự Học HTML &amp; Dựng Website Đơn Giản Trong 15 Phút\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=jSyH0HxKQPY\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"Hiểu Rõ Khung Xương Web App: Cấu Trúc Thẻ HTML, Trình Duyệt &amp; Luồng Giao Diện\"</div>\n              <div class=\"video-channel-tag\"><span>Kênh: Tôi Đi Code Dạo (Phạm Huy Hoàng)</span> • 320.000+ Lượt xem</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=jSyH0HxKQPY\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Kiến thức nền tảng:</strong> Hướng dẫn trực quan cách một trang web được xây dựng, cấu trúc các thẻ HTML, cách nhúng CSS định dạng và cách trình duyệt render giao diện cho người dùng.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 01:15 — Cấu trúc thẻ HTML cơ bản</span>\n                <span class=\"video-stamp-pill\">⏱️ 06:40 — Tạo biểu mẫu nhập liệu (Form)</span>\n                <span class=\"video-stamp-pill\">⏱️ 12:20 — Mở file chạy trực tiếp trên trình duyệt</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>1. Bốn tầng cấu tạo của một ứng dụng Web hiện đại</h3>\n          <p>Mọi hệ thống phần mềm web dù đơn giản hay phức tạp đều được xây dựng dựa trên 4 tầng nền tảng:</p>\n          <ul>\n            <li><strong>Tầng 1: Frontend (Client-side):</strong> Chạy trên trình duyệt của người dùng (Chrome, Safari). Bao gồm HTML (khung xương), CSS (định dạng thị giác) và JavaScript (hành vi tương tác). <em>Quy tắc vàng:</em> Frontend là môi trường công khai, tuyệt đối không bao giờ chứa mật khẩu hoặc API Key bí mật.</li>\n            <li><strong>Tầng 2: Backend &amp; API (Server-side):</strong> Chạy trên máy chủ từ xa (Node.js, Python FastAPI, Go, hoặc Serverless Functions). Nhiệm vụ: Xác minh danh tính người dùng, kiểm tra quyền hạn (Authorization), thực hiện nghiệp vụ tính toán và giao tiếp với CSDL.</li>\n            <li><strong>Tầng 3: Database (Cơ sở dữ liệu):</strong> Nơi lưu trữ dữ liệu bền vững (Persistent Data) theo cấu trúc bảng (Relational SQL) hoặc tài liệu (NoSQL). CSDL đảm bảo dữ liệu không bị mất khi người dùng tắt trình duyệt hoặc máy chủ khởi động lại.</li>\n            <li><strong>Tầng 4: Infrastructure &amp; Hosting (Hạ tầng mạng):</strong> Máy chủ đám mây, mạng phân phối nội dung (CDN), tên miền (DNS) và chứng chỉ bảo mật HTTPS (Vercel, Netlify, Cloudflare, AWS).</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>2. Phân tích 5 cấp độ lưu trữ dữ liệu trong thực tế</h3>\n          <p>Tùy theo giai đoạn thử nghiệm hay triển khai chính thức, bạn sẽ yêu cầu AI Coding Agent lựa chọn đường đi dữ liệu phù hợp:</p>\n          <ol>\n            <li><strong>Level 1 - Memory State (Bộ nhớ tạm JS):</strong> Dữ liệu chỉ nằm trong biến JavaScript (mất ngay khi người dùng nhấn F5 tải lại trang). Thích hợp cho hoạt ảnh giao diện và form nhiều bước trước khi submit.</li>\n            <li><strong>Level 2 - LocalStorage / IndexedDB:</strong> Lưu trực tiếp trên trình duyệt cá nhân của từng thiết bị. Không cần máy chủ, không tốn phí, xây dựng xong trong 5 phút. Rất phù hợp cho ứng dụng ghi chú cá nhân, mockup demo hoặc lưu cài đặt giao diện (Dark Mode).</li>\n            <li><strong>Level 3 - Mock JSON File:</strong> Đọc dữ liệu từ file tĩnh <code>data.json</code>. Rất tiện lợi cho việc kiểm tra giao diện với 30-50 bản ghi mẫu trước khi kết nối CSDL thật.</li>\n            <li><strong>Level 4 - SQLite Local Database:</strong> CSDL quan hệ lưu trong 1 file đơn duy nhất trên máy tính hoặc server. Siêu nhẹ, hỗ trợ đầy đủ cú pháp SQL tiêu chuẩn, không cần cài đặt dịch vụ CSDL phức tạp. Thích hợp cho app nội bộ máy tính và công cụ nội bộ.</li>\n            <li><strong>Level 5 - Cloud Database (Supabase / PostgreSQL):</strong> CSDL quan hệ đám mây hoàn chỉnh, hỗ trợ hàng triệu người dùng, xác thực tài khoản, phân quyền Row-Level Security (RLS) và sao lưu tự động. Đây là lựa chọn bắt buộc cho sản phẩm thương mại.</li>\n          </ol>\n        </section>\n\n        <section class=\"wide\">\n          <div class=\"choice-table\">\n            <div><b>Mức lưu trữ</b><b>Ưu điểm nổi bật</b><b>Nhược điểm &amp; Rủi ro</b><b>Khi nào nên dùng?</b></div>\n            <div><span><b>1. LocalStorage</b></span><span>Cực nhanh, 0đ, không cần backend</span><span>Dữ liệu không đồng bộ qua máy khác, dễ bị xóa</span><span>Prototype, bài lab cá nhân, lưu Theme</span></div>\n            <div><span><b>2. SQLite file</b></span><span>Chuẩn SQL, tốc độ cao, file đơn gọn</span><span>Khó scale đa máy chủ phân tán</span><span>Tool nội bộ máy tính, hệ thống 1 server</span></div>\n            <div><span><b>3. Supabase Cloud</b></span><span>Bảo mật cấp doanh nghiệp, Auth có sẵn, API REST</span><span>Cần kết nối mạng, có giới hạn gói free</span><span>Sản phẩm chính thức, app nhiều người dùng</span></div>\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Cách dữ liệu di chuyển: REST API, JSON và HTTP Methods</h3>\n          <p>Khi người dùng thực hiện một thao tác trên giao diện (ví dụ: bấm nút \"Lưu đơn hàng\"), một luồng dữ liệu chuẩn sẽ diễn ra:</p>\n          <div class=\"code\">\n            <div><span>LUỒNG GIAO TIẾP HTTP CHUẨN</span></div>\n            <pre>[Client Frontend] --(1) Gửi HTTP POST + Body JSON--> [Backend API Server]\n                                                            |\n                                                   (2) Kiểm tra Token / Quyền\n                                                   (3) Validate dữ liệu\n                                                            |\n                                                   (4) Ghi vào [Database]\n                                                            |\n[Client Frontend] &lt;--(5) Nhận HTTP 200 OK + JSON kết quả--- [Backend API Server]</pre>\n          </div>\n          <p>Các phương thức HTTP tiêu chuẩn bạn cần biết khi giao tiếp với AI:</p>\n          <ul>\n            <li><code>GET /api/items</code>: Lấy danh sách bản ghi (không làm thay đổi dữ liệu).</li>\n            <li><code>POST /api/items</code>: Tạo mới một bản ghi.</li>\n            <li><code>PUT / PATCH /api/items/123</code>: Cập nhật thông tin bản ghi số 123.</li>\n            <li><code>DELETE /api/items/123</code>: Xóa bản ghi số 123.</li>\n          </ul>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 2 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"2\">✓ Đánh dấu đã đọc chương 2</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-1\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 01: Bản chất Vibe Coding</span>\n          </a>\n          <a href=\"#chapter-3\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 03: Chuẩn bị Workspace</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-3":"    <article class=\"ebook-page\" id=\"chapter-3\" data-chapter=\"3\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">03</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 03 · PHẦN I <span>· 25 PHÚT ĐỌC</span></p>\n          <h2>Chuẩn Bị Workspace &amp; Kho Mã Nguồn Chuẩn Cho AI</h2>\n          <p class=\"chapter-subtitle\">Kho mã nguồn tốt cho con người cũng là kho mã nguồn tốt nhất cho AI Agent hiểu ngữ cảnh.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Tổ chức cây thư mục chuẩn cho AI Agent quét nhanh; thiết lập bộ hồ sơ quy tắc dự án (AGENTS.md, SPEC.md, RULES.md, .gitignore); nắm vững kỷ luật Git an toàn và nguyên tắc bảo mật Zero Secret Leakage.</span>\n      </div>\n\n      <div class=\"body\">\n        <section>\n          <h3>1. Cấu trúc thư mục tối ưu cho AI Agent</h3>\n          <p>AI Agent đọc hiểu thư mục rất nhanh nếu bạn đặt tên tệp có ý nghĩa, tránh nhồi nhét mọi thứ vào 1 file duy nhất nhưng cũng không chia tách quá vụn vặt:</p>\n          <div class=\"code\">\n            <div><span>CẤU TRÚC WORKSPACE TIÊU CHUẨN</span></div>\n            <pre>my-project/\n├── .gitignore          # Chặn commit file rác và bí mật (.env, node_modules, tmp/)\n├── AGENTS.md           # Quy tắc hành vi &amp; phong cách viết mã cho AI Agent\n├── SPEC.md             # Tài liệu đặc tả yêu cầu kỹ thuật &amp; tiêu chí nghiệm thu\n├── index.html          # Trang chủ ứng dụng (HTML ngữ nghĩa, sạch sẽ)\n├── css/\n│   ├── style.css       # Design tokens, reset, biến màu sắc &amp; font chữ\n│   └── components.css  # Giao diện các thành phần chi tiết\n├── js/\n│   ├── app.js          # Logic điều phối chính &amp; routing\n│   └── modules/        # Các module xử lý dữ liệu và API\n├── data/\n│   └── sample.json     # Dữ liệu mẫu phục vụ kiểm thử\n└── tests/              # Kịch bản kiểm thử tự động</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>1.1. Chụp “baseline” trước khi giao Agent sửa mã</h3>\n          <p>Đừng bắt đầu bằng yêu cầu “sửa hết đi”. Trước mỗi thay đổi đáng kể, hãy ghi nhận trạng thái đang chạy được để biết lỗi nào có sẵn và lỗi nào xuất hiện sau khi Agent can thiệp.</p>\n          <ol>\n            <li><strong>Đọc hướng dẫn:</strong> mở <code>README.md</code>, <code>SPEC.md</code> và các quy tắc hiện có trước khi ra lệnh.</li>\n            <li><strong>Kiểm tra trạng thái Git:</strong> dùng <code>git status</code>; không trộn thay đổi dở dang của người khác vào nhiệm vụ mới.</li>\n            <li><strong>Chạy đúng kiểm tra đã có:</strong> chỉ chạy lệnh được dự án khai báo, như <code>npm test</code>, <code>npm run build</code> hoặc checklist thủ công trong README.</li>\n            <li><strong>Lưu bằng chứng ngắn:</strong> ghi lại lệnh đã chạy, kết quả và ảnh Preview nếu có. Khi test vốn đã lỗi, tách nó thành việc riêng thay vì quy cho thay đổi mới.</li>\n          </ol>\n          <div class=\"hint\"><strong>Prompt an toàn:</strong> “Chỉ đọc repo. Hãy cho tôi biết trạng thái Git, các lệnh kiểm tra được khai báo và kết quả baseline. Chưa sửa bất kỳ tệp nào.”</div>\n        </section>\n\n        <!-- THƯ VIỆN PROMPT KHỞI TẠO WORKSPACE THỰC CHIẾN -->\n        <section class=\"wide\" style=\"margin: 20px 0;\">\n          <div style=\"background: linear-gradient(135deg, #0f172a, #1e293b); border: 1px solid #334155; border-radius: 14px; padding: 24px; color: #f8fafc;\">\n            <div style=\"display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; margin-bottom: 18px;\">\n              <h4 style=\"margin: 0; font-size: 16px; color: #38bdf8; display: flex; align-items: center; gap: 8px;\">\n                <span>⚡</span> Thư Viện Prompt Khởi Tạo Workspace &amp; Hồ Sơ Quy Tắc Dự Án (Bootstrap Prompts)\n              </h4>\n              <span style=\"background: #0284c7; color: #ffffff; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 700;\">Sao Chép Dùng Liền</span>\n            </div>\n\n            <!-- PROMPT 1 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">📁 Mẫu 1: Khởi Tạo Cây Thư Mục Chuẩn &amp; File .gitignore Bảo Mật</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Dựng móng dự án</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy khởi tạo cấu trúc thư mục hoàn chỉnh cho dự án web mới:\n1. Tạo các thư mục: css/, js/, data/, assets/diagrams/, assets/icons/, tests/.\n2. Tạo file .gitignore chuẩn, loại trừ: .env, node_modules/, .DS_Store, tmp/, *.log, dist/.\n3. Tạo file index.html cơ bản với thẻ HTML5 ngữ nghĩa, nạp sẵn font Be Vietnam Pro và liên kết css/style.css, js/app.js.\n4. Tạo file README.md ghi rõ mục tiêu dự án, cách chạy thử nghiệm và cấu trúc thư mục.</pre>\n            </div>\n\n            <!-- PROMPT 2 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">📜 Mẫu 2: Tự Động Sinh File Nội Quy Dự Án AGENTS.md</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Thiết lập \"vòng kim cô\" cho AI</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy tạo file AGENTS.md tại thư mục gốc của dự án với các quy định nghiêm ngặt sau:\n- Vai trò: Bạn là Kỹ sư lập trình Fullstack giàu kinh nghiệm, chuyên về HTML5/CSS/Vanilla JS.\n- Quy tắc công nghệ: Không tự ý cài đặt thêm framework bên ngoài (React/Vue/Tailwind) trừ khi tôi yêu cầu. Mọi CSS phải đặt trong file .css riêng, không viết inline style tràn lan.\n- Bảo mật: Tuyệt đối không lưu mật khẩu hay API Key ở mã nguồn client.\n- Quy trình sửa đổi: Phải phân tích giải pháp và lập kế hoạch (Plan) trước; chỉ sửa đúng file liên quan (Minimal Changes), không xóa hay viết lại mã nguồn đang hoạt động ổn định.</pre>\n            </div>\n\n            <!-- PROMPT 3 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">🛡️ Mẫu 3: Đọc Baseline &amp; Kiểm Tra An Toàn Trước Khi Giao Nhiệm Vụ Mới</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Chống ghi đè mã nguồn</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Chỉ đọc repository. Chưa sửa đổi bất kỳ tệp nào.\nHãy quét toàn bộ cấu trúc dự án và báo cáo cho tôi:\n1. Trạng thái Git hiện tại (các file đang staged, modified hoặc untracked).\n2. Tóm tắt kiến trúc hiện có và các module đang chạy ổn định.\n3. Bản kế hoạch từng bước (Step-by-step Plan) để thực hiện nhiệm vụ [Mô tả tính năng cần làm].\nSau khi tôi duyệt bản kế hoạch này, bạn mới được bắt đầu viết mã.</pre>\n            </div>\n          </div>\n        </section>\n\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">📂 Hình 3.1: Giải phẫu kho mã nguồn chuẩn mực cho AI Agent</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/diagrams/03_repo_anatomy.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/diagrams/03_repo_anatomy.webp\" alt=\"Giải phẫu kho mã nguồn repo chuẩn cho AI\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 3.1:</em> Tổ chức thư mục rõ ràng giúp Agent định vị tệp cần sửa mà không đọc thừa thãi, tiết kiệm Context Window và hạn chế xung đột mã.\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Bộ ba tài liệu \"Định hướng hành vi AI\"</h3>\n          <p>Để Agent không đi chệch hướng, hãy luôn duy trì 3 file văn bản ở thư mục gốc:</p>\n          <ol>\n            <li><strong>SPEC.md (Tài liệu đặc tả):</strong> Định nghĩa ứng dụng làm gì, ai dùng, các trường dữ liệu và tiêu chí nghiệm thu cụ thể.</li>\n            <li><strong>AGENTS.md (Quy tắc thực thi):</strong> Quy định ngôn ngữ lập trình, thư viện được phép dùng, tiêu chuẩn đặt tên hàm và yêu cầu lập kế hoạch trước khi viết mã.</li>\n            <li><strong>.gitignore (Bộ lọc an toàn):</strong> Danh sách các file và thư mục cấm đẩy lên Git (file chứa API Key, file tạm, thư mục cài đặt nặng).</li>\n          </ol>\n        </section>\n\n        <section>\n          <h3>3. Kỷ luật Git an toàn tuyệt đối khi lập trình cùng AI</h3>\n          <ul>\n            <li><strong>Tạo nhánh mới cho từng tính năng (Feature Branch):</strong> Luôn tạo nhánh mới như <code>git checkout -b feat/user-auth</code> trước khi yêu cầu AI viết mã lớn. Nếu AI làm hỏng, bạn có thể xóa nhánh đi làm lại mà không ảnh hưởng nhánh chính <code>main</code>.</li>\n            <li><strong>Commit theo từng lát cắt nhỏ (Semantic Commits):</strong> Commit ngay khi một phần tính năng chạy tốt. Ví dụ: <code>feat: tạo form nhập liệu</code> → <code>feat: kết nối api lưu đơn</code>.</li>\n            <li><strong>Luôn kiểm tra Visual Diff:</strong> Không gõ <code>git add .</code> một cách mù quáng. Hãy mở giao diện Diff để xem từng dòng code AI đã sửa đổi.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>4. Quản lý biến môi trường (.env) và bảo mật</h3>\n          <div class=\"warn\">\n            <strong>NGUYÊN TẮC ZERO SECRET LEAKAGE:</strong>\n            <p style=\"margin: 6px 0 0;\">Tạo file <code>.env.example</code> chứa các tên biến mẫu (như <code>SUPABASE_URL=your_url_here</code>) để đẩy lên Git, trong khi file <code>.env</code> thật chứa khóa bí mật bắt buộc phải được khai báo trong <code>.gitignore</code>.</p>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 3 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"3\">✓ Đánh dấu đã đọc chương 3</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-2\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 02: Mô hình hoạt động Web App</span>\n          </a>\n          <a href=\"#chapter-4\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 04: Google Antigravity</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-4":"    <article class=\"ebook-page\" id=\"chapter-4\" data-chapter=\"4\">\n      <div class=\"part-lead-header\">\n        <span class=\"part-tag\">PHẦN II · CÔNG CỤ CHUYÊN SÂU</span>\n        <h2>Tam Mã AI Coding Agent Thực Chiến</h2>\n        <p>Khảo sát sâu sắc 3 công cụ lập trình AI mạnh nhất hiện nay: Google Antigravity, OpenAI Codex và Claude Desktop. Nắm vững giao diện, phím tắt, cơ chế lưu bộ nhớ và cách phối hợp tối ưu chi phí.</p>\n      </div>\n\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">04</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 04 · PHẦN II <span>· 30 PHÚT ĐỌC</span></p>\n          <h2>Làm Chủ Google Antigravity: IDE, CLI &amp; Hệ Thống Artifacts</h2>\n          <p class=\"chapter-subtitle\">Trợ lý mã nguồn tự chủ từ DeepMind với cơ chế sinh Artifact tài liệu, duyệt diff trực quan và điều khiển trình duyệt headless.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Làm chủ toàn bộ hệ sinh thái Google Antigravity (IDE, agy CLI, Python SDK); vận hành thành thạo hệ thống Artifacts (Plan &amp; Walkthrough); khai thác Browser Subagent để kiểm thử UI tự động và thiết lập cấu hình GEMINI.md nâng cao.</span>\n      </div>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">🌌 Hình 4.1: Giao diện thực tế Google Antigravity IDE (2026 Edition)</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/official_ui/antigravity_plan.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/official_ui/antigravity_plan.webp\" alt=\"Giao diện Google Antigravity IDE: Agent Chat, Artifacts Panel, Editor, Browser Subagent\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 4.1:</em> Bố cục 4 khu vực làm việc của Google Antigravity: <strong>Thanh tác vụ Agent</strong> (trái), <strong>Khung soạn thảo mã nguồn</strong> (giữa), <strong>Hệ thống Artifacts &amp; Plan</strong> (phải) và <strong>Trình duyệt kiểm thử Browser Subagent</strong>.\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: GOOGLE ANTIGRAVITY -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Series Antigravity</span>\n                📺 Video Hướng Dẫn: Làm Chủ Google Antigravity &amp; Trợ Lý Lập Trình Tự Chủ\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=jxHzdaNMUlI&amp;list=PLMpzwYzN40ePz2ZxNkbOjs907VctUWdTi&amp;index=1\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"Khám Phá &amp; Thực Chiến Google Antigravity — Hệ Thống Kế Hoạch, Artifacts &amp; Agent Tự Chủ\"</div>\n              <div class=\"video-channel-tag\"><span>Series: Google Antigravity Masterclass</span> • Video Thực Hành</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=jxHzdaNMUlI&amp;list=PLMpzwYzN40ePz2ZxNkbOjs907VctUWdTi&amp;index=1\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Điểm nhấn kỹ thuật:</strong> Hướng dẫn chi tiết cách vận hành Google Antigravity IDE, thiết lập quy trình duyệt kế hoạch (Artifacts &amp; Plan), chỉ đạo Subagent và kiểm thử tự động trên trình duyệt.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 01:00 — Giao diện Antigravity IDE</span>\n                <span class=\"video-stamp-pill\">⏱️ 05:20 — Quy trình duyệt Kế hoạch (Plan Mode)</span>\n                <span class=\"video-stamp-pill\">⏱️ 11:30 — Vận hành Browser Subagent &amp; Artifacts</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>1. Kiến trúc tổng thể của Google Antigravity 2.0</h3>\n          <p>Google Antigravity 2.0 được phát triển bởi Google DeepMind, tích hợp dòng mô hình Gemini 2.5/3.0 với khả năng xử lý Context Window cực lớn (lên tới 1–2 triệu token) cùng cơ chế <strong>Reactive Messaging</strong> và <strong>Multi-Agent Delegation</strong>. Hệ sinh thái Antigravity gồm 4 cấu phần chủ lực:</p>\n          <ul>\n            <li><strong>Antigravity IDE &amp; Command Center:</strong> Môi trường phát triển tích hợp đầy đủ tính năng soạn thảo, quản lý phiên làm việc, trực quan hóa Git Diff và hệ thống duyệt kế hoạch Artifacts tương tác.</li>\n            <li><strong>Antigravity CLI (agy):</strong> Công cụ dòng lệnh mạnh mẽ cho phép chạy Agent trực tiếp từ Terminal trên macOS, Linux và Windows với cờ <code>--worktree</code> an toàn.</li>\n            <li><strong>Subagents &amp; Parallel Workers:</strong> Khả năng phân tách nhiệm vụ lớn thành nhiều subagent độc lập (nghiên cứu tài liệu, kiểm thử giao diện, rà soát bảo mật) chạy song song mà không làm ô nhiễm ngữ cảnh chính.</li>\n            <li><strong>Custom Skills &amp; Knowledge System:</strong> Hệ thống nạp kỹ năng mở rộng qua cấu trúc <code>SKILL.md</code> (kèm YAML frontmatter) và quản lý bộ nhớ Knowledge Items được lưu bền vững.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>2. Điểm mạnh vượt trội: Hệ thống Artifacts &amp; Planning Mode</h3>\n          <p>Khác biệt cốt lõi của Antigravity so với các chatbot thông thường là <strong>Hệ thống Artifacts</strong> và cơ chế <strong>Planning Mode</strong>. Thay vì nhồi nhét hàng nghìn dòng giải thích vào khung chat, Antigravity tách riêng thành các tài liệu cấu trúc:</p>\n          <ol>\n            <li><strong>Implementation Plan (implementation_plan.md):</strong> Kế hoạch kỹ thuật chi tiết trước khi hành động. Chứa danh sách chính xác các file cần tạo mới (<code>[NEW]</code>), sửa đổi (<code>[MODIFY]</code>) hoặc xóa bỏ (<code>[DELETE]</code>), phân tích rủi ro và các câu hỏi cần người dùng duyệt. Khi bạn bấm nút <strong>Proceed</strong>, Agent mới bắt đầu sửa mã nguồn.</li>\n            <li><strong>Walkthrough (walkthrough.md):</strong> Báo cáo nghiệm thu sau khi hoàn thành công việc. Tóm tắt những thay đổi đã thực hiện, kết quả kiểm thử và hướng dẫn người dùng chạy thử kèm ảnh/video minh họa.</li>\n            <li><strong>Architecture &amp; Data Diagrams:</strong> Sơ đồ luồng dữ liệu hoặc biểu đồ cấu trúc được kết xuất trực quan bằng Mermaid hoặc PlantUML.</li>\n          </ol>\n          <div class=\"hint\">\n            <strong>MẸO THỰC CHIẾN VỚI ARTIFACTS:</strong><br>\n            Bạn có thể bôi đen và bình luận trực tiếp lên từng dòng của <code>implementation_plan.md</code> để yêu cầu Agent điều chỉnh kiến trúc trước khi phê duyệt thực thi!\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Hệ thống Kỹ năng (Custom Skills) &amp; Phân tầng Quy tắc (Rules)</h3>\n          <p>Antigravity cho phép người dùng tùy biến hành vi của Agent thông qua 2 cấp độ thư mục:</p>\n          <div class=\"mini-table\">\n            <div><b>Cấp độ</b><b>Đường dẫn</b><b>Mục đích &amp; Phạm vi</b></div>\n            <div><span><b>Toàn cục (Global)</b></span><span><code>~/.gemini/config/</code></span><span>Chứa các kỹ năng và quy tắc dùng chung cho toàn bộ dự án trên máy tính của bạn.</span></div>\n            <div><span><b>Dự án (Workspace)</b></span><span><code>.agents/</code> và <code>GEMINI.md</code></span><span>Chứa các quy tắc riêng biệt, coding standards và context đặc thù của riêng dự án đó.</span></div>\n          </div>\n          <p>Mỗi Kỹ năng (Skill) được đóng gói trong một thư mục chứa tệp <code>SKILL.md</code> với cấu trúc YAML chuẩn hóa:</p>\n          <div class=\"code\">\n            <div><span>CẤU TRÚC SKILL.MD CHUẨN TRONG ANTIGRAVITY</span></div>\n            <pre>---\nname: security-auditor\ndescription: Tự động quét lỗ hổng OWASP Top 10, SQLi, XSS và bảo vệ dữ liệu PII theo Luật BV DLCN 2025.\n---\n\n# Hướng dẫn Kỹ sư Bảo mật\n1. Khi phát hiện mã nguồn xử lý dữ liệu người dùng, kiểm tra cơ chế escape/sanitize.\n2. Tuyệt đối cấm hardcode API Key, mật khẩu, JWT token trong file mã nguồn.\n3. Tạo báo cáo bảo mật dưới dạng bảng kiểm tra ĐẠT / CẢNH BÁO / NGUY HIỂM.</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>4. Trình duyệt kiểm thử tự động Browser Subagent</h3>\n          <p>Antigravity tích hợp một <em>Browser Subagent</em> chạy Chromium ngầm. Nó có thể:</p>\n          <ul>\n            <li>Tự động mở trang web cục bộ (<code>http://localhost:3000</code>).</li>\n            <li>Bấm vào các nút, nhập văn bản vào các ô input và chuyển đổi giữa các tab.</li>\n            <li>Chụp ảnh màn hình (screenshot) và quay video WebP để báo cáo trực quan cho bạn thấy giao diện thực tế.</li>\n            <li>Tự động đọc Console log để phát hiện các lỗi JavaScript ẩn mà mắt thường không thấy.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>5. Bộ lệnh Slash Commands chuyên sâu &amp; Context Cache</h3>\n          <p>Antigravity cung cấp các lệnh tương tác nhanh (Slash Commands) giúp tối ưu hóa hiệu suất làm việc:</p>\n          <div class=\"mini-table\">\n            <div><b>Lệnh</b><b>Công dụng</b><b>Ví dụ sử dụng</b></div>\n            <div><span><code>/goal</code></span><span>Kích hoạt chế độ chạy tự động liên tục cho đến khi đạt mục tiêu kiểm thử.</span><span><code>/goal Xây dựng hoàn tất module điểm danh và đạt 100% test</code></span></div>\n            <div><span><code>/grill-me</code></span><span>Kích hoạt chế độ phỏng vấn phản biện để làm rõ yêu cầu trước khi lập kế hoạch.</span><span><code>/grill-me về luồng duyệt đơn xin hoãn thi</code></span></div>\n            <div><span><code>/schedule</code></span><span>Đặt lịch thực thi tác vụ định kỳ (Cron) hoặc hẹn giờ tự động.</span><span><code>/schedule CronExpression=\"0 9 * * *\" Prompt=\"Quét lỗi bảo mật\"</code></span></div>\n            <div><span><code>/learn</code></span><span>Lưu lại kinh nghiệm và pattern đã giải quyết thành tri thức cho các phiên sau.</span><span><code>/learn Cách fix lỗi tiếng Việt UTF-8 khi xuất CSV</code></span></div>\n          </div>\n        </section>\n\n        <section>\n          <h3>6. Cấu hình file quy tắc GEMINI.md chuẩn</h3>\n          <p>Tạo file <code>GEMINI.md</code> tại thư mục gốc của dự án để ép Antigravity tuân thủ các chuẩn mực phát triển:</p>\n          <div class=\"code\">\n            <div><span>GEMINI.md - QUY TẮC BẮT BUỘC DỰ ÁN</span></div>\n            <pre># Quy tắc dự án cho Antigravity 2.0\n1. Luôn tạo và cập nhật `implementation_plan.md` trước khi viết mã.\n2. Viết mã HTML5/CSS ngữ nghĩa, chuẩn W3C, không dùng thư viện nặng khi chưa yêu cầu.\n3. Khi sửa CSS, luôn kiểm tra hiển thị trên điện thoại di động (Mobile) và máy tính (Desktop).\n4. Sử dụng Sequential Thinking để giải quyết các bài toán logic phức tạp.\n5. Tuyệt đối không đưa dữ liệu thật của sinh viên, bệnh nhân hay mật khẩu vào mã nguồn.</pre>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 4 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"4\">✓ Đánh dấu đã đọc chương 4</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-3\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 03: Chuẩn bị Workspace</span>\n          </a>\n          <a href=\"#chapter-5\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 05: OpenAI Codex</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-5":"    <article class=\"ebook-page\" id=\"chapter-5\" data-chapter=\"5\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">05</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 05 · PHẦN II <span>· 30 PHÚT ĐỌC</span></p>\n          <h2>Làm Chủ OpenAI Codex: Desktop App, CLI &amp; AGENTS.md</h2>\n          <p class=\"chapter-subtitle\">Công cụ lập trình AI thế hệ mới từ OpenAI với môi trường Sandbox cô lập và khả năng thực thi lệnh terminal mạnh mẽ.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Sử dụng thành thạo Codex Desktop &amp; CLI; hiểu cơ chế Sandbox an toàn; thiết lập cây phân cấp file AGENTS.md; sử dụng cây phân nhánh Session Branching để thử nghiệm nhiều hướng giải quyết và xử lý xung đột mã nguồn.</span>\n      </div>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">🤖 Hình 5.1: Giao diện thực tế OpenAI Codex Desktop &amp; CLI</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/official_ui/codex_app.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/official_ui/codex_app.webp\" alt=\"Giao diện OpenAI Codex Desktop: Session Tree, Terminal Sandbox, Diff Reviewer\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 5.1:</em> Không gian làm việc của OpenAI Codex với cơ chế xem trước Diff màu sắc, cây phiên làm việc (Session Tree) và bảng điều khiển Sandbox cô lập an toàn.\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: OPENAI CODEX -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Hướng Dẫn Thực Chiến</span>\n                📺 Video Hướng Dẫn: Làm Chủ OpenAI Codex &amp; Kỷ Luật Lập Trình Tác Nhân\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=PqxPSzeoVQU\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"Hướng Dẫn Sử Dụng OpenAI Codex — Quản Trị Phiên, Terminal Sandbox &amp; File AGENTS.md\"</div>\n              <div class=\"video-channel-tag\"><span>Chuyên đề: OpenAI Codex &amp; Reasoning Models</span> • Video Thực Hành</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=PqxPSzeoVQU\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Kinh nghiệm thực chiến:</strong> Hướng dẫn chi tiết cách khai thác sức mạnh của OpenAI Codex, vận hành môi trường Terminal Sandbox an toàn, quản lý cây phân nhánh Session Branching và tối ưu hạn ngạch Token.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 01:15 — Giao diện Codex Desktop &amp; CLI</span>\n                <span class=\"video-stamp-pill\">⏱️ 06:20 — Cơ chế Sandbox &amp; Duyệt Diff</span>\n                <span class=\"video-stamp-pill\">⏱️ 12:40 — Thiết lập file nội quy AGENTS.md</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>1. Kiến trúc nền tảng và mô hình suy luận của Codex</h3>\n          <p>OpenAI Codex không chỉ là một chatbot lập trình thông thường. Nền tảng của nó là các mô hình lý luận chuyên biệt (Reasoning Models), đặc biệt là dòng <strong>o3, o3-mini và GPT-4o</strong>, được tối ưu hóa cho bài toán lập trình đa bước có điều kiện ràng buộc phức tạp.</p>\n          <p>Điểm khác biệt cốt lõi so với các chatbot thông thường là Codex hoạt động theo mô hình <strong>tác nhân thực thi (Execution Agent)</strong>: nó không chỉ <em>sinh văn bản mô tả giải pháp</em> mà còn <em>thực sự chạy các lệnh trong môi trường sandbox</em>, quan sát đầu ra, phân tích kết quả và tự điều chỉnh hướng đi cho đến khi đạt mục tiêu. Cơ chế này gọi là <strong>vòng lặp Observe-Plan-Execute-Verify (OPEV)</strong>:</p>\n          <ol>\n            <li><strong>Observe (Quan sát):</strong> Codex đọc toàn bộ mã nguồn trong thư mục dự án, phân tích cấu trúc file và nội dung AGENTS.md để nắm bối cảnh.</li>\n            <li><strong>Plan (Lên kế hoạch):</strong> Codex tự phân rã yêu cầu thành các nhiệm vụ nhỏ có thứ tự thực hiện rõ ràng và dự đoán các rủi ro kỹ thuật.</li>\n            <li><strong>Execute (Thực thi):</strong> Codex viết mã, chạy lệnh trong Sandbox, xem kết quả và tiếp tục điều chỉnh cho đến khi đạt kết quả mong muốn.</li>\n            <li><strong>Verify (Xác minh):</strong> Codex chạy các bộ test (pytest, jest) để tự kiểm tra tính đúng đắn của mã nguồn vừa tạo trước khi trình kết quả cho người dùng.</li>\n          </ol>\n        </section>\n\n        <section>\n          <h3>2. Terminal Sandbox: Pháo đài an toàn cho tự động hóa</h3>\n          <p>Đây là tính năng phân biệt Codex khỏi tất cả các AI khác. Mọi lệnh terminal mà Codex cần thực thi đều chạy trong một <strong>môi trường container cô lập hoàn toàn</strong>, không có quyền truy cập vào file system thật của bạn nếu không được cấp phép rõ ràng.</p>\n          <p>Codex hỗ trợ 3 chế độ phê duyệt (Approval Mode) khác nhau:</p>\n          <div class=\"mini-table\">\n            <div><b>Chế độ</b><b>Cờ lệnh</b><b>Hành vi</b><b>Dùng khi nào</b></div>\n            <div><span><b>Tự động hoàn toàn</b></span><span><code>--approval-mode auto</code></span><span>Tự chạy mọi lệnh mà không hỏi</span><span>Môi trường CI/CD đáng tin cậy</span></div>\n            <div><span><b>Thủ công (khuyến nghị)</b></span><span><code>--approval-mode manual</code></span><span>Hỏi xác nhận trước mỗi lệnh</span><span>Dự án thực tế, code quan trọng</span></div>\n            <div><span><b>Chỉ đọc</b></span><span><code>--approval-mode suggest</code></span><span>Chỉ đề xuất, không thực thi</span><span>Rà soát, phân tích bảo mật</span></div>\n          </div>\n          <div class=\"code\">\n            <div><span>CÁC LỆNH CODEX CLI THIẾT YẾU</span></div>\n            <pre># Cài đặt Codex CLI toàn cục\nnpm install -g @openai/codex\n\n# Khởi động phiên làm việc chế độ thủ công (an toàn nhất)\ncodex --approval-mode manual\n\n# Yêu cầu Codex phân tích bảo mật, không sửa file\ncodex --approval-mode suggest \"Rà soát toàn bộ thư mục /api và liệt kê các lỗ hổng SQL Injection tiềm năng\"\n\n# Yêu cầu Codex cài dependencies và chạy test\ncodex \"Cài đặt jest, tạo file test cơ bản cho module auth.js và chạy npm test\"\n\n# Yêu cầu với giới hạn thư mục cụ thể\ncodex --workspace ./backend \"Refactor hàm validateUser để hỗ trợ OAuth2\"</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Phân cấp quy tắc AGENTS.md: Hệ thống điều lệ của dự án</h3>\n          <p>File <code>AGENTS.md</code> là \"hiến pháp\" của dự án dành cho Codex. Hệ thống đọc file này theo <strong>cấu trúc phân cấp thư mục</strong>: file ở thư mục gốc áp dụng cho toàn dự án, file ở thư mục con sẽ kế thừa và ghi đè cho phạm vi đó. Đây là một ưu điểm mạnh hơn file GEMINI.md của Antigravity vì cho phép quy tắc chi tiết theo từng module.</p>\n          <div class=\"code\">\n            <div><span>CẤU TRÚC AGENTS.md TOÀN DIỆN CHO DỰ ÁN</span></div>\n            <pre># ======================================================================\n# AGENTS.md - Điều lệ tự động hóa toàn dự án (ROOT LEVEL)\n# Phiên bản: 2.0 | Áp dụng cho: Google Antigravity, OpenAI Codex, Claude\n# ======================================================================\n\n## 1. NGUYÊN TẮC BẤT BIẾN (Không bao giờ vi phạm)\n- **Không xóa mã nguồn cũ** nếu chưa có sự xác nhận rõ ràng từ người dùng.\n- **Không tự ý tạo thêm tính năng** nằm ngoài phạm vi v1 trong SPEC.md.\n- **Không hardcode** API Key, password, connection string vào bất kỳ file nào.\n- **Không xóa file SPEC.md, AGENTS.md** hoặc bất kỳ tài liệu dự án nào.\n\n## 2. NGÔN NGỮ VÀ TECH STACK\n- Frontend: HTML5 ngữ nghĩa, Vanilla CSS/JavaScript (không dùng jQuery).\n- Backend: Node.js (Express) hoặc Python (FastAPI) theo SPEC.md.\n- Database: SQLite (phát triển cục bộ), PostgreSQL (production).\n- Deployment: Vercel (frontend), Railway (backend).\n\n## 3. QUY ƯỚC ĐẶT TÊN MÃ NGUỒN\n- Hàm JavaScript/Python: camelCase hoặc snake_case tùy ngôn ngữ.\n- Hằng số: UPPER_SNAKE_CASE (ví dụ: MAX_RETRY_COUNT).\n- Tên file: lowercase-kebab-case (ví dụ: user-auth.js, api-gateway.py).\n- Database table/column: snake_case (ví dụ: user_profiles, created_at).\n\n## 4. PHONG CÁCH PHẢN HỒI\n- Sau mỗi lần thực thi, tóm tắt: (1) Những file đã thay đổi, (2) Lý do thay đổi, (3) Bước tiếp theo đề xuất.\n- Khi gặp điểm không rõ trong yêu cầu, HỎI TRƯỚC khi làm.\n- Luôn viết comment tiếng Việt cho logic phức tạp.\n\n## 5. TEST VÀ ĐẢM BẢO CHẤT LƯỢNG\n- Viết unit test cho mọi hàm xử lý nghiệp vụ cốt lõi.\n- Sau khi sửa bug, chạy `npm test` hoặc `pytest` để kiểm tra hồi quy.\n- Báo cáo bao phủ test (Coverage) nếu được yêu cầu.</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>4. Session Tree &amp; Branching: Thử nghiệm song song các giải pháp</h3>\n          <p>Đây là tính năng độc quyền của Codex Desktop không có trên bất kỳ AI coding tool nào khác. Session Tree cho phép bạn <strong>rẽ nhánh phiên làm việc như Git</strong> — từ một điểm gốc, bạn có thể thử nghiệm nhiều hướng tiếp cận song song mà không làm ảnh hưởng lẫn nhau.</p>\n          <div class=\"hint\">\n            <strong>VÍ DỤ THỰC TẾ — PHÂN TÍCH LỰA CHỌN KIẾN TRÚC CSDL:</strong><br>\n            Bạn đang phân vân giữa SQLite và PostgreSQL cho hệ thống quản lý đơn hàng 10,000 bản ghi/ngày.<br><br>\n            <strong>Nhánh A (SQLite):</strong> Tạo từ commit gốc → Codex xây dựng phiên bản SQLite → Chạy benchmark 10,000 bản ghi → Đo thời gian query: 45ms trung bình.<br>\n            <strong>Nhánh B (PostgreSQL):</strong> Tạo từ cùng commit gốc → Codex xây dựng phiên bản PostgreSQL + index → Chạy cùng benchmark → Thời gian query: 8ms với full-text search.<br><br>\n            Kết quả: Bạn so sánh trực quan trên Session Tree và chọn nhánh B. Codex merge nhánh B vào nhánh chính chỉ với một cú click.\n          </div>\n          <p>Quy trình sử dụng Session Branching chuyên nghiệp:</p>\n          <ol>\n            <li><strong>Commit điểm khởi đầu:</strong> Trước khi rẽ nhánh, đảm bảo codebase ổn định và đã được kiểm thử cơ bản.</li>\n            <li><strong>Tạo nhánh thử nghiệm:</strong> Click \"Branch Session\" trên giao diện Codex Desktop hoặc dùng lệnh <code>codex branch \"Thử kiến trúc microservices\"</code>.</li>\n            <li><strong>Thử nghiệm độc lập:</strong> Mỗi nhánh hoạt động hoàn toàn độc lập — bao gồm file system và terminal sandbox riêng.</li>\n            <li><strong>So sánh và quyết định:</strong> Xem diff giữa các nhánh, kiểm tra kết quả test và chọn nhánh tốt nhất.</li>\n            <li><strong>Merge hoặc Abandon:</strong> Apply nhánh được chọn vào project thật, các nhánh thất bại được xóa sạch không để lại vết.</li>\n          </ol>\n        </section>\n\n        <section>\n          <h3>5. Visual Diff Reviewer: Quyền kiểm soát tối cao của lập trình viên</h3>\n          <p>Mọi thay đổi Codex đề xuất đều phải đi qua <strong>màn hình Visual Diff</strong> trước khi được ghi vào file thật. Đây là cơ chế bảo vệ quan trọng nhất, ngăn chặn trường hợp AI tự ý thay đổi logic quan trọng mà bạn không nhận ra.</p>\n          <p>Cách đọc màn hình Visual Diff hiệu quả:</p>\n          <ul>\n            <li><strong>Dòng màu xanh lá (+):</strong> Mã mới được thêm vào — luôn đọc kỹ để đảm bảo logic đúng với ý định.</li>\n            <li><strong>Dòng màu đỏ (-):</strong> Mã cũ bị xóa — kiểm tra xem có logic nghiệp vụ quan trọng nào đang bị xóa không.</li>\n            <li><strong>Dòng xám (context):</strong> Mã không thay đổi, hiển thị để bạn hiểu ngữ cảnh xung quanh.</li>\n            <li><strong>Header @@ -10,7 +10,15 @@:</strong> Cho biết thay đổi bắt đầu từ dòng 10, cũ có 7 dòng, mới có 15 dòng.</li>\n          </ul>\n          <div class=\"hint\">\n            <strong>THÓI QUEN CHUYÊN NGHIỆP KHI REVIEW DIFF:</strong><br>\n            Trước khi bấm \"Apply Changes\", hãy kiểm tra 3 điều: (1) Có dòng xóa nào chứa logic xử lý lỗi quan trọng không? (2) Có dòng thêm nào giới thiệu dependency mới không cần thiết không? (3) Có bất kỳ thông tin nhạy cảm nào (key, password, token) xuất hiện trong diff không? Nếu có bất kỳ dấu hiệu đáng ngờ nào, hãy chọn \"Request Changes\" thay vì \"Apply\".\n          </div>\n        </section>\n\n        <section>\n          <h3>6. Tích hợp Codex vào quy trình CI/CD chuyên nghiệp</h3>\n          <p>Codex CLI không chỉ dùng cho phát triển thủ công — nó có thể chạy tự động trong pipeline CI/CD như một bước tự động hóa thông minh:</p>\n          <div class=\"code\">\n            <div><span>GITHUB ACTIONS - TÍCH HỢP CODEX REVIEW TỰ ĐỘNG</span></div>\n            <pre\">name: AI Code Review với Codex\non: [pull_request]\n\njobs:\n  codex-review:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      \n      - name: Cài đặt Codex CLI\n        run: npm install -g @openai/codex\n        \n      - name: Yêu cầu Codex rà soát PR\n        env:\n          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}\n        run: |\n          codex --approval-mode suggest             \"Rà soát các thay đổi trong PR này. Kiểm tra:             1) Lỗ hổng bảo mật,             2) Hiệu suất query database,             3) Tính nhất quán với coding convention trong AGENTS.md.             Xuất báo cáo dạng Markdown.\" > review_report.md\n          \n      - name: Đăng báo cáo vào PR Comment\n        uses: actions/github-script@v7\n        with:\n          script: |\n            const fs = require('fs')\n            const report = fs.readFileSync('review_report.md', 'utf8')\n            github.rest.issues.createComment({\n              issue_number: context.issue.number,\n              owner: context.repo.owner,\n              repo: context.repo.repo,\n              body: '## 🤖 Báo cáo rà soát bởi Codex AI\n\n' + report\n            })</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>7. So sánh chuyên sâu: Codex vs Antigravity cho từng tác vụ cụ thể</h3>\n          <div class=\"mini-table\">\n            <div><b>Tác vụ</b><b>Dùng Codex</b><b>Dùng Antigravity</b></div>\n            <div><span><b>Viết unit test hàng loạt</b></span><span>✅ Ưu tiên — Sandbox chạy test thật, kiểm tra coverage</span><span>✅ Tốt — Nhưng không chạy test tự động</span></div>\n            <div><span><b>Refactor module lớn (500+ dòng)</b></span><span>✅ Ưu tiên — Session Branching an toàn</span><span>⚠️ Dùng được nhưng cần thận trọng hơn</span></div>\n            <div><span><b>Debug lỗi runtime phức tạp</b></span><span>✅ Ưu tiên — Chạy code thật trong sandbox để tái hiện lỗi</span><span>⚠️ Phân tích tĩnh, không chạy được code</span></div>\n            <div><span><b>Lập kế hoạch kiến trúc</b></span><span>⚠️ Dùng được nhưng thiếu context dài</span><span>✅ Ưu tiên — 1M+ token context, sinh Artifacts</span></div>\n            <div><span><b>Kiểm thử UI Playwright</b></span><span>❌ Không hỗ trợ browser automation</span><span>✅ Ưu tiên — Browser Subagent tích hợp sẵn</span></div>\n            <div><span><b>Cài package và migrate DB</b></span><span>✅ Ưu tiên — Chạy npm/pip/migration thật trong sandbox</span><span>❌ Không thực thi lệnh terminal</span></div>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 5 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"5\">✓ Đánh dấu đã đọc chương 5</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-4\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 04: Google Antigravity</span>\n          </a>\n          <a href=\"#chapter-6\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 06: Claude Desktop &amp; MCP</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-6":"    <article class=\"ebook-page\" id=\"chapter-6\" data-chapter=\"6\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">06</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 06 · PHẦN II <span>· 30 PHÚT ĐỌC</span></p>\n          <h2>Làm Chủ Claude Desktop &amp; Claude Code: Hệ Sinh Thái MCP</h2>\n          <p class=\"chapter-subtitle\">Kết nối Claude với toàn bộ dữ liệu nội bộ qua Model Context Protocol (MCP) và công cụ dòng lệnh Claude Code.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Hiểu sâu giao thức chuẩn mở MCP (Model Context Protocol); cấu hình claude_desktop_config.json kết nối CSDL SQLite, GitHub và File System; làm chủ Claude Code CLI và kỹ năng tận dụng Extended Thinking để tái cấu trúc hệ thống lớn.</span>\n      </div>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">⚡ Hình 6.1: Giao diện Claude Desktop và Kiến trúc MCP Client-Server</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/official_ui/mcp_architecture.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/official_ui/mcp_architecture.webp\" alt=\"Giao diện Claude Desktop và sơ đồ giao thức MCP kết nối PostgreSQL, GitHub, Local Files\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 6.1:</em> Chuẩn mở <strong>Model Context Protocol (MCP)</strong>: Claude đóng vai trò Host/Client, kết nối bảo mật với các MCP Server (CSDL, Google Drive, Hệ thống file nội bộ).\n            </div>\n          </div>\n\n          <!-- YOUTUBE GUIDELINE: CLAUDE DESKTOP & MCP -->\n          <div class=\"video-guideline-box\">\n            <div class=\"video-guideline-header\">\n              <span class=\"video-guideline-title\">\n                <span class=\"video-guideline-badge\">Kênh Huy Dao</span>\n                📺 Video Hướng Dẫn: Làm Chủ Claude Desktop &amp; Hệ Sinh Thái Tác Nhân AI\n              </span>\n              <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=XSpYx8IEk6c\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n            </div>\n            <div class=\"video-card-banner\">\n              <div class=\"video-topic\">🎬 \"Hướng Dẫn Sử Dụng Claude AI: Từ Cơ Bản Đến Nâng Cao (Desktop App, Cowork, Code &amp; Computer Use)\"</div>\n              <div class=\"video-channel-tag\"><span>Kênh: Huy Dao</span> • Video Thực Hành Toàn Diện</div>\n              <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=XSpYx8IEk6c\" target=\"_blank\" rel=\"noopener\">\n                ▶ Xem Video Trên YouTube\n              </a>\n            </div>\n            <div class=\"video-guideline-body\">\n              <strong>Điểm nhấn kỹ thuật:</strong> Hướng dẫn toàn diện cách sử dụng Claude Desktop, kích hoạt chế độ Code/Cowork, điều khiển máy tính an toàn và khai thác chuẩn kết nối MCP vạn năng.\n              <div class=\"video-guideline-timestamps\">\n                <span class=\"video-stamp-pill\">⏱️ 02:15 — Ứng dụng Claude Desktop &amp; Giao diện</span>\n                <span class=\"video-stamp-pill\">⏱️ 08:30 — Chế độ Code, Cowork &amp; Project</span>\n                <span class=\"video-stamp-pill\">⏱️ 15:40 — Điều khiển máy tính &amp; Kỹ năng mở rộng</span>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>1. Sức mạnh vượt trội của Claude 3.7 Sonnet &amp; Extended Thinking</h3>\n          <p>Mô hình Claude 3.7 Sonnet từ Anthropic mang đến khả năng <em>Lập luận mở rộng (Extended Thinking)</em>. Trước khi trả lời, mô hình tự động dành ra hàng nghìn token suy luận nội tâm (Internal Reasoning Tokens) — một quá trình tương đương với việc một kỹ sư cấp cao ngồi \"vẽ nháp\" trên tờ giấy trước khi đưa ra kết luận chính thức.</p>\n          <p>Điều này biến Claude thành chuyên gia số một cho 3 nhóm tác vụ đặc thù:</p>\n          <ul>\n            <li><strong>Thiết kế kiến trúc ban đầu:</strong> Claude có thể xem xét toàn bộ yêu cầu, đánh giá nhiều phương án kiến trúc (Monolith vs Microservices, SQL vs NoSQL), phân tích ưu nhược điểm và đề xuất lựa chọn tối ưu với lý giải chi tiết.</li>\n            <li><strong>Phát hiện lỗi logic bảo mật:</strong> Extended Thinking cho phép Claude \"suy nghĩ\" qua từng nhánh thực thi của mã nguồn, phát hiện các trường hợp IDOR, race condition và SQL Injection tinh vi mà phân tích tĩnh thông thường bỏ sót.</li>\n            <li><strong>Tái cấu trúc (Refactoring) module phức tạp:</strong> Claude có thể đọc toàn bộ 2,000 dòng mã legacy, hiểu đầy đủ ý nghĩa kinh doanh và tái cấu trúc mà không phá vỡ bất kỳ behavior nào đang hoạt động.</li>\n          </ul>\n          <p>Cách kích hoạt Extended Thinking khi làm việc với Claude:</p>\n          <div class=\"prompt\">\n            <b>PROMPT MẪU KÍCH HOẠT EXTENDED THINKING:</b>\n            <p>Hãy suy nghĩ thật sâu và toàn diện (Extended Thinking) trước khi trả lời. Chúng tôi cần thiết kế kiến trúc xác thực người dùng cho hệ thống SaaS với 50,000 người dùng đồng thời. Hãy phân tích ít nhất 3 phương án (JWT + Refresh Token, Session-based, OAuth2 PKCE), so sánh độ phức tạp triển khai, độ bảo mật, khả năng mở rộng và chi phí vận hành. Sau đó đưa ra đề xuất cuối cùng có kèm lý do kỹ thuật.</p>\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Toàn tập về Model Context Protocol (MCP): Kiến trúc và Nguyên lý</h3>\n          <p>MCP là chuẩn giao thức mở do Anthropic phát triển vào cuối 2024, nhanh chóng trở thành tiêu chuẩn ngành được tất cả các nhà cung cấp AI lớn (OpenAI, Google) chấp thuận. Nó giải quyết bài toán lớn nhất của AI trong doanh nghiệp: <em>làm sao để AI truy cập an toàn vào dữ liệu riêng tư mà không phải tải toàn bộ lên máy chủ bên thứ ba</em>.</p>\n          <p>Kiến trúc 3 tầng của MCP:</p>\n          <div class=\"mini-table\">\n            <div><b>Thành phần</b><b>Vai trò</b><b>Ví dụ thực tế</b></div>\n            <div><span><b>MCP Host</b></span><span>Ứng dụng điều phối giao diện và session người dùng</span><span>Claude Desktop, Antigravity IDE, VS Code Extension</span></div>\n            <div><span><b>MCP Client</b></span><span>Thành phần embed trong Host, quản lý kết nối JSON-RPC 2.0</span><span>Thư viện @anthropic-ai/mcp-client</span></div>\n            <div><span><b>MCP Server</b></span><span>Tiến trình chạy cục bộ, cung cấp Tools/Resources/Prompts</span><span>mcp-server-sqlite, mcp-server-filesystem, mcp-server-github</span></div>\n          </div>\n          <p>MCP Server cung cấp 3 loại khả năng cho AI:</p>\n          <ul>\n            <li><strong>Tools (Công cụ thực thi):</strong> Các hàm mà AI có thể gọi để thực hiện hành động, ví dụ: <code>query_database(sql)</code>, <code>create_github_issue(title, body)</code>.</li>\n            <li><strong>Resources (Tài nguyên dữ liệu):</strong> Dữ liệu có địa chỉ URI mà AI có thể đọc, ví dụ: <code>sqlite:///app.db/users</code>, <code>file:///workspace/SPEC.md</code>.</li>\n            <li><strong>Prompts (Mẫu lệnh):</strong> Các mẫu prompt có tham số tái sử dụng được, ví dụ: mẫu prompt review code theo chuẩn OWASP.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>3. Hướng dẫn cấu hình claude_desktop_config.json toàn diện</h3>\n          <p>Mở file cấu hình tại <code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (macOS) hoặc <code>%APPDATA%\\Claude\\claude_desktop_config.json</code> (Windows). Đây là bản cấu hình đầy đủ cho môi trường phát triển web app:</p>\n          <div class=\"code\">\n            <div><span>claude_desktop_config.json - CẤU HÌNH MCP TOÀN DIỆN CHO WEB DEV</span></div>\n            <pre>{\n  \"mcpServers\": {\n    \"sqlite\": {\n      \"command\": \"uvx\",\n      \"args\": [\"mcp-server-sqlite\", \"--db-path\", \"/duong_dan_du_an/my_app.db\"],\n      \"description\": \"Đọc và query CSDL SQLite cục bộ an toàn\"\n    },\n    \"filesystem\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-filesystem\", \"/duong_dan_du_an/workspace/\"],\n      \"description\": \"Đọc, ghi file trong workspace được chỉ định\"\n    },\n    \"github\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-github\"],\n      \"env\": {\n        \"GITHUB_PERSONAL_ACCESS_TOKEN\": \"ghp_your_token_here\"\n      },\n      \"description\": \"Đọc issues, PR, commit history từ GitHub\"\n    },\n    \"postgres\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-postgres\",\n               \"postgresql://user:password@localhost:5432/mydb\"],\n      \"description\": \"Kết nối PostgreSQL production (chỉ đọc)\"\n    },\n    \"brave-search\": {\n      \"command\": \"npx\",\n      \"args\": [\"-y\", \"@modelcontextprotocol/server-brave-search\"],\n      \"env\": {\n        \"BRAVE_API_KEY\": \"BSA_your_brave_api_key\"\n      },\n      \"description\": \"Tìm kiếm web qua Brave Search API\"\n    }\n  }\n}</pre>\n          </div>\n          <p>Sau khi cập nhật file, khởi động lại Claude Desktop. Truy cập menu Settings → MCP để kiểm tra trạng thái kết nối của từng server (xanh = kết nối thành công, đỏ = lỗi).</p>\n        </section>\n\n        <section>\n          <h3>4. Xây dựng MCP Server tùy chỉnh cho hệ thống nội bộ</h3>\n          <p>Khi không có MCP Server sẵn có phù hợp với hệ thống nội bộ (ERP, CRM, legacy API), bạn có thể tự xây dựng MCP Server chỉ với ~50 dòng Python:</p>\n          <div class=\"code\">\n            <div><span>CUSTOM MCP SERVER - KẾT NỐI API NỘI BỘ</span></div>\n            <pre\">from mcp.server import Server\nfrom mcp.server.stdio import stdio_server\nfrom mcp import Tool\nimport httpx\nimport json\n\napp = Server(\"internal-erp-server\")\n\n@app.list_tools()\nasync def list_tools():\n    return [\n        Tool(\n            name=\"get_employee_info\",\n            description=\"Lấy thông tin nhân viên từ hệ thống HR nội bộ theo mã nhân viên\",\n            inputSchema={\n                \"type\": \"object\",\n                \"properties\": {\n                    \"employee_id\": {\n                        \"type\": \"string\",\n                        \"description\": \"Mã nhân viên (ví dụ: EMP-001)\"\n                    }\n                },\n                \"required\": [\"employee_id\"]\n            }\n        ),\n        Tool(\n            name=\"list_pending_approvals\",\n            description=\"Lấy danh sách đơn từ đang chờ phê duyệt của người quản lý\",\n            inputSchema={\n                \"type\": \"object\",\n                \"properties\": {\n                    \"manager_id\": {\"type\": \"string\"},\n                    \"limit\": {\"type\": \"integer\", \"default\": 20}\n                },\n                \"required\": [\"manager_id\"]\n            }\n        )\n    ]\n\n@app.call_tool()\nasync def call_tool(name: str, arguments: dict):\n    async with httpx.AsyncClient() as client:\n        if name == \"get_employee_info\":\n            resp = await client.get(\n                f\"https://erp.internal/api/employees/{arguments['employee_id']}\",\n                headers={\"Authorization\": f\"Bearer {INTERNAL_API_TOKEN}\"}\n            )\n            return [{\"type\": \"text\", \"text\": json.dumps(resp.json(), ensure_ascii=False)}]\n\n# Chạy server qua stdio\nasync def main():\n    async with stdio_server() as (read_stream, write_stream):\n        await app.run(read_stream, write_stream, app.create_initialization_options())\n\nif __name__ == \"__main__\":\n    import asyncio\n    asyncio.run(main())</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>5. Claude Code CLI: Lập trình trong Terminal như một cao thủ</h3>\n          <p>Claude Code là công cụ dòng lệnh chạy trực tiếp trong terminal, cho phép Claude truy cập toàn bộ codebase và thực hiện thay đổi trực tiếp lên file mà không cần giao diện đồ họa. Đây là công cụ được các kỹ sư backend ưa chuộng nhất:</p>\n          <div class=\"code\">\n            <div><span>CLAUDE CODE CLI - CÁC LỆNH THIẾT YẾU</span></div>\n            <pre># Cài đặt\nnpm install -g @anthropic-ai/claude-code\n\n# Khởi động trong thư mục dự án\ncd /path/to/your/project\nclaude\n\n# Yêu cầu không tương tác (1 lần chạy tự động)\nclaude --print \"Phân tích tất cả API endpoint trong /routes và liệt kê những endpoint thiếu middleware xác thực\"\n\n# Đọc file cụ thể trước khi tư vấn\nclaude --input-file SPEC.md \"Dựa trên spec này, hãy đề xuất schema database tối ưu\"\n\n# Chế độ chỉ đọc (không sửa file)\nclaude --no-edit \"Giải thích toàn bộ luồng xử lý đơn hàng trong codebase này\"</pre>\n          </div>\n          <p>Các tác vụ Claude Code thực hiện xuất sắc trong môi trường terminal:</p>\n          <ul>\n            <li><strong>Tìm kiếm toàn repo:</strong> <code>claude \"Tìm tất cả nơi trong codebase đang dùng console.log() để debug và đề xuất cách thay bằng proper logging\"</code></li>\n            <li><strong>Commit Git thông minh:</strong> Claude tự động phân tích diff, viết commit message mô tả đầy đủ theo Conventional Commits.</li>\n            <li><strong>Tạo migration CSDL:</strong> Claude đọc schema hiện tại và tạo file migration SQL/Prisma an toàn.</li>\n            <li><strong>Sinh tài liệu API:</strong> Claude đọc toàn bộ route handlers và tạo file OpenAPI 3.0 spec đầy đủ.</li>\n          </ul>\n        </section>\n\n        <section>\n          <h3>6. Chiến lược khai thác MCP tối đa: Mô hình 4 lớp dữ liệu</h3>\n          <div class=\"hint\">\n            <strong>MÔ HÌNH PHÂN CẤP DỮ LIỆU CHO CLAUDE + MCP:</strong><br>\n            <strong>Lớp 1 - Thời gian thực (Real-time):</strong> Kết nối MCP Server CSDL production (chỉ đọc) → Claude truy vấn số liệu mới nhất trực tiếp.<br>\n            <strong>Lớp 2 - Tài liệu dự án (Project Docs):</strong> MCP Filesystem đọc SPEC.md, AGENTS.md, README → Claude hiểu ngữ cảnh dự án đầy đủ.<br>\n            <strong>Lớp 3 - Mã nguồn (Source Code):</strong> MCP Filesystem đọc toàn bộ /src → Claude hiểu kiến trúc hiện tại trước khi đề xuất thay đổi.<br>\n            <strong>Lớp 4 - Lịch sử thay đổi (Git History):</strong> MCP GitHub đọc commit history → Claude hiểu lý do tại sao code được viết theo cách đó, tránh lặp lại lỗi cũ.\n          </div>\n          <p>Với 4 lớp này, một câu hỏi đơn giản như \"Tại sao tính năng X lại chậm?\" sẽ cho ra câu trả lời cực kỳ chính xác vì Claude có đủ bối cảnh: dữ liệu thực, kiến trúc code, và lịch sử thay đổi liên quan.</p>\n        </section>\n      </div>\n\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 6 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"6\">✓ Đánh dấu đã đọc chương 6</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-5\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 05: OpenAI Codex</span>\n          </a>\n          <a href=\"#chapter-7\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 07: So sánh &amp; Phối hợp</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-7":"    <article class=\"ebook-page\" id=\"chapter-7\" data-chapter=\"7\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">07</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 07 · PHẦN II <span>· 25 PHÚT ĐỌC</span></p>\n          <h2>Bảng So Sánh Chi Tiết &amp; Chiến Lược Phối Hợp Tam Mã</h2>\n          <p class=\"chapter-subtitle\">Không có công cụ nào hoàn hảo cho mọi việc — cách kết hợp Antigravity, Codex và Claude Desktop để đạt hiệu suất cao nhất với chi phí thấp nhất.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Đối chiếu 12 tiêu chí chuyên sâu giữa 3 Agent; nắm vững công thức phối hợp 4 giai đoạn chuẩn doanh nghiệp; làm chủ kỹ thuật chuyển giao ngữ cảnh (Context Handoff) và quản lý ngân sách Token tối ưu.</span>\n      </div>\n\n      <div class=\"body\">\n        <section class=\"wide\">\n          <div class=\"figure-showcase\">\n            <div class=\"figure-header\">\n              <span class=\"figure-title\">⚖️ Hình 7.1: Ma trận so sánh Antigravity vs Codex vs Claude Desktop</span>\n              <div class=\"figure-actions\">\n                <a class=\"figure-btn\" href=\"assets/official_ui/model_comparison_2026.webp\" target=\"_blank\">🔗 Mở ảnh gốc</a>\n                <button class=\"figure-btn zoom-btn\">🔍 Phóng to</button>\n              </div>\n            </div>\n            <div class=\"figure-img-wrap\">\n              <img src=\"assets/official_ui/model_comparison_2026.webp\" alt=\"Bảng so sánh chi tiết tính năng Antigravity vs Codex vs Claude Desktop\" loading=\"lazy\" decoding=\"async\">\n            </div>\n            <div class=\"figure-caption\">\n              <em>Hình 7.1:</em> So sánh chi tiết về <strong>Context Window</strong>, <strong>Khả năng tự động hóa Browser</strong>, <strong>Hỗ trợ Terminal Sandbox</strong> và <strong>Chi phí sử dụng</strong>.\n            </div>\n          </div>\n        </section>\n\n        <section class=\"wide\">\n          <h3>1. Ma trận so sánh 12 tiêu chí chuyên sâu</h3>\n          <div class=\"choice-table\">\n            <div><b>Tiêu chí so sánh</b><b>Google Antigravity</b><b>OpenAI Codex</b><b>Claude Desktop + MCP</b></div>\n            <div><span><b>1. Sức mạnh nổi bật nhất</b></span><span>Lập kế hoạch sâu &amp; Test UI tự động</span><span>Thực thi nhanh, quản lý git tốt</span><span>Lập luận sắc bén, mở rộng qua MCP</span></div>\n            <div><span><b>2. Công cụ độc quyền</b></span><span>Browser Subagent + Artifacts Plan</span><span>Terminal Sandbox + Session Tree</span><span>Extended Thinking + MCP Ecosystem</span></div>\n            <div><span><b>3. Dung lượng Context</b></span><span>1.000.000+ Tokens (Gemini 2.5)</span><span>128.000 - 200.000 Tokens</span><span>200.000 Tokens (Claude 3.7)</span></div>\n            <div><span><b>4. Giai đoạn tối ưu nhất</b></span><span>Lên ý tưởng, Lập Plan &amp; Nghiệm thu UI</span><span>Viết mã chi tiết, chạy test &amp; Fix bug</span><span>Thiết kế kiến trúc &amp; Đọc CSDL thật</span></div>\n            <div><span><b>5. Chi phí &amp; Hạn mức</b></span><span>Rất kinh tế với gói Google AI Pro</span><span>Theo gói ChatGPT Plus / API Token</span><span>Theo gói Claude Pro / Team / API</span></div>\n            <div><span><b>6. Khả năng chạy Terminal</b></span><span>❌ Không thực thi lệnh trực tiếp</span><span>✅ Đầy đủ — Sandbox cô lập an toàn</span><span>✅ Qua Claude Code CLI</span></div>\n            <div><span><b>7. Kiểm thử giao diện</b></span><span>✅ Browser Subagent + Playwright</span><span>❌ Không có browser automation</span><span>❌ Không có browser automation</span></div>\n            <div><span><b>8. Đọc CSDL thật</b></span><span>✅ Qua MCP tools</span><span>❌ Chỉ đọc file, không kết nối DB</span><span>✅ MCP Server PostgreSQL/SQLite</span></div>\n            <div><span><b>9. Đọc codebase lớn (100k+ dòng)</b></span><span>✅ Tốt nhất — 1M token context</span><span>⚠️ Giới hạn 128k, cần chia nhỏ</span><span>⚠️ 200k token, khá tốt</span></div>\n            <div><span><b>10. Quản lý Session Branching</b></span><span>❌ Mỗi conversation độc lập</span><span>✅ Session Tree trực quan</span><span>❌ Conversation tuyến tính</span></div>\n            <div><span><b>11. Tích hợp IDE phổ biến</b></span><span>✅ VS Code, JetBrains</span><span>✅ VS Code, Cursor, Neovim</span><span>✅ VS Code qua extension</span></div>\n            <div><span><b>12. Tạo tài liệu Artifacts</b></span><span>✅ Xuất sắc — implementation_plan, walkthrough</span><span>⚠️ Tốt nhưng không có format riêng</span><span>✅ Tốt với Extended Thinking</span></div>\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Quy trình phối hợp 4 giai đoạn chuẩn doanh nghiệp</h3>\n          <p>Chiến lược hiệu quả nhất không phải là chọn một công cụ duy nhất mà là <strong>phân công đúng người đúng việc</strong> theo từng giai đoạn của dự án. Đây là quy trình đã được kiểm chứng thực tế:</p>\n          <ol>\n            <li><strong>Giai đoạn 1 - Khám phá &amp; Lập đặc tả (Dùng Claude Desktop + MCP):</strong> Kết nối Claude với MCP Server đọc dữ liệu hiện có (CSDL sản xuất, tài liệu Google Drive, API nội bộ). Claude dùng Extended Thinking để phân tích khoảng cách giữa trạng thái hiện tại và mục tiêu. Output: <code>SPEC.md</code> chính xác, không đoán mò.</li>\n            <li><strong>Giai đoạn 2 - Lập kế hoạch kỹ thuật (Dùng Google Antigravity):</strong> Mở Antigravity, yêu cầu đọc <code>SPEC.md</code> để sinh <code>implementation_plan.md</code> chi tiết từng bước. Với context window 1M token, Antigravity đọc được toàn bộ codebase để tạo kế hoạch không xung đột với code hiện tại.</li>\n            <li><strong>Giai đoạn 3 - Viết mã &amp; Sandbox (Dùng OpenAI Codex):</strong> Thực thi từng lát cắt mã nguồn theo kế hoạch, chạy unit test trong sandbox an toàn. Dùng Session Branching để thử nghiệm các implementation thay thế nếu cần. Output: code đã qua test, không có regression.</li>\n            <li><strong>Giai đoạn 4 - Kiểm thử UI &amp; Nghiệm thu (Dùng Antigravity Browser Subagent):</strong> Tự động mở trình duyệt, click test trên các độ phân giải màn hình (máy tính, tablet, điện thoại) và chụp ảnh báo cáo <code>walkthrough.md</code>. Bàn giao sản phẩm có bằng chứng kiểm thử đầy đủ.</li>\n          </ol>\n        </section>\n\n        <section>\n          <h3>3. Kỹ thuật chuyển giao ngữ cảnh (Context Handoff) không suy hao</h3>\n          <p>Khi chuyển từ công cụ này sang công cụ khác, tuyệt đối không copy toàn bộ đoạn chat dài vì nó vừa tốn token vừa gây mất cấu trúc thông tin. Hãy áp dụng <strong>Giao thức chuyển giao 3 bước</strong>:</p>\n          <div class=\"hint\">\n            <strong>GIAO THỨC CHUYỂN GIAO NGỮ CẢNH CHUẨN:</strong><br>\n            <strong>Bước 1 — Chốt &amp; Lưu trữ:</strong> Trước khi đóng phiên làm việc với Tool A, yêu cầu AI tóm tắt: \"Hãy tổng kết những quyết định thiết kế quan trọng, các file đã tạo/sửa và bước tiếp theo vào file <code>HANDOFF.md</code>.\"<br>\n            <strong>Bước 2 — Nạp ngữ cảnh tối giản:</strong> Sang Tool B, chỉ cần gửi: \"Đọc SPEC.md, AGENTS.md và HANDOFF.md. Chúng ta đang ở Giai đoạn X. Hãy bắt đầu từ [điểm cụ thể].\"<br>\n            <strong>Bước 3 — Xác minh hiểu biết:</strong> Hỏi lại: \"Hãy tóm tắt lại những gì đã làm trước đó và bước tiếp theo.\" Nếu câu trả lời không chính xác, bổ sung ngữ cảnh còn thiếu.\n          </div>\n        </section>\n\n        <section>\n          <h3>4. Quản lý ngân sách Token tối ưu: Tránh lãng phí chi phí</h3>\n          <p>Mỗi token đều có chi phí. Đây là chiến lược quản lý ngân sách token chuyên nghiệp:</p>\n          <div class=\"hint\"><strong>Đừng nhầm Context với Quota:</strong> Context là lượng lịch sử, tệp và kết quả công cụ mà phiên hiện tại đang mang theo; tạo phiên mới có thể làm nó gọn hơn. Quota/usage là hạn mức của tài khoản theo cửa sổ thời gian, nên không tự đầy lại chỉ vì bạn mở chat mới. Khi gần hạn mức, hãy lưu <code>HANDOFF.md</code>, kiểm tra mốc reset hiển thị trong ứng dụng rồi mới quyết định tiếp tục, chờ hoặc đổi gói.</div>\n          <div class=\"mini-table\">\n            <div><b>Tình huống</b><b>Chiến lược tối ưu</b><b>Lý do</b></div>\n            <div><span><b>Đọc toàn codebase</b></span><span>Dùng Antigravity (1M context) — 1 lần</span><span>Tránh đọc nhiều lần trên tool 128k token</span></div>\n            <div><span><b>Debug lỗi nhỏ</b></span><span>Gửi đúng function bị lỗi + stack trace</span><span>Không cần gửi toàn bộ file 500 dòng</span></div>\n            <div><span><b>Refactor module</b></span><span>Codex Session Branch — thử nghiệm trước</span><span>Tránh lặp lại nhiều vòng chat sửa đi sửa lại</span></div>\n            <div><span><b>Sinh tài liệu</b></span><span>Claude + SPEC.md làm input — 1 lần sinh đủ</span><span>Extended Thinking sinh tài liệu hoàn chỉnh</span></div>\n          </div>\n        </section>\n\n        <section>\n          <h3>5. Kịch bản thực tế: Dự án quản lý đơn hàng thương mại điện tử</h3>\n          <p>Áp dụng chiến lược phối hợp tam mã cho dự án thực tế: xây dựng hệ thống quản lý đơn hàng cho doanh nghiệp 500 nhân viên:</p>\n          <div class=\"prompt\">\n            <b>TUẦN 1 — CLAUDE DESKTOP + MCP (Khám phá &amp; Đặc tả):</b>\n            <p>Claude đọc CSDL hiện tại (3 bảng, 50,000 đơn hàng), tài liệu nghiệp vụ trên Google Drive và phỏng vấn qua chat. Output: SPEC.md 15 trang với 8 luồng người dùng, 12 bảng dữ liệu, 30 kịch bản nghiệm thu Given-When-Then.</p>\n            <b>TUẦN 2 — GOOGLE ANTIGRAVITY (Lập kế hoạch kiến trúc):</b>\n            <p>Antigravity đọc SPEC.md + toàn bộ codebase legacy (8,000 dòng). Output: implementation_plan.md chia 4 sprint, 22 file cần tạo/sửa, danh sách 3 rủi ro kỹ thuật cần xử lý trước.</p>\n            <b>TUẦN 3-6 — OPENAI CODEX (Thực thi):</b>\n            <p>Codex thực hiện từng sprint theo kế hoạch. Mỗi ngày chạy 200 unit test tự động trong sandbox. Session Branching thử nghiệm 2 phương án tối ưu query database — chọn phương án nhanh hơn 3x.</p>\n            <b>TUẦN 7 — ANTIGRAVITY BROWSER SUBAGENT (Nghiệm thu):</b>\n            <p>Tự động test 15 luồng người dùng trên 3 độ phân giải. Output: walkthrough.md 40 trang với 120 ảnh chụp màn hình làm bằng chứng nghiệm thu. Bàn giao cho khách hàng với đầy đủ tài liệu.</p>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 7 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"7\">✓ Đánh dấu đã đọc chương 7</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-6\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 06: Claude Desktop &amp; MCP</span>\n          </a>\n          <a href=\"#chapter-8\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 08: Đặc tả Spec-Driven</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-8":"    <article class=\"ebook-page\" id=\"chapter-8\" data-chapter=\"8\">\n      <div class=\"part-lead-header\">\n        <span class=\"part-tag\">PHẦN III · QUY TRÌNH THỰC THI</span>\n        <h2>Quy Trình Xây Dựng Ứng Dụng Từ A Đến Z</h2>\n        <p>Thực hành trọn vẹn quy trình công nghiệp: từ thiết kế giao diện trực quan bằng Google Stitch, thiết kế dữ liệu, phân quyền bảo mật đến đặc tả kỹ thuật và xuất bản ứng dụng lên Production.</p>\n      </div>\n\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">08</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 08 · PHẦN III <span>· 25 PHÚT ĐỌC</span></p>\n          <h2>Thiết Kế Giao Diện UI/UX Hiện Đại Với Google Stitch</h2>\n          <p class=\"chapter-subtitle\">Giao diện đẹp không phải là ngẫu nhiên — biến ý tưởng thành giao diện sống động với Prompt-to-UI, tối ưu di động và Design System tinh gọn.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Sử dụng Google Stitch để sinh nhanh giao diện từ Prompt; làm chủ bộ biến CSS Design Tokens (màu sắc HSL, khoảng cách); thiết kế co giãn đa thiết bị (Mobile &amp; Desktop); đảm bảo tương phản rõ nét và xử lý đủ 5 trạng thái màn hình.</span>\n      </div>\n\n      <div class=\"body\">\n        <!-- YOUTUBE GUIDELINE: GOOGLE STITCH & THIẾT KẾ UI/UX (ĐẦU NHÓM) -->\n        <div class=\"video-guideline-box\">\n          <div class=\"video-guideline-header\">\n            <span class=\"video-guideline-title\">\n              <span class=\"video-guideline-badge\">Google Stitch UI</span>\n              📺 Video Hướng Dẫn: Thiết Kế UI/UX Cực Nhanh Bằng Prompt-to-UI &amp; Google Stitch\n            </span>\n            <a class=\"video-guideline-link\" href=\"https://www.youtube.com/watch?v=bJosdenauog\" target=\"_blank\" rel=\"noopener\">Mở trên YouTube ↗</a>\n          </div>\n          <div class=\"video-card-banner\">\n            <div class=\"video-topic\">🎬 \"Thiết Kế Giao Diện Trực Quan: Biến Prompt Thành Giao Diện Web Chuẩn UI/UX Trong 3 Phút Với Google Stitch\"</div>\n            <div class=\"video-channel-tag\"><span>Chuyên đề: Google Stitch &amp; Prompt-to-UI</span> • Video Thực Hành</div>\n            <a class=\"video-play-btn\" href=\"https://www.youtube.com/watch?v=bJosdenauog\" target=\"_blank\" rel=\"noopener\">\n              ▶ Xem Video Trên YouTube\n            </a>\n          </div>\n          <div class=\"video-guideline-body\">\n            <strong>Thực chiến Prompt-to-UI:</strong> Hướng dẫn cách dùng Google Stitch để chuyển đổi văn bản mô tả thành bản vẽ giao diện hoàn chỉnh, xuất mã nguồn HTML/CSS chuẩn Responsive và tinh chỉnh trải nghiệm người dùng không cần code tay.\n            <div class=\"video-guideline-timestamps\">\n              <span class=\"video-stamp-pill\">⏱️ 01:20 — Giới thiệu Google Stitch &amp; Prompt-to-UI</span>\n              <span class=\"video-stamp-pill\">⏱️ 06:10 — Cấu trúc Prompt đặc tả giao diện</span>\n              <span class=\"video-stamp-pill\">⏱️ 12:45 — Xuất mã nguồn HTML/CSS &amp; Ghép vào dự án</span>\n            </div>\n          </div>\n        </div>\n\n        <section>\n          <h3>1. Quy trình \"Prompt-to-UI\" với Google Stitch: Ra kết quả trong 3 phút</h3>\n          <p>Thay vì phải ngồi viết từng dòng CSS thủ công từ con số không, bạn sử dụng <strong>Google Stitch</strong> (hoặc AI UI Generator của Google Antigravity) để sinh ra giao diện sống động và xuất mã nguồn HTML5/CSS sạch sẽ. Quy trình 3 bước thực chiến:</p>\n          <div class=\"code\">\n            <div><span>QUY TRÌNH 3 BƯỚC TẠO GIAO DIỆN VỚI GOOGLE STITCH</span></div>\n            <pre>1. Viết Prompt Đặc Tả Giao Diện (Design Prompt) theo chuẩn 4 khối: Vai trò + Bố cục khung + Bảng màu HSL + 5 Trạng thái.\n2. Nạp Prompt vào Google Stitch / Antigravity UI Generator để render bản vẽ tương tác trực quan (Live Preview).\n3. Xuất mã nguồn HTML5 ngữ nghĩa &amp; Vanilla CSS co giãn (Responsive), gắn vào workspace dự án.</pre>\n          </div>\n        </section>\n\n        <!-- BỘ PROMPT THỰC CHIẾN 1-CHẠM -->\n        <section class=\"wide\">\n          <div style=\"background: linear-gradient(135deg, #0f172a, #1e293b); border: 1px solid #334155; border-radius: 14px; padding: 24px; color: #f8fafc; margin-top: 14px;\">\n            <div style=\"display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; margin-bottom: 18px;\">\n              <h4 style=\"margin: 0; font-size: 16px; color: #38bdf8; display: flex; align-items: center; gap: 8px;\">\n                <span>✨</span> Thư Viện Prompt UI/UX \"Ăn Ngay\" Cho Google Stitch &amp; AI Agent\n              </h4>\n              <span style=\"background: #0284c7; color: #ffffff; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 700;\">Sao Chép Dùng Liền</span>\n            </div>\n\n            <!-- PROMPT 1 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">📋 Mẫu 1: Dashboard Quản Trị Hành Chính (Sạch Sẽ, Chuẩn Y Khoa)</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Dùng cho Google Stitch / Antigravity</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy thiết kế giao diện Dashboard Quản trị cấp phát giấy xác nhận sinh viên bằng HTML5 và Vanilla CSS chuẩn Google Stitch.\n- Bố cục: 1 thanh Header cố định, 1 Sidebar điều hướng bên trái (có thể thu gọn trên Mobile), khu vực nội dung chính gồm 4 thẻ thống kê KPI (Tổng hồ sơ, Chờ duyệt, Đã cấp, Bị từ chối) và 1 bảng dữ liệu có thanh tìm kiếm/lọc trạng thái.\n- Phong cách: Tối giản, hiện đại, màu chủ đạo Xanh Y Khoa (#0284c7), nền thẻ xám nhạt (#f8fafc), bo góc 10px, đổ bóng nhẹ nhàng.\n- Responsive: Tự động co giãn 1 cột trên điện thoại di động, thanh toán tab mượt mà, không bị cuộn ngang tràn màn hình.</pre>\n            </div>\n\n            <!-- PROMPT 2 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">📱 Mẫu 2: Biểu Mẫu Nộp Hồ Sơ Tối Ưu Màn Hình Di Động</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Dễ chạm, không tràn viền</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Tạo biểu mẫu nộp đề nghị cấp giấy xác nhận dành cho sinh viên chạy mượt mà trên điện thoại di động (Mobile-First).\n- Yêu cầu cấu trúc: Các trường Họ tên, Mã sinh viên, Lớp, Lý do xin cấp, Nơi nhận. Có nút đính kèm ảnh chụp thẻ sinh viên.\n- UX di động: Chiều cao mọi ô nhập và nút bấm rộng rãi, dễ thao tác chạm ngón tay. Nhãn (Label) đặt phía trên ô nhập liệu.\n- Tương tác: Báo lỗi viền đỏ tức thì khi bỏ trống trường bắt buộc; khi nhấn Gửi thì đổi nút thành trạng thái xoay loading và hiện Toast thông báo thành công.</pre>\n            </div>\n\n            <!-- PROMPT 3 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">🎭 Mẫu 3: Thiết Kế Đủ 5 Trạng Thái Màn Hình (Tránh Màn Hình Đơ)</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Empty State &amp; Skeleton Loader</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy bổ sung đầy đủ 5 trạng thái giao diện cho trang danh sách hồ sơ:\n1. Ideal State: Hiển thị bảng danh sách 5 hồ sơ mẫu đầy đủ thông tin.\n2. Empty State: Khi chưa có dữ liệu, hiện hình minh họa tài liệu trống kèm thông báo \"Chưa có hồ sơ nào\" và nút \"+ Tạo hồ sơ đầu tiên\".\n3. Loading State: Khung xương Skeleton mờ lướt nhẹ (shimmer animation) trong lúc chờ nạp dữ liệu.\n4. Error State: Banner đỏ nhạt báo lỗi \"Không thể kết nối máy chủ\" kèm nút \"Thử tải lại\".\n5. Partial State: Cắt gọn tên quá dài bằng dấu ba chấm (...) và tooltip hiển thị đầy đủ khi hover.</pre>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>2. Bộ biến CSS Design Tokens đồng nhất giao diện</h3>\n          <p>Yêu cầu AI khai báo toàn bộ hệ thống biến tại <code>:root</code> để giao diện sinh ra từ Google Stitch gắn kết hài hòa với toàn bộ trang:</p>\n          <div class=\"code\">\n            <div><span>CSS DESIGN TOKENS CHUẨN</span></div>\n            <pre>:root {\n  /* Bảng màu phân cấp */\n  --primary: #0284c7;\n  --primary-hover: #0369a1;\n  --accent: #6366f1;\n  --success: #10b981;\n  --warning: #f59e0b;\n  --danger: #ef4444;\n  \n  /* Màu nền &amp; Văn bản */\n  --bg-page: #ffffff;\n  --bg-card: #f8fafc;\n  --text-main: #0f172a;\n  --text-muted: #64748b;\n  --border-color: #e2e8f0;\n\n  /* Typography &amp; Spacing */\n  --font-body: 'Be Vietnam Pro', sans-serif;\n  --font-mono: 'DM Mono', monospace;\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --shadow-sm: 0 1px 3px rgba(0,0,0,0.05);\n  --shadow-md: 0 4px 14px rgba(0,0,0,0.08);\n}</pre>\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Tiêu chí kiểm tra trải nghiệm trên điện thoại di động</h3>\n          <ul>\n            <li><strong>Không cuộn ngang (No horizontal scroll):</strong> Kiểm tra trên mọi kích thước màn hình điện thoại không bị tràn mép hay vỡ khung.</li>\n            <li><strong>Khu vực chạm thoải mái:</strong> Mọi nút bấm và liên kết trên màn hình cảm ứng phải đủ rộng rãi để bấm ngón tay không bị trượt.</li>\n            <li><strong>Độ tương phản màu sắc rõ nét:</strong> Chữ màu đậm trên nền sáng giúp người dùng đọc rõ ràng trong mọi điều kiện ánh sáng.</li>\n            <li><strong>Cấu trúc chuẩn HTML5:</strong> Dùng đúng các thẻ ngữ nghĩa <code>&lt;button&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;article&gt;</code> để ứng dụng hoạt động ổn định trên mọi trình duyệt.</li>\n          </ul>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 08 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"8\">✓ Đánh dấu đã đọc chương 8</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-7\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 07: So sánh &amp; Phối hợp</span>\n          </a>\n          <a href=\"#chapter-9\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 09: Dữ liệu &amp; Bảo mật</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","chapter-9":"<article class=\"ebook-page\" id=\"chapter-9\" data-chapter=\"9\">\n      <header class=\"chapter-head\">\n        <div class=\"chapter-badge-num\">09</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHƯƠNG 09 · PHẦN III <span>· 25 PHÚT ĐỌC</span></p>\n          <h2>Bảo Mật Dữ Liệu, Phân Quyền &amp; Kiểm Thử Vượt Quyền Bằng AI</h2>\n          <p class=\"chapter-subtitle\">Vibe Coding an toàn: Thiết lập phân quyền đa vai trò, bộ testcase bảo mật và dùng AI đóng vai Hacker rà soát lỗ hổng vượt quyền tiềm ẩn.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chương:</b>\n        <span>Nắm vững 3 nguyên tắc bảo mật cơ bản trong Vibe Coding; xây dựng bộ Test Case phân quyền cho nhiều vai trò (Khách, Người nộp, Chuyên viên, Admin); sử dụng Prompt đóng vai Hacker để AI tự động dò quét các lỗ hổng vượt quyền mà mắt thường con người không thấy.</span>\n      </div>\n\n      <div class=\"body\">\n        <section>\n          <h3>1. Ba chiếc \"dây an toàn\" bảo mật người làm Vibe Coding cần biết</h3>\n          <p>Khi ra lệnh cho AI viết ứng dụng, bạn không cần phải là chuyên gia an ninh mạng hay thuộc lòng các thuật toán phức tạp. Bạn chỉ cần nắm chắc <strong>3 chiếc dây an toàn</strong> sau:</p>\n          <div class=\"mini-table\">\n            <div><b>Dây an toàn</b><b>Rủi ro nếu bỏ qua</b><b>Cách xử lý đơn giản</b></div>\n            <div><span><b>1. Khóa bí mật &amp; Dữ liệu thật</b></span><span>Lộ thông tin sinh viên/bệnh nhân, bị đánh cắp API Key</span><span>Dùng Mock data (dữ liệu giả) khi chat với AI; cất key vào file <code>.env</code></span></div>\n            <div><span><b>2. Phân quyền hiển thị &amp; Thực thi</b></span><span>Người dùng thường tự ý duyệt đơn hoặc xóa nhầm hồ sơ của người khác</span><span>Chỉ định rõ: User chỉ thấy việc của mình, chỉ Admin mới có quyền Duyệt/Xóa</span></div>\n            <div><span><b>3. Chống mất dữ liệu (F5)</b></span><span>Người dùng tải lại trang thì dữ liệu biến mất hoặc trang bị trắng đơ</span><span>Yêu cầu AI bọc hàm lưu trữ an toàn (Safe LocalStorage với try-catch)</span></div>\n          </div>\n        </section>\n\n        <!-- NĂM MÔ HÌNH KẾT NỐI DỮ LIỆU THỰC CHIẾN -->\n        <section class=\"wide\">\n          <h3>2. Năm Lựa Chọn Kết Nối Dữ Liệu Trong Vibe Coding (Từ Nhẹ Đến Nâng Cao)</h3>\n          <p>Không có một giải pháp đúng cho mọi bài toán. Tùy theo nhu cầu và độ nhạy cảm của dữ liệu, hãy chọn mô hình phù hợp:</p>\n          <div class=\"choice-table\" style=\"min-width: 820px;\">\n            <div><b>Mô hình</b><b>Cơ chế lưu trữ</b><b>Ưu điểm lớn nhất</b><b>Ranh giới an toàn cần nhớ</b></div>\n            <div>\n              <span><b>00 · LocalStorage</b></span>\n              <span>Lưu trực tiếp trong trình duyệt máy cá nhân</span>\n              <span>Không cần backend, chạy offline 100% không tốn chi phí</span>\n              <span>Chỉ dùng cho 1 người/1 máy; xóa cache trình duyệt là mất</span>\n            </div>\n            <div>\n              <span><b>01 · Google Sheets</b></span>\n              <span>Form HTML → Google Apps Script → Bảng tính</span>\n              <span>Người không biết kỹ thuật vẫn mở Excel xem và lọc báo cáo được</span>\n              <span>Không gửi tài khoản/quyển Drive cho AI; chỉ truyền dữ liệu 3-5 cột</span>\n            </div>\n            <div>\n              <span><b>02 · SQLite Backend</b></span>\n              <span>Node.js (<code>node:sqlite</code>) → file <code>noi-bo.db</code></span>\n              <span>Dữ liệu tập trung nội bộ, sao lưu cực nhanh chỉ bằng 1 file <code>.db</code></span>\n              <span>Không commit file <code>.db</code> lên Git công khai</span>\n            </div>\n            <div>\n              <span><b>03 · Supabase RLS</b></span>\n              <span>Postgres Cloud + Row Level Security</span>\n              <span>Đồng bộ nhiều người dùng thời gian thực, có xác thực tài khoản</span>\n              <span>BẮT BUỘC bật RLS (Người dùng A không được xem dòng của Người B)</span>\n            </div>\n            <div>\n              <span><b>04 · AI Backend Proxy</b></span>\n              <span>Browser → Backend giữ API Key → Gọi AI → Trả bản nháp</span>\n              <span>Bảo vệ tuyệt đối API Key, kiểm soát token và chi phí</span>\n              <span>Bật <code>MOCK_AI=true</code> trước; AI chỉ tạo nháp, con người duyệt cuối</span>\n            </div>\n          </div>\n        </section>\n\n        <!-- BẢNG TESTCASE BẢO MẬT & PHÂN QUYỀN ĐA VAI TRÒ -->\n        <section class=\"wide\">\n          <h3>3. Bảng Ma Trận Test Case Phân Quyền Đa Vai Trò (Multi-Role Security Matrix)</h3>\n          <p>Trước khi đưa ứng dụng vào sử dụng, hãy chạy thử các kịch bản sau với từng vai trò người dùng để đảm bảo không ai làm được điều vượt quá thẩm quyền:</p>\n          <div class=\"choice-table\" style=\"min-width: 800px;\">\n            <div><b>Vai trò kiểm thử</b><b>Hành động cố tình thử nghiệm</b><b>Kỳ vọng hệ thống (Phải chặn)</b><b>Đánh giá an toàn</b></div>\n            <div><span><b>1. Khách vãng lai (Guest)</b></span><span>Cố tình nhập đường link trực tiếp vào trang quản trị</span><span>Chuyển hướng ngay về trang đăng nhập hoặc trang chủ công khai</span><span>🔒 An toàn</span></div>\n            <div><span><b>2. Người nộp (Sinh viên / User)</b></span><span>Cố sửa ID trong thanh URL hoặc LocalStorage để xem đơn của người khác</span><span>Báo lỗi \"Không có quyền truy cập\", màn hình không hiển thị bất kỳ thông tin nào của đơn đó</span><span>🔒 An toàn</span></div>\n            <div><span><b>3. Người nộp (Sinh viên / User)</b></span><span>Mở F12 gõ lệnh duyệt hồ sơ hoặc tìm nút \"Phê duyệt\"</span><span>Nút bấm không tồn tại; hàm xử lý từ chối lệnh nếu không đúng mã quyền Admin</span><span>🔒 An toàn</span></div>\n            <div><span><b>4. Người nộp (Sinh viên / User)</b></span><span>Cố sửa nội dung hồ sơ khi hồ sơ đã ở trạng thái \"Đang thẩm định\"</span><span>Toàn bộ các ô nhập bị vô hiệu hóa (disabled), nút \"Lưu thay đổi\" bị ẩn</span><span>🔒 An toàn</span></div>\n            <div><span><b>5. Chuyên viên (Reviewer)</b></span><span>Thử bấm nút \"Xóa vĩnh viễn hồ sơ\"</span><span>Chuyên viên chỉ có nút \"Yêu cầu bổ sung\" và \"Duyệt chuyển tiếp\", không có quyền xóa dữ liệu</span><span>🔒 An toàn</span></div>\n            <div><span><b>6. Quản trị viên (Admin)</b></span><span>Thực hiện phê duyệt, từ chối kèm lý do hoặc khôi phục dữ liệu</span><span>Toàn quyền thao tác; mọi thao tác quan trọng đều được ghi lại vào lịch sử</span><span>🔒 An toàn</span></div>\n          </div>\n        </section>\n\n        <!-- BỘ PROMPT BẢO MẬT THỰC CHIẾN CHO VIBE CODING -->\n        <section class=\"wide\">\n          <div style=\"background: linear-gradient(135deg, #0f172a, #1e293b); border: 1px solid #334155; border-radius: 14px; padding: 24px; color: #f8fafc; margin-top: 14px;\">\n            <div style=\"display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; margin-bottom: 18px;\">\n              <h4 style=\"margin: 0; font-size: 16px; color: #38bdf8; display: flex; align-items: center; gap: 8px;\">\n                <span>🛡️</span> Thư Viện Prompt Bảo Mật &amp; Kiểm Thử Lỗ Hổng Bằng AI (Copy Dùng Ngay)\n              </h4>\n              <span style=\"background: #0284c7; color: #ffffff; padding: 3px 10px; border-radius: 20px; font-size: 11px; font-weight: 700;\">Dành Cho Vibe Coding</span>\n            </div>\n\n            <!-- PROMPT 1: RED TEAM AUDIT PROMPT (ĐẶC BIỆT MẠNH) -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #0284c7; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #38bdf8; font-size: 13.5px;\">🕵️ Prompt Đặc Biệt: Dùng AI Đóng Vai Hacker Dò Lỗ Hổng Vượt Quyền Tiềm Ẩn</b>\n                <span style=\"font-size: 10.5px; background: #0369a1; color: #fff; padding: 2px 8px; border-radius: 6px;\">Cực Kỳ Quan Trọng</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy đóng vai một chuyên gia bảo mật kiểm thử xâm nhập (White-hat Hacker / Red Team) rà soát toàn bộ mã nguồn của dự án này.\nNhiệm vụ của bạn là tìm ra TẤT CẢ các lỗ hổng phân quyền, kẽ hở vượt quyền và điểm yếu logic mà mắt thường con người không thấy:\n\n1. Lỗ hổng ẩn giao diện: Nút \"Phê duyệt\" hoặc \"Xóa\" có phải chỉ bị ẩn bằng CSS (`display: none`) nhưng nếu người dùng mở Console F12 gọi hàm JavaScript thì vẫn chạy được không?\n2. Lỗ hổng can thiệp dữ liệu: Người dùng có thể tự mở F12 sửa `localStorage` (ví dụ đổi role=\"user\" thành role=\"admin\" hoặc đổi mã sinh viên) để xem/sửa hồ sơ của người khác không?\n3. Lỗ hổng phơi bày biến toàn cục: Các hàm xử lý quan trọng có bị gắn trực tiếp vào `window` để ai cũng gọi được từ thanh địa chỉ không?\n4. Lỗ hổng chèn mã độc (XSS): Có ô nhập liệu nào đang in trực tiếp vào `innerHTML` thay vì `textContent` không?\n\nKẾT QUẢ TRẢ VỀ:\n- Lập bảng danh sách các kẽ hở tìm thấy (Mức độ: Nghiêm trọng / Trung bình / Nhẹ).\n- Hướng dẫn cách người xấu có thể khai thác kẽ hở đó.\n- Cung cấp đoạn mã đã sửa chữa (Vá lỗ hổng) theo nguyên tắc sửa đổi tối thiểu (Minimal Fix), không làm hỏng các tính năng đang chạy.</pre>\n            </div>\n\n            <!-- PROMPT 2 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">🔒 Prompt 2: Chốt chặn chống lộ thông tin bí mật &amp; Tạo dữ liệu mẫu an toàn</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Bảo vệ dữ liệu cá nhân</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy tạo một file `DU_LIEU_MAU.json` chứa 10 bản ghi hồ sơ mẫu để tôi chạy thử ứng dụng.\nRÀNG BUỘC BẢO MẬT BẮT BUỘC:\n- 100% tên người, mã số, địa chỉ phải là HƯ CẤU (ví dụ: Nguyễn Văn A, SV-2026-001).\n- TUYỆT ĐỐI KHÔNG tạo số điện thoại thật, email thật hay số căn cước công dân (CCCD).\n- Không hardcode bất kỳ API Key, mật khẩu hay token nào vào trong mã nguồn. Nếu có khóa cấu hình, hãy tạo file `.env.example` và hướng dẫn tôi cách nạp.</pre>\n            </div>\n\n            <!-- PROMPT 3 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px; margin-bottom: 14px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">👥 Prompt 3: Thiết lập phân quyền vai trò (User thường vs Quản lý)</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Chặn thao tác vượt quyền</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy bổ sung logic phân quyền người dùng đơn giản cho ứng dụng:\n1. Vai trò \"Người nộp\" (User): Chỉ xem được danh sách các hồ sơ do chính mình gửi lên; không được thấy nút \"Phê duyệt\" hay \"Từ chối\".\n2. Vai trò \"Cán bộ duyệt\" (Admin): Xem được toàn bộ hồ sơ của tất cả sinh viên; có các nút \"Duyệt\", \"Từ chối kèm lý do\" và nút \"Xuất file CSV\".\n3. Khi người dùng bấm nút xóa một mục, luôn hiện hộp thoại xác nhận: \"Bạn có chắc chắn muốn xóa mục này? Thao tác này không thể hoàn tác.\"</pre>\n            </div>\n\n            <!-- PROMPT 4 -->\n            <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid #334155; border-radius: 10px; padding: 16px;\">\n              <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                <b style=\"color: #67e8f9; font-size: 13px;\">💾 Prompt 4: Lưu trữ an toàn &amp; Chống mất dữ liệu khi nhấn F5</b>\n                <span style=\"font-size: 10.5px; color: #94a3b8;\">Bảo vệ dữ liệu LocalStorage</span>\n              </div>\n              <pre style=\"background: #020617; padding: 12px; border-radius: 8px; font-size: 12px; color: #e2e8f0; white-space: pre-wrap; margin: 0; border: 1px solid #1e293b;\">Hãy viết hàm lưu trữ dữ liệu vào LocalStorage thật an toàn và chống lỗi sập trang:\n- Mỗi khi thêm, sửa hoặc xóa dữ liệu, tự động đồng bộ ngay vào `localStorage.setItem('ten_ung_dung_data')`.\n- Khi người dùng tải lại trang (F5) hoặc mở lại trình duyệt, tự động nạp lại dữ liệu cũ đầy đủ.\n- Bắt buộc bọc khối đọc dữ liệu trong `try ... catch`. Nếu dữ liệu trong máy người dùng bị hỏng hoặc lỗi định dạng, hãy tự động nạp lại bộ dữ liệu mặc định an toàn thay vì làm trắng trang.</pre>\n            </div>\n          </div>\n        </section>\n\n        <section>\n          <h3>3. Bốn câu lệnh kiểm tra an toàn nhanh trước khi đưa vào sử dụng</h3>\n          <p>Trước khi đưa ứng dụng cho người khác dùng thử, hãy tự chạy 4 bài kiểm tra thực tế sau:</p>\n          <ul>\n            <li><strong>Thử nghiệm F5 (Tải lại trang):</strong> Nhập 2 công việc mới → Nhấn F5 xem công việc có còn nguyên không.</li>\n            <li><strong>Thử nghiệm ô trống &amp; Ký tự lạ:</strong> Thử để trống và bấm nút Gửi xem có hiện cảnh báo đỏ không; gõ chữ <code>&lt;h1&gt;Lỗi&lt;/h1&gt;</code> vào ô tên xem có bị phóng to chữ không.</li>\n            <li><strong>Thử nghiệm nút Xóa:</strong> Bấm Xóa → Nhấn \"Hủy\" trên thông báo xem dữ liệu có được giữ lại an toàn không.</li>\n            <li><strong>Quét mã nguồn tìm khóa bí mật:</strong> Đảm bảo không có chuỗi API Key hay mật khẩu thật nào bị lưu thẳng trong các file JavaScript hoặc HTML.</li>\n          </ul>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <div class=\"chapter-status-line\">\n          <span>Chương 09 / 12</span>\n          <button class=\"chapter-btn-read\" data-complete-chapter=\"9\">✓ Đánh dấu đã đọc chương 9</button>\n        </div>\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#chapter-8\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Chương 08: Thiết kế UI/UX &amp; Google Stitch</span>\n          </a>\n          <a href=\"#chapter-10\" class=\"nav-link-next\">\n            <small>CHƯƠNG TIẾP THEO →</small>\n            <span>Chương 10: Đặc tả Spec-Driven</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n","home":"<article class=\"ebook-page\" id=\"home\" style=\"padding: 0 0 60px 0;\">\n  <!-- HERO BANNER (STITCH UMP ACADEMIC VIBE) -->\n  <section class=\"stitch-hero\"\n    style=\"background: linear-gradient(135deg, #00346f 0%, #00224a 60%, #04154e 100%); color: #ffffff; border-radius: 24px; padding: 48px 44px; margin-bottom: 36px; box-shadow: 0 20px 60px rgba(0, 52, 111, 0.25); border: 1px solid rgba(255, 255, 255, 0.12); position: relative; overflow: hidden;\">\n    <!-- Background Glow Orbs -->\n    <div\n      style=\"position: absolute; right: -80px; top: -80px; width: 340px; height: 340px; border-radius: 50%; background: radial-gradient(circle, rgba(98, 176, 254, 0.25) 0%, transparent 70%); pointer-events: none;\">\n    </div>\n    <div\n      style=\"position: absolute; left: 30%; bottom: -100px; width: 280px; height: 280px; border-radius: 50%; background: radial-gradient(circle, rgba(255, 204, 0, 0.15) 0%, transparent 70%); pointer-events: none;\">\n    </div>\n\n    <div\n      style=\"display: grid; grid-template-columns: 1.15fr 0.85fr; gap: 40px; align-items: center; position: relative; z-index: 2;\">\n      <!-- Left Column: Copy & Actions -->\n      <div>\n        <div\n          style=\"display: inline-flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.1); backdrop-filter: blur(12px); border: 1px solid rgba(255, 255, 255, 0.2); padding: 6px 14px; border-radius: 999px; margin-bottom: 20px;\">\n          <span\n            style=\"display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; background: #ffcc00; color: #00346f; font-weight: 900; font-size: 11px;\">✦</span>\n          <span\n            style=\"font-family: var(--font-heading); font-size: 11.5px; font-weight: 700; color: #d7e2ff; letter-spacing: 0.8px; text-transform: uppercase;\">UMP\n            • VIBE CODING LAB</span>\n        </div>\n\n        <h1\n          style=\"font-family: var(--font-heading); font-size: clamp(32px, 3.8vw, 48px); font-weight: 800; line-height: 1.15; letter-spacing: -1.2px; margin: 0 0 16px; color: #ffffff;\">\n          Cẩm Nang Thực Chiến<br>\n          <span\n            style=\"color: #ffcc00; background: linear-gradient(135deg, #ffcc00 0%, #ffe066 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent;\">AI\n            Coding Agent</span>\n        </h1>\n\n        <p\n          style=\"font-family: var(--font-body); font-size: 15.5px; line-height: 1.65; color: #d7e2ff; margin: 0 0 28px; max-width: 540px;\">\n          Hướng dẫn toàn diện giúp cán bộ, giảng viên, sinh viên và nhân viên y tế làm chủ <strong>Google\n            Antigravity</strong>, <strong>OpenAI Codex</strong> và <strong>Claude Desktop</strong> để tự tay xây dựng\n          ứng dụng số an toàn mà không cần biết viết code.\n        </p>\n\n        <!-- Action Buttons -->\n        <div style=\"display: flex; gap: 14px; flex-wrap: wrap; align-items: center;\">\n          <a href=\"#chapter-1\"\n            style=\"background: #ffcc00; color: #00346f; font-family: var(--font-heading); font-size: 14.5px; font-weight: 800; padding: 14px 28px; border-radius: 12px; text-decoration: none; display: inline-flex; align-items: center; gap: 10px; box-shadow: 0 10px 25px rgba(255, 204, 0, 0.35); transition: transform 0.2s ease;\">\n            <span>📖 Bắt đầu đọc Ebook ngay</span>\n            <span>→</span>\n          </a>\n        </div>\n      </div>\n\n      <!-- Right Column: Hero Illustration Card -->\n      <div style=\"position: relative;\">\n        <div\n          style=\"background: rgba(255, 255, 255, 0.95); backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.4); border-radius: 18px; padding: 12px; box-shadow: 0 25px 60px rgba(0, 0, 0, 0.3); overflow: hidden;\">\n          <!-- Window Head -->\n          <div\n            style=\"display: flex; align-items: center; justify-content: space-between; padding: 6px 12px 10px; border-bottom: 1px solid #e2e8f0;\">\n            <div style=\"display: flex; gap: 6px;\">\n              <span\n                style=\"width: 10px; height: 10px; border-radius: 50%; background: #ef4444; display: inline-block;\"></span>\n              <span\n                style=\"width: 10px; height: 10px; border-radius: 50%; background: #f59e0b; display: inline-block;\"></span>\n              <span\n                style=\"width: 10px; height: 10px; border-radius: 50%; background: #10b981; display: inline-block;\"></span>\n            </div>\n            <span\n              style=\"font-family: var(--font-mono); font-size: 11px; color: #64748b; font-weight: 600;\">antigravity-ide\n              • workspace</span>\n            <span\n              style=\"background: #e0f2fe; color: #0369a1; font-family: var(--font-mono); font-size: 9.5px; font-weight: 700; padding: 2px 7px; border-radius: 4px;\">LIVE\n              AGENT</span>\n          </div>\n\n          <!-- Main Illustration -->\n          <div style=\"position: relative; border-radius: 10px; overflow: hidden; margin-top: 8px;\">\n            <img src=\"assets/official_ui/stitch_editor_workflow.webp\"\n              alt=\"Giao diện thiết kế và lập trình AI Coding Agent\"\n              style=\"width: 100%; height: auto; display: block; border-radius: 10px;\" loading=\"eager\" decoding=\"async\">\n            <!-- Floating Prompt Chip -->\n            <div\n              style=\"position: absolute; bottom: 12px; left: 12px; right: 12px; background: rgba(15, 23, 42, 0.88); backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.15); border-radius: 10px; padding: 10px 14px; display: flex; align-items: center; gap: 10px;\">\n              <span style=\"font-size: 16px;\">✨</span>\n              <span\n                style=\"font-family: var(--font-mono); font-size: 11.5px; color: #38bdf8; line-height: 1.35; flex: 1;\">\n                \"Tạo ứng dụng Bệnh nhân ảo mô phỏng lâm sàng có chấm điểm...\"\n              </span>\n              <span\n                style=\"background: #10b981; color: #ffffff; font-size: 9.5px; font-weight: 700; padding: 3px 8px; border-radius: 6px;\">READY</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- THREE CORE AGENT CARDS (TAM MÃ AI AGENT) -->\n  <section style=\"margin-bottom: 36px;\">\n    <div style=\"text-align: center; margin-bottom: 24px;\">\n      <h2 style=\"font-family: var(--font-heading); font-size: 24px; font-weight: 800; color: #04154e; margin: 0 0 6px;\">\n        Tam Mã AI Coding Agent Hàng Đầu\n      </h2>\n      <p style=\"font-size: 14px; color: #475569; margin: 0;\">\n        Lựa chọn đúng công cụ phù hợp với từng giai đoạn và mục tiêu bài toán nghiệp vụ\n      </p>\n    </div>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px;\">\n      <!-- Card 1: Google Antigravity -->\n      <div\n        style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 18px; padding: 24px; box-shadow: 0 4px 20px rgba(4, 21, 78, 0.04); transition: transform 0.2s ease; border-top: 4px solid #0284c7;\">\n        <div style=\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px;\">\n          <span\n            style=\"display: grid; place-items: center; width: 42px; height: 42px; border-radius: 12px; background: #e0f2fe; color: #0284c7; font-weight: 800; font-size: 18px;\">AG</span>\n          <span\n            style=\"font-family: var(--font-mono); font-size: 10.5px; font-weight: 700; background: #f1f5f9; color: #475569; padding: 3px 8px; border-radius: 6px;\">CHƯƠNG\n            04</span>\n        </div>\n        <h3\n          style=\"font-family: var(--font-heading); font-size: 18px; font-weight: 700; color: #0f172a; margin: 0 0 8px;\">\n          Google Antigravity</h3>\n        <p style=\"font-size: 13px; color: #475569; line-height: 1.55; margin: 0 0 16px;\">\n          Agent IDE toàn diện chạy nền tảng Gemini 2.5 / 3.0: tự động lên kế hoạch (Plan), chỉnh sửa đa tệp tin, tích\n          hợp trình duyệt và MCP Server.\n        </p>\n        <a href=\"#chapter-4\"\n          style=\"color: #0284c7; font-weight: 700; font-size: 12.5px; text-decoration: none; display: inline-flex; align-items: center; gap: 4px;\">\n          Khám phá Antigravity →\n        </a>\n      </div>\n\n      <!-- Card 2: OpenAI Codex -->\n      <div\n        style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 18px; padding: 24px; box-shadow: 0 4px 20px rgba(4, 21, 78, 0.04); transition: transform 0.2s ease; border-top: 4px solid #059669;\">\n        <div style=\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px;\">\n          <span\n            style=\"display: grid; place-items: center; width: 42px; height: 42px; border-radius: 12px; background: #dcfce7; color: #059669; font-weight: 800; font-size: 18px;\">CX</span>\n          <span\n            style=\"font-family: var(--font-mono); font-size: 10.5px; font-weight: 700; background: #f1f5f9; color: #475569; padding: 3px 8px; border-radius: 6px;\">CHƯƠNG\n            05</span>\n        </div>\n        <h3\n          style=\"font-family: var(--font-heading); font-size: 18px; font-weight: 700; color: #0f172a; margin: 0 0 8px;\">\n          OpenAI Codex</h3>\n        <p style=\"font-size: 13px; color: #475569; line-height: 1.55; margin: 0 0 16px;\">\n          Công cụ xây dựng logic tính toán, xử lý dữ liệu Excel/CSV, điều hướng quy trình tự động và kiểm soát ngoại lệ\n          bằng file AGENTS.md.\n        </p>\n        <a href=\"#chapter-5\"\n          style=\"color: #059669; font-weight: 700; font-size: 12.5px; text-decoration: none; display: inline-flex; align-items: center; gap: 4px;\">\n          Khám phá Codex →\n        </a>\n      </div>\n\n      <!-- Card 3: Claude Desktop & MCP -->\n      <div\n        style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 18px; padding: 24px; box-shadow: 0 4px 20px rgba(4, 21, 78, 0.04); transition: transform 0.2s ease; border-top: 4px solid #d97706;\">\n        <div style=\"display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px;\">\n          <span\n            style=\"display: grid; place-items: center; width: 42px; height: 42px; border-radius: 12px; background: #fef3c7; color: #d97706; font-weight: 800; font-size: 18px;\">CL</span>\n          <span\n            style=\"font-family: var(--font-mono); font-size: 10.5px; font-weight: 700; background: #f1f5f9; color: #475569; padding: 3px 8px; border-radius: 6px;\">CHƯƠNG\n            06</span>\n        </div>\n        <h3\n          style=\"font-family: var(--font-heading); font-size: 18px; font-weight: 700; color: #0f172a; margin: 0 0 8px;\">\n          Claude Desktop &amp; MCP</h3>\n        <p style=\"font-size: 13px; color: #475569; line-height: 1.55; margin: 0 0 16px;\">\n          Mô hình lý luận sâu, phân tích cấu trúc phức tạp và kết nối hệ thống mở rộng qua giao thức chuẩn Model Context\n          Protocol (MCP).\n        </p>\n        <a href=\"#chapter-6\"\n          style=\"color: #d97706; font-weight: 700; font-size: 12.5px; text-decoration: none; display: inline-flex; align-items: center; gap: 4px;\">\n          Khám phá Claude &amp; MCP →\n        </a>\n      </div>\n    </div>\n  </section>\n\n  <!-- TWO SPECIALIZED DOMAINS (CHUYÊN ĐỀ THỰC HÀNH) -->\n  <section\n    style=\"background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 20px; padding: 32px; margin-bottom: 36px;\">\n    <div\n      style=\"display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; margin-bottom: 24px;\">\n      <div>\n        <span\n          style=\"background: #00346f; color: #ffffff; font-family: var(--font-mono); font-size: 10.5px; font-weight: 800; padding: 3px 10px; border-radius: 6px; text-transform: uppercase;\">CHUYÊN\n          ĐỀ ĐẶC BIỆT</span>\n        <h2\n          style=\"font-family: var(--font-heading); font-size: 22px; font-weight: 800; color: #04154e; margin: 8px 0 0;\">\n          Chuyên Đề Ứng Dụng Thực Hành Thực Tế\n        </h2>\n      </div>\n      <span style=\"font-size: 13px; color: #64748b;\">Đầy đủ tài liệu, bài lab &amp; video hướng dẫn</span>\n    </div>\n\n    <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 24px;\">\n      <!-- Specialization 1: Medical Vibe Coding -->\n      <div\n        style=\"background: #ffffff; border: 1px solid #cbd5e1; border-radius: 16px; padding: 24px; box-shadow: 0 4px 16px rgba(0,0,0,0.03); display: flex; flex-direction: column;\">\n        <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 12px;\">\n          <span style=\"font-size: 24px;\">⚕</span>\n          <h3 style=\"font-family: var(--font-heading); font-size: 17px; font-weight: 700; color: #00346f; margin: 0;\">\n            Vibe Coding Y Khoa (4 Buổi)\n          </h3>\n        </div>\n        <p style=\"font-size: 13px; color: #475569; line-height: 1.6; margin: 0 0 16px; flex: 1;\">\n          Chương trình thực chiến 30% lý thuyết – 70% thực hành: đi từ công thức prompt CRAFT, kết nối 5 mô hình dữ liệu\n          (LocalStorage, Sheets, SQLite, Supabase, AI Proxy) đến thiết kế Bệnh nhân ảo và thuyết trình Demo Day.\n        </p>\n        <div\n          style=\"display: flex; align-items: center; justify-content: space-between; padding-top: 14px; border-top: 1px solid #f1f5f9;\">\n          <span style=\"font-size: 12px; color: #059669; font-weight: 700;\">✓ Trọn bộ 12 hình minh họa</span>\n          <a href=\"#medical-course\"\n            style=\"background: #00346f; color: #ffffff; font-family: var(--font-heading); font-size: 12.5px; font-weight: 700; padding: 8px 16px; border-radius: 8px; text-decoration: none;\">\n            Vào học ngay →\n          </a>\n        </div>\n      </div>\n\n      <!-- Specialization 2: Digitalize 8 Gates -->\n      <div\n        style=\"background: #ffffff; border: 1px solid #cbd5e1; border-radius: 16px; padding: 24px; box-shadow: 0 4px 16px rgba(0,0,0,0.03); display: flex; flex-direction: column;\">\n        <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 12px;\">\n          <span style=\"font-size: 24px;\">🏛</span>\n          <h3 style=\"font-family: var(--font-heading); font-size: 17px; font-weight: 700; color: #4338ca; margin: 0;\">\n            Số Hóa Quy Trình 8 Cổng Kiểm Soát\n          </h3>\n        </div>\n        <p style=\"font-size: 13px; color: #475569; line-height: 1.6; margin: 0 0 16px; flex: 1;\">\n          Guideline chuẩn mực chuyển đổi hồ sơ giấy sang quy trình số: Khảo sát AS-IS, thiết kế TO-BE &amp; SLA, khóa dữ\n          liệu 4 cấp độ, lập ma trận quyền, đặc tả SPEC 10 phần và kiểm thử UAT quyền âm.\n        </p>\n        <div\n          style=\"display: flex; align-items: center; justify-content: space-between; padding-top: 14px; border-top: 1px solid #f1f5f9;\">\n          <span style=\"font-size: 12px; color: #4338ca; font-weight: 700;\">✓ Kèm bộ mẫu tải về</span>\n          <a href=\"#admin-guide\"\n            style=\"background: #4338ca; color: #ffffff; font-family: var(--font-heading); font-size: 12.5px; font-weight: 700; padding: 8px 16px; border-radius: 8px; text-decoration: none;\">\n            Vào học ngay →\n          </a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- STATS BAR -->\n  <section style=\"display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 24px;\">\n    <div\n      style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; padding: 18px; text-align: center;\">\n      <b\n        style=\"font-family: var(--font-heading); font-size: 26px; font-weight: 800; color: #00346f; display: block;\">12</b>\n      <span style=\"font-size: 12px; color: #64748b;\">Chương sách toàn diện</span>\n    </div>\n    <div\n      style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; padding: 18px; text-align: center;\">\n      <b\n        style=\"font-family: var(--font-heading); font-size: 26px; font-weight: 800; color: #0284c7; display: block;\">02</b>\n      <span style=\"font-size: 12px; color: #64748b;\">Chuyên đề thực hành sâu</span>\n    </div>\n    <div\n      style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; padding: 18px; text-align: center;\">\n      <b\n        style=\"font-family: var(--font-heading); font-size: 26px; font-weight: 800; color: #059669; display: block;\">05</b>\n      <span style=\"font-size: 12px; color: #64748b;\">Mô hình kết nối dữ liệu</span>\n    </div>\n    <div\n      style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; padding: 18px; text-align: center;\">\n      <b\n        style=\"font-family: var(--font-heading); font-size: 26px; font-weight: 800; color: #d97706; display: block;\">100%</b>\n      <span style=\"font-size: 12px; color: #64748b;\">An toàn &amp; Dữ liệu giả</span>\n    </div>\n  </section>\n</article>","medical-course":"    <article class=\"ebook-page medical-course\" id=\"medical-course\">\n      <div class=\"part-lead-header\">\n        <span class=\"part-tag\">PHẦN V · CHUYÊN ĐỀ THỰC HÀNH ỨNG DỤNG</span>\n        <h2>Vibe Coding Y Khoa: Lộ Trình 4 Buổi &amp; Kết Nối Dữ Liệu AI</h2>\n        <p>Lộ trình 30% lý thuyết – 70% thực hành: Đi từ câu lệnh prompt đầu tiên, kết nối 5 mô hình dữ liệu thực chiến (LocalStorage, Google Sheets, SQLite, Supabase, AI Proxy) đến một sản phẩm số hoàn chỉnh phục vụ y tế.</p>\n      </div>\n\n      <header class=\"chapter-head medical-course-head\">\n        <div class=\"chapter-badge-num\" style=\"background: linear-gradient(135deg, #0ea5e9, #0284c7);\">⚕</div>\n        <div class=\"chapter-head-info\">\n          <p class=\"chapter-eyebrow\">CHUYÊN ĐỀ ĐẶC BIỆT <span>· 4 BUỔI THỰC HÀNH &amp; KẾT NỐI DỮ LIỆU</span></p>\n          <h2>Lộ Trình Vibe Coding Ứng Dụng Trong Ngành Y Tế</h2>\n          <p class=\"chapter-subtitle\">Dành riêng cho bác sĩ, điều dưỡng, cán bộ quản lý y tế — không cần biết lập trình, chỉ cần tư duy nghiệp vụ và chỉ đạo AI.</p>\n        </div>\n      </header>\n\n      <div class=\"chapter-goal-box\">\n        <b>Mục tiêu chuyên đề:</b>\n        <span>Trang bị trọn bộ kỹ năng chỉ đạo AI Coding Agent (Google Antigravity, Claude Desktop, OpenAI Codex); tự tay làm chủ <strong>5 mô hình kết nối dữ liệu</strong> (LocalStorage, Google Sheets, SQLite, Supabase, AI Backend Proxy); xây dựng 4 ứng dụng y khoa thực tế và xuất bản lên mạng an toàn.</span>\n      </div>\n\n      <div class=\"body\">\n        <!-- TỔNG QUAN KHÓA HỌC -->\n        <section class=\"wide medical-course-intro\">\n          <div>\n            <p class=\"section-kicker\">TRIẾT LÝ TIẾP CẬN THỰC CHIẾN</p>\n            <h3>Học Bằng Một Sản Phẩm Thật Xuyên Suốt 4 Buổi</h3>\n            <p>Không dạy lý thuyết hàn lâm hay bắt bạn học viết từng dòng mã phức tạp. Khóa học tập trung vào <strong>năng lực giải quyết bài toán nghiệp vụ y khoa</strong> bằng cách đóng vai \"Kiến trúc sư\", chỉ huy AI viết mã và kiểm soát kết quả.</p>\n            <ul>\n              <li><strong>Đối tượng phù hợp:</strong> Bác sĩ, Dược sĩ, Điều dưỡng, Cán bộ phòng Kế hoạch tổng hợp, Đào tạo, Tổ chức cán bộ, Công nghệ thông tin bệnh viện.</li>\n              <li><strong>Yêu cầu đầu vào:</strong> Chỉ cần kỹ năng tin học văn phòng cơ bản (Word, Excel) và tư duy logic nghiệp vụ.</li>\n              <li><strong>Ranh giới đạo đức &amp; an toàn:</strong> Tuyệt đối không đưa hồ sơ bệnh nhân thật hoặc dữ liệu nhạy cảm lên AI công cộng; 100% bài thực hành sử dụng dữ liệu giả lập (Mock data).</li>\n            </ul>\n          </div>\n          <figure class=\"medical-figure portrait\">\n            <img src=\"assets/medical-course/medical-course-1.webp\" alt=\"Quy trình Vibe Coding 7 bước từ seed prompt đến deploy\" loading=\"lazy\" decoding=\"async\">\n            <figcaption><em>Hình M.1:</em> Quy trình Vibe Coding 7 bước trong y khoa: Xác định bài toán → Prompt hạt giống → Bổ sung ngữ cảnh → Tinh chỉnh giao diện → Kiểm thử → Vá lỗi → Xuất bản.</figcaption>\n          </figure>\n        </section>\n\n        <!-- MA TRẬN SO SÁNH 3 CÔNG CỤ TRONG Y KHOA -->\n        <section class=\"wide\">\n          <h3>Bản Đồ Công Cụ AI Agent Phục Vụ Ngành Y</h3>\n          <div class=\"medical-media-pair\">\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-2.webp\" alt=\"So sánh 3 công cụ Claude Desktop, Antigravity và Codex trong y khoa\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><em>Hình M.2:</em> Tam mã AI Agent: Claude Desktop (nghiên cứu &amp; tra cứu sâu), Antigravity (phát triển app toàn diện đa file) và Codex (tự động hóa script &amp; xử lý dữ liệu).</figcaption>\n            </figure>\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-3.webp\" alt=\"Cấu trúc thư mục Workspace y khoa chuẩn\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><em>Hình M.3:</em> Cấu trúc Workspace y tế an toàn: SPEC.md (đặc tả), DU_LIEU_MAU.json (dữ liệu giả), AGENTS.md (luật bảo vệ PII) và code ứng dụng.</figcaption>\n            </figure>\n          </div>\n        </section>\n\n        <!-- LỘ TRÌNH TỔNG QUAN 4 BUỔI -->\n        <section class=\"wide\">\n          <h3>Lộ Trình 4 Buổi Thực Hành &amp; Sản Phẩm Đầu Ra Cụ Thể</h3>\n          <div class=\"medical-session-grid\">\n            <article>\n              <span>BUỔI 1</span>\n              <h4>Nhập Môn &amp; Claude Desktop</h4>\n              <p>Học công thức Prompt CRAFT chuyên ngành y; tạo Quiz giải phẫu, công cụ tra cứu phác đồ hoặc máy tính sinh hiệu y học.</p>\n              <b>Đầu ra: Ứng dụng đơn trang đầu tay</b>\n            </article>\n            <article>\n              <span>BUỔI 2</span>\n              <h4>Tự Động Hóa &amp; Quản Lý Nội Bộ</h4>\n              <p>Ứng dụng MCP kết nối dữ liệu: Tự động hóa xếp lịch trực khoa phòng, soạn thảo công văn hành chính, cảnh báo trùng lịch giảng.</p>\n              <b>Đầu ra: Công cụ văn phòng dùng được ngay</b>\n            </article>\n            <article>\n              <span>BUỔI 3</span>\n              <h4>Kết Nối Dữ Liệu &amp; Tích Hợp AI</h4>\n              <p>Làm chủ 5 mô hình dữ liệu (LocalStorage, Google Sheets, SQLite, Supabase, AI Proxy); xây dựng Cổng tiếp nhận &amp; Bệnh nhân ảo.</p>\n              <b>Đầu ra: Web App tương tác có lưu trữ</b>\n            </article>\n            <article>\n              <span>BUỔI 4</span>\n              <h4>Bảo Mật, UAT &amp; Demo Day</h4>\n              <p>Rà soát an toàn thông tin (Luật 2025), chạy 8 ca kiểm thử UAT, đóng gói đưa lên mạng (Vercel/Netlify) và thuyết trình Demo 5 phút.</p>\n              <b>Đầu ra: Sản phẩm hoàn chỉnh lên Internet</b>\n            </article>\n          </div>\n        </section>\n\n        <!-- BUỔI 1: CRAFT PROMPT & QUIZ GIẢNG DẠY -->\n        <section class=\"wide medical-split\">\n          <figure class=\"medical-figure landscape\">\n            <img src=\"assets/medical-course/medical-course-4.webp\" alt=\"Công thức prompt CRAFT cho ngành y\" loading=\"lazy\" decoding=\"async\">\n            <figcaption><em>Hình M.4:</em> Công thức CRAFT: Context (Bối cảnh y tế) → Role (Vai trò chuyên gia) → Action (Hành động cụ thể) → Format (Định dạng đầu ra) → Tone (Văn phong chuẩn mực).</figcaption>\n          </figure>\n          <div>\n            <p class=\"section-kicker\">BUỔI 1 · KỸ NĂNG CỐT LÕI</p>\n            <h3>Công Thức Prompt CRAFT Cho Y Khoa</h3>\n            <p>Để AI không suy diễn sai lệch trong bối cảnh y tế, mọi câu lệnh cần tuân thủ 5 thành tố CRAFT:</p>\n            <ol>\n              <li><strong>Context (Bối cảnh):</strong> Khoa Khám bệnh / Phòng Kế hoạch tổng hợp tại bệnh viện hạng I.</li>\n              <li><strong>Role (Vai trò):</strong> Giảng viên bộ môn Giải phẫu / Chuyên viên phân tích số liệu y tế.</li>\n              <li><strong>Action (Hành động):</strong> Tạo một ứng dụng web trắc nghiệm 10 câu giải phẫu hệ tim mạch, có giải thích đáp án chi tiết khi học viên bấm chọn.</li>\n              <li><strong>Format (Định dạng):</strong> Một file HTML duy nhất chứa sẵn CSS và JS, có thể mở trực tiếp bằng trình duyệt không cần cài đặt.</li>\n              <li><strong>Tone (Văn phong):</strong> Khoa học, chuẩn mực thuật ngữ Bộ Y tế, thân thiện với người học.</li>\n            </ol>\n          </div>\n        </section>\n\n        <!-- BA NHÓM BÀI LAB THỰC HÀNH -->\n        <section class=\"wide\">\n          <h3>Ba Nhóm Bài Lab Thực Hành Sát Với Thực Tế Phòng Ban</h3>\n          <div class=\"medical-lab-grid\">\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-5.webp\" alt=\"Giao diện ngân hàng câu hỏi nội khoa\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><strong>Nhóm 1 — Đào tạo &amp; Giảng dạy:</strong> Ngân hàng câu hỏi trắc nghiệm, bài tập giải phẫu, chấm điểm tự động và giải thích ca bệnh cho sinh viên y khoa.</figcaption>\n            </figure>\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-6.webp\" alt=\"Công cụ quản lý lịch trực khoa phòng\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><strong>Nhóm 2 — Quản trị &amp; Phân ca:</strong> Xếp lịch trực khoa phòng tự động, phân ca trực đêm, cảnh báo vi phạm định mức giờ làm và chia sẻ lịch online.</figcaption>\n            </figure>\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-10.webp\" alt=\"Công cụ tạo công văn mới\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><strong>Nhóm 3 — Hành chính y tế:</strong> Soạn thảo công văn báo cáo, biểu mẫu thẩm định quy trình, kiểm tra văn bản theo Nghị định 310/2026/NĐ-CP.</figcaption>\n            </figure>\n          </div>\n        </section>\n\n        <!-- ================================================================= -->\n        <!-- BUỔI 3 CHUYÊN SÂU: KẾT NỐI DỮ LIỆU & AI CHO VIBE CODING -->\n        <!-- ================================================================= -->\n        <section class=\"wide\" style=\"background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 16px; padding: 28px; margin: 24px 0;\">\n          <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 12px;\">\n            <span style=\"background: #0284c7; color: #fff; font-weight: 800; font-size: 11px; padding: 4px 10px; border-radius: 6px;\">BUỔI 3 TRỌNG TÂM</span>\n            <h3 style=\"margin: 0; font-size: 20px; color: #0f172a;\">Năm Mô Hình Kết Nối Dữ Liệu &amp; Tích Hợp AI Thực Chiến</h3>\n          </div>\n          <p style=\"font-size: 14px; color: #475569; line-height: 1.6; margin-bottom: 20px;\">\n            \"Vibe coding đúng là điều khiển được luồng dữ liệu — không chỉ tạo được giao diện\". Tùy thuộc vào quy mô và độ nhạy cảm của dữ liệu y tế, học viên lựa chọn 1 trong 5 mô hình kiến trúc chuẩn dưới đây:\n          </p>\n\n          <!-- 5 KIẾN TRÚC DỮ LIỆU -->\n          <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-bottom: 24px;\">\n            <!-- MÔ HÌNH 00 -->\n            <div style=\"background: #ffffff; border: 1px solid #cbd5e1; border-top: 4px solid #64748b; border-radius: 12px; padding: 18px;\">\n              <span style=\"font-family: var(--font-mono); font-size: 10px; font-weight: 800; color: #64748b; background: #f1f5f9; padding: 2px 6px; border-radius: 4px;\">00 · LOCALSTORAGE</span>\n              <h4 style=\"margin: 8px 0 6px; font-size: 15px; color: #0f172a;\">Lưu Cục Bộ Trình Duyệt</h4>\n              <p style=\"font-size: 12.5px; color: #475569; line-height: 1.5; margin-bottom: 8px;\">• <strong>Cách thức:</strong> <code>Form → JSON.stringify() → LocalStorage</code>. Tải lại trang (F5) tự động phục hồi dữ liệu.<br>• <strong>Ưu điểm:</strong> Không cần backend, chạy offline 100%, bảo mật tuyệt đối trên máy cá nhân.<br>• <strong>Hạn chế:</strong> Chỉ dùng trên 1 thiết bị, xóa lịch sử duyệt web là mất.</p>\n              <span style=\"font-size: 11.5px; color: #0369a1; font-weight: 700;\">Phù hợp: Quiz giải phẫu, Bảng tính liều thuốc cá nhân.</span>\n            </div>\n\n            <!-- MÔ HÌNH 01 -->\n            <div style=\"background: #ffffff; border: 1px solid #cbd5e1; border-top: 4px solid #10b981; border-radius: 12px; padding: 18px;\">\n              <span style=\"font-family: var(--font-mono); font-size: 10px; font-weight: 800; color: #059669; background: #ecfdf5; padding: 2px 6px; border-radius: 4px;\">01 · GOOGLE SHEETS</span>\n              <h4 style=\"margin: 8px 0 6px; font-size: 15px; color: #0f172a;\">Form Web → Apps Script</h4>\n              <p style=\"font-size: 12.5px; color: #475569; line-height: 1.5; margin-bottom: 8px;\">• <strong>Cách thức:</strong> Form HTML gửi POST đến Google Apps Script (<code>doPost</code>), tự động ghi 1 dòng 5 cột vào Sheet.<br>• <strong>Ưu điểm:</strong> Nhân viên phòng ban xem và lọc trực tiếp trên Excel/Sheets quen thuộc.<br>• <strong>Hạn chế:</strong> Giới hạn tần suất gọi API, không phù hợp dữ liệu bảo mật cao.</p>\n              <span style=\"font-size: 11.5px; color: #059669; font-weight: 700;\">Phù hợp: Đăng ký lịch học, Khảo sát ý kiến, Tiếp nhận đề xuất.</span>\n            </div>\n\n            <!-- MÔ HÌNH 02 -->\n            <div style=\"background: #ffffff; border: 1px solid #cbd5e1; border-top: 4px solid #0284c7; border-radius: 12px; padding: 18px;\">\n              <span style=\"font-family: var(--font-mono); font-size: 10px; font-weight: 800; color: #0284c7; background: #f0f9ff; padding: 2px 6px; border-radius: 4px;\">02 · NODE SQLITE</span>\n              <h4 style=\"margin: 8px 0 6px; font-size: 15px; color: #0f172a;\">Backend Nhẹ SQLite</h4>\n              <p style=\"font-size: 12.5px; color: #475569; line-height: 1.5; margin-bottom: 8px;\">• <strong>Cách thức:</strong> Dùng <code>node:sqlite</code> tích hợp sẵn trong Node.js (>=22.13), lưu vào file <code>data/noi-bo.db</code>.<br>• <strong>Ưu điểm:</strong> Dữ liệu cô lập trong mạng LAN bệnh viện, backup chỉ cần copy file <code>.db</code>.<br>• <strong>Hạn chế:</strong> Cần máy chủ nội bộ hoặc container chạy backend.</p>\n              <span style=\"font-size: 11.5px; color: #0284c7; font-weight: 700;\">Phù hợp: Quản lý khoa phòng, Sổ nhật ký trực nội bộ.</span>\n            </div>\n\n            <!-- MÔ HÌNH 03 -->\n            <div style=\"background: #ffffff; border: 1px solid #cbd5e1; border-top: 4px solid #8b5cf6; border-radius: 12px; padding: 18px;\">\n              <span style=\"font-family: var(--font-mono); font-size: 10px; font-weight: 800; color: #7c3aed; background: #f5f3ff; padding: 2px 6px; border-radius: 4px;\">03 · SUPABASE RLS</span>\n              <h4 style=\"margin: 8px 0 6px; font-size: 15px; color: #0f172a;\">Postgres Cloud + RLS</h4>\n              <p style=\"font-size: 12.5px; color: #475569; line-height: 1.5; margin-bottom: 8px;\">• <strong>Cách thức:</strong> Kết nối qua Supabase SDK, bật Anonymous Auth, bắt buộc cài đặt <strong>Row Level Security (RLS)</strong>.<br>• <strong>Ưu điểm:</strong> Đồng bộ realtime đa người dùng, cloud phân quyền chặt chẽ (Phiên B không thấy dòng của Phiên A).<br>• <strong>Hạn chế:</strong> Đòi hỏi hiểu về chính sách bảo mật dữ liệu đám mây.</p>\n              <span style=\"font-size: 11.5px; color: #7c3aed; font-weight: 700;\">Phù hợp: Ứng dụng liên khoa phòng, Hội chẩn từ xa.</span>\n            </div>\n\n            <!-- MÔ HÌNH 04 -->\n            <div style=\"background: #ffffff; border: 1px solid #cbd5e1; border-top: 4px solid #f59e0b; border-radius: 12px; padding: 18px;\">\n              <span style=\"font-family: var(--font-mono); font-size: 10px; font-weight: 800; color: #d97706; background: #fffbeb; padding: 2px 6px; border-radius: 4px;\">04 · AI BACKEND PROXY</span>\n              <h4 style=\"margin: 8px 0 6px; font-size: 15px; color: #0f172a;\">Tích Hợp AI Qua Proxy An Toàn</h4>\n              <p style=\"font-size: 12.5px; color: #475569; line-height: 1.5; margin-bottom: 8px;\">• <strong>Cách thức:</strong> Browser gọi <code>POST /api/draft</code>. Backend giữ bí mật API Key, kiểm soát độ dài đầu vào (3–80 ký tự), gọi AI và trả kết quả BẢN NHÁP.<br>• <strong>Quy tắc thép:</strong> Bật <code>MOCK_AI=true</code> kiểm thử trước; Tuyệt đối không để lộ key trên frontend; Bác sĩ là người duyệt cuối.</p>\n              <span style=\"font-size: 11.5px; color: #d97706; font-weight: 700;\">Phù hợp: Trợ lý soạn thảo báo cáo, Gợi ý checklist trạm y tế.</span>\n            </div>\n          </div>\n\n          <!-- BỘ PROMPT BUỔI 3 -->\n          <h4 style=\"font-size: 16px; color: #0f172a; margin: 20px 0 12px;\">Thư Viện Prompt Mẫu Chuẩn Cho Buổi 3 (Sao Chép 1-Chạm)</h4>\n          <div class=\"prompt-grid\">\n            <details open>\n              <summary><span>P0</span>Prompt Mở Đầu: Khảo sát kiến trúc trước khi code</summary>\n              <div>\n                <p id=\"p-b3-0\">Bạn là trợ giảng vibe coding cho người mới. Hãy đọc README và các file trong folder hiện tại. Chưa sửa file, chưa chạy lệnh ghi dữ liệu. Hãy trả lời ngắn: 1) Luồng frontend → backend/dịch vụ → nơi lưu; 2) File nào cần cấu hình; 3) Ba bước chạy nhỏ nhất; 4) Dữ liệu giả lập nào sẽ được tạo; 5) Rủi ro key, quyền hoặc dữ liệu nhạy cảm.</p>\n                <button class=\"copy\" data-copy=\"p-b3-0\">Sao chép prompt</button>\n              </div>\n            </details>\n\n            <details>\n              <summary><span>P1</span>Prompt LocalStorage: Lưu trữ an toàn, chống crash</summary>\n              <div>\n                <p id=\"p-b3-1\">Chỉ làm trong folder 00-localstorage. Giữ đúng 2 trường: station và readiness. Không thêm backend, tài khoản, thư viện hoặc dữ liệu người bệnh. Hãy giải thích ngắn rồi kiểm tra: 1) dữ liệu được JSON.stringify trước khi lưu; 2) tải lại trang vẫn thấy bản ghi; 3) dữ liệu lỗi không làm app dừng (bọc try-catch); 4) nút xóa có xác nhận. Cho tôi diff ngắn và cách xem Local Storage trong DevTools.</p>\n                <button class=\"copy\" data-copy=\"p-b3-1\">Sao chép prompt</button>\n              </div>\n            </details>\n\n            <details>\n              <summary><span>P2</span>Prompt Google Sheets: Khớp form 3 trường vào Sheet 5 cột</summary>\n              <div>\n                <p id=\"p-b3-2\">Chỉ làm trong folder 01-google-sheets-appscript. Giữ form đúng 3 trường: maNhom, tram, ca. Kiểm tra app.js và Code.gs có cùng tên trường. Không thêm họ tên, mã định danh. Nêu điểm chưa khớp trước khi sửa. Sau khi sửa: cho diff ngắn và checklist kiểm tra: form gửi thành công, sheet YeuCau có dòng mới 5 cột, trạng thái mặc định là 'Mới'. Tôi tự điền SPREADSHEET_ID.</p>\n                <button class=\"copy\" data-copy=\"p-b3-2\">Sao chép prompt</button>\n              </div>\n            </details>\n\n            <details>\n              <summary><span>P3</span>Prompt SQLite Backend: REST API với node:sqlite</summary>\n              <div>\n                <p id=\"p-b3-3\">Chỉ làm trong folder 02-sqlite-backend. Tôi dùng Node >=22.13 và pnpm. Không thêm thư viện SQLite bên ngoài, sử dụng node:sqlite tích hợp. Hãy giúp tôi chạy app để: 1) GET /api/checks trả danh sách JSON; 2) POST /api/checks nhận station và result; 3) Tải lại trang vẫn còn dữ liệu. Cho lệnh chạy, lệnh curl kiểm tra và vị trí file .db. Không xóa database nếu chưa hỏi tôi.</p>\n                <button class=\"copy\" data-copy=\"p-b3-3\">Sao chép prompt</button>\n              </div>\n            </details>\n\n            <details>\n              <summary><span>P4</span>Prompt Supabase Cloud: Bật RLS &amp; Khóa quyền dữ liệu</summary>\n              <div>\n                <p id=\"p-b3-4\">Chỉ làm trong folder 03-supabase. Dữ liệu chỉ có trường title là ý tưởng mô phỏng. Hãy hướng dẫn từng bước: chạy schema.sql, bật Anonymous Auth, điền Project URL và anon key vào config.js. Không tắt RLS. Không dùng service_role key ở frontend. Hướng dẫn tôi mở hai cửa sổ ẩn danh thử nghiệm: phiên B tuyệt đối không được thấy dữ liệu của phiên A.</p>\n                <button class=\"copy\" data-copy=\"p-b3-4\">Sao chép prompt</button>\n              </div>\n            </details>\n\n            <details>\n              <summary><span>P5</span>Prompt AI Proxy: Chạy Mock trước, giấu API Key ở Backend</summary>\n              <div>\n                <p id=\"p-b3-5\">Chỉ làm trong folder 04-ai-api-key. Đầu tiên giữ MOCK_AI=true, không cần API key thật. Giúp tôi chạy app và kiểm tra POST /api/draft với tên trạm giả lập. Đầu vào phải giới hạn 3–80 ký tự; đầu ra ghi rõ BẢN NHÁP. Sau khi mock đạt, giải thích cách cấu hình AI key ở backend qua biến môi trường .env. Không đặt key trong frontend hoặc Git. Không gửi dữ liệu bệnh nhân thật.</p>\n                <button class=\"copy\" data-copy=\"p-b3-5\">Sao chép prompt</button>\n              </div>\n            </details>\n\n            <details>\n              <summary><span>P6</span>Prompt Chẩn đoán &amp; Sửa lỗi kỹ thuật (1 Giả thuyết duy nhất)</summary>\n              <div>\n                <p id=\"p-b3-6\">Tôi đang ở folder [...]. Bước vừa làm: [...]. Kỳ vọng: [...]. Thực tế: [...]. Lỗi nguyên văn đã xóa key/URL: [...]. Hãy: 1) Nêu một nguyên nhân có khả năng cao nhất; 2) Chỉ đề xuất duy nhất một phép kiểm tra; 3) Nếu xác nhận đúng mới sửa tối thiểu; 4) Cho lệnh hoặc thao tác kiểm tra lại; 5) Không xóa dữ liệu và không tắt bảo mật.</p>\n                <button class=\"copy\" data-copy=\"p-b3-6\">Sao chép prompt</button>\n              </div>\n            </details>\n          </div>\n\n          <!-- 4 TÍNH NĂNG AI TRỢ LÝ Y KHOA & TEST CASE BUỔI 3 -->\n          <div style=\"margin-top: 24px; padding-top: 20px; border-top: 1px solid #cbd5e1;\">\n            <h4 style=\"font-size: 16px; color: #0f172a; margin: 0 0 12px;\">Bốn Tính Năng AI Trợ Lý Có Kiểm Soát (Mô Hình Ứng Dụng Đại Học Y Dược TP.HCM)</h4>\n            <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; margin-bottom: 20px;\">\n              <div style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px;\">\n                <b style=\"color: #0284c7; font-size: 13px; display: block; margin-bottom: 4px;\">1. AI Tóm tắt văn bản</b>\n                <p style=\"font-size: 12px; color: #475569; margin: 0; line-height: 1.45;\">Báo cáo 5 trang → AI trích xuất 3 ý chính: Mục đích, Đơn vị đề xuất, Nội dung trọng tâm.</p>\n              </div>\n              <div style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px;\">\n                <b style=\"color: #059669; font-size: 13px; display: block; margin-bottom: 4px;\">2. AI Kiểm tra thành phần</b>\n                <p style=\"font-size: 12px; color: #475569; margin: 0; line-height: 1.45;\">Tự động kiểm tra đủ 5/5 tài liệu đính kèm theo quy định trước khi cho phép bấm gửi.</p>\n              </div>\n              <div style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px;\">\n                <b style=\"color: #7c3aed; font-size: 13px; display: block; margin-bottom: 4px;\">3. AI Phân loại hồ sơ</b>\n                <p style=\"font-size: 12px; color: #475569; margin: 0; line-height: 1.45;\">Đọc trích yếu → Tự động gắn thẻ chuyên môn (<em>Đào tạo CME, NCKH, Tài chính, Hành chính</em>).</p>\n              </div>\n              <div style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 14px;\">\n                <b style=\"color: #d97706; font-size: 13px; display: block; margin-bottom: 4px;\">4. AI Dự thảo phản hồi</b>\n                <p style=\"font-size: 12px; color: #475569; margin: 0; line-height: 1.45;\">Tạo sẵn khung thư trả lời kết quả thẩm định; bác sĩ/chuyên viên duyệt trước khi phát hành.</p>\n              </div>\n            </div>\n\n            <!-- BẢNG TESTCASE BUỔI 3 -->\n            <h5 style=\"font-size: 13.5px; color: #0f172a; margin: 0 0 8px;\">Khung Bảng Ghi Nhận Kiểm Thử Thực Hành Buổi 3 (Test Case Matrix)</h5>\n            <div class=\"mini-table\" style=\"grid-template-columns: 0.5fr 1fr 1fr 1fr 0.5fr; min-width: 600px; overflow-x: auto;\">\n              <b>STT</b><b>Kịch bản kiểm thử</b><b>Dữ liệu đầu vào</b><b>Kết quả mong đợi</b><b>Đánh giá</b>\n              <span>01</span><span>Tạo hồ sơ bình thường</span><span>Nguyễn Văn A, Khoa Nội</span><span>Lưu thành công, trạng thái \"Mới tạo\"</span><span style=\"color: #16a34a; font-weight: 700;\">✓ ĐẠT</span>\n              <span>02</span><span>Để trống trường bắt buộc</span><span>Họ tên: \"\" (rỗng)</span><span>Báo lỗi \"Bắt buộc nhập Họ tên\", không gửi</span><span style=\"color: #16a34a; font-weight: 700;\">✓ ĐẠT</span>\n              <span>03</span><span>Duyệt hồ sơ &amp; Ghi log</span><span>Hồ sơ #01, Role: Lãnh đạo</span><span>Chuyển \"ĐÃ DUYỆT\", thêm 1 dòng Audit log</span><span style=\"color: #16a34a; font-weight: 700;\">✓ ĐẠT</span>\n              <span>04</span><span>Gọi AI tóm tắt hồ sơ</span><span>Văn bản mẫu 500 từ</span><span>Trả về bản tóm tắt 3 câu chính xác</span><span style=\"color: #16a34a; font-weight: 700;\">✓ ĐẠT</span>\n            </div>\n          </div>\n        </section>\n\n        <!-- BUỔI 3 TIẾP TỤC: BỆNH NHÂN ẢO & MÔ PHỎNG LÂM SÀNG -->\n        <section class=\"wide\">\n          <h3>Mô Phỏng Lâm Sàng: Ứng Dụng \"Bệnh Nhân Ảo\" Tương Tác</h3>\n          <div class=\"medical-media-pair\">\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-11.webp\" alt=\"Bệnh nhân ảo luyện tập lâm sàng\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><em>Hình M.5:</em> Ứng dụng \"Bệnh nhân ảo\" mô phỏng hỏi bệnh, khám thực thể, xem kết quả cận lâm sàng và đưa ra phác đồ điều trị có chấm điểm logic.</figcaption>\n            </figure>\n            <div>\n              <p class=\"section-kicker\">BUỔI 3 · SẢN PHẨM NÂNG CAO</p>\n              <h4>Cách Xây Dựng Ứng Dụng Bệnh Nhân Ảo Với Google Stitch</h4>\n              <p>Học viên chỉ cần tải kịch bản ca bệnh lâm sàng mẫu (ví dụ: Cơn đau thắt ngực không ổn định) và dùng prompt chỉ đạo AI tạo ra ứng dụng tương tác:</p>\n              <ul>\n                <li>Bệnh nhân trả lời theo từng câu hỏi của bác sĩ thực tập.</li>\n                <li>Hệ thống hiển thị hình ảnh điện tâm đồ (ECG) và kết quả xét nghiệm Troponin giả lập.</li>\n                <li>Đánh giá quyết định xử trí cấp cứu của học viên và đưa ra lời khuyên theo phác đồ khuyến cáo.</li>\n              </ul>\n            </div>\n          </div>\n        </section>\n\n        <!-- BUỔI 4: BẢO MẬT & LUẬT DỮ LIỆU CÁ NHÂN -->\n        <section class=\"wide medical-safety\">\n          <div>\n            <p class=\"section-kicker\">AN TOÀN THÔNG TIN LÀ ĐIỀU KIỆN TIÊN QUYẾT</p>\n            <h3>Bốn Lớp Bảo Vệ Dữ Liệu Y Tế (Tuân Thủ Luật BV DLCN 2025)</h3>\n            <p>Dữ liệu y tế và sức khỏe thuộc nhóm <strong>Dữ liệu cá nhân nhạy cảm</strong> theo quy định của pháp luật Việt Nam. Khi ứng dụng AI trong bệnh viện, bắt buộc phải thiết lập 4 lớp rào chắn:</p>\n            <ul>\n              <li><strong>Lớp 1 — Mạng &amp; Truy cập:</strong> Bắt buộc dùng kết nối mã hóa HTTPS, chứng thực người dùng và phân quyền tối thiểu (Least Privilege).</li>\n              <li><strong>Lớp 2 — Ứng dụng:</strong> Khử độc dữ liệu nhập vào (chống XSS), ghi nhật ký kiểm toán bất biến (Audit Log: Ai, Lúc nào, Thao tác gì).</li>\n              <li><strong>Lớp 3 — Dữ liệu:</strong> Ẩn danh hóa (Anonymization), che số điện thoại (`090****123`), tuyệt đối không lưu CCCD hay bệnh án thật.</li>\n              <li><strong>Lớp 4 — Lưu trữ an toàn:</strong> Bọc hàm `try...catch` khi đọc LocalStorage, tự phục hồi dữ liệu khi người dùng bấm F5 hoặc mở lại máy.</li>\n            </ul>\n            <div class=\"medical-warning\"><strong>QUY TẮC BẤT DI BẤT DỊCH:</strong> Không dùng dữ liệu bệnh nhân thật trong bất kỳ bài thực hành hay sản phẩm thử nghiệm nào. Toàn bộ dữ liệu demo phải là dữ liệu giả lập hư cấu 100%.</div>\n          </div>\n          <figure class=\"medical-figure portrait\">\n            <img src=\"assets/medical-course/medical-course-7.webp\" alt=\"Bốn lớp bảo mật dữ liệu y tế\" loading=\"lazy\" decoding=\"async\">\n            <figcaption><em>Hình M.6:</em> Sơ đồ 4 lớp bảo mật dữ liệu y tế: Mạng &amp; Truy cập → Ứng dụng &amp; Kiểm soát → Dữ liệu &amp; Mã hóa → Pháp lý &amp; Quy chuẩn.</figcaption>\n          </figure>\n        </section>\n\n        <!-- BUỔI 4: KIỂM THỬ UAT & QUY TRÌNH TỰ ĐỘNG HÓA -->\n        <section class=\"wide\">\n          <h3>Kiểm Thử Trước Khi Bàn Giao &amp; Tự Động Hóa Quy Trình</h3>\n          <div class=\"medical-media-pair\">\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-8.webp\" alt=\"Quy trình kiểm thử người dùng cho ứng dụng y tế\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><em>Hình M.7:</em> Quy trình kiểm thử người dùng (UAT): Chuẩn bị kịch bản → Quan sát thao tác thực tế → Ghi nhận phản hồi → Tối ưu giao diện.</figcaption>\n            </figure>\n            <figure class=\"medical-figure\">\n              <img src=\"assets/medical-course/medical-course-9.webp\" alt=\"Quy trình tự động hóa email lịch hẹn và biểu mẫu\" loading=\"lazy\" decoding=\"async\">\n              <figcaption><em>Hình M.8:</em> Tự động hóa quy trình y tế: Bệnh nhân đăng ký → AI xác thực biểu mẫu → Tự động cập nhật danh sách và xuất phiếu hẹn có mã tiếp nhận.</figcaption>\n            </figure>\n          </div>\n        </section>\n\n        <!-- DEMO DAY & TIÊU CHÍ HOÀN THÀNH -->\n        <section class=\"wide medical-final\">\n          <figure class=\"medical-figure landscape\">\n            <img src=\"assets/medical-course/medical-course-12.webp\" alt=\"Cây quyết định chọn giải pháp AI\" loading=\"lazy\" decoding=\"async\">\n            <figcaption><em>Hình M.9:</em> Cây quyết định chọn giải pháp: Khi nào chỉ cần Prompt đơn lẻ, khi nào cần Web App, khi nào cần Workflow tự động và khi nào cần Hệ thống Multi-Agent.</figcaption>\n          </figure>\n          <div>\n            <p class=\"section-kicker\">FINAL PROJECT &amp; DEMO DAY</p>\n            <h3>Tiêu Chí Nghiệm Thu Sản Phẩm Cuối Khóa</h3>\n            <p>Mỗi học viên / nhóm học viên sẽ trình bày sản phẩm số của mình trong buổi Demo Day theo 4 tiêu chí chuẩn hóa:</p>\n            <ul>\n              <li><strong>Tính thực tiễn:</strong> Giải quyết được ít nhất 1 bài toán có thật tại khoa phòng hoặc đơn vị công tác.</li>\n              <li><strong>Hoạt động trơn tru:</strong> Có ít nhất 3 tính năng tương tác hoàn chỉnh, không có lỗi đứng trang hay lỗi console.</li>\n              <li><strong>Địa chỉ trực tuyến (URL):</strong> Ứng dụng đã được xuất bản lên Internet qua Netlify Drop hoặc Vercel để mọi người mở dùng thử trên điện thoại.</li>\n              <li><strong>Thuyết trình 5 phút:</strong> Báo cáo theo cấu trúc chuẩn: <em>Vấn đề ban đầu → Giải pháp ứng dụng → Thao tác trực tiếp (Live demo) → Hướng mở rộng tiếp theo.</em></li>\n            </ul>\n          </div>\n        </section>\n      </div>\n\n      <footer class=\"chapter-footer-seamless\">\n        <nav class=\"seamless-bottom-nav\">\n          <a href=\"#appendix-c\" class=\"nav-link-prev\">\n            <small>← QUAY LẠI</small>\n            <span>Phụ lục C: Bộ Starter Kit</span>\n          </a>\n          <a href=\"#admin-guide\" class=\"nav-link-next\">\n            <small>CHUYÊN ĐỀ TIẾP THEO →</small>\n            <span>Chuyên đề: Số hóa quy trình 8 cổng</span>\n          </a>\n        </nav>\n      </footer>\n    </article>\n"};
